// Real-Life Scenarios content: 27 original branching conversations (13 for grades 3-5, 14 for grades 6-8). One scene per line.
// Schema: see tools/access-scenarios.test.mjs (every scene is checked for reachability, three choices per turn, tags, Spanish and length).
export const SCENES = [
  {"id":"s35-late-pass","b":"3-5","title":"Late to school","titleEs":"Llegar tarde a la escuela","place":"office","goal":"Get a late pass from the school office.","goalEs":"Conseguir un pase de tardanza en la oficina de la escuela.","focus":["greet","apologize","request"],"npc":{"name":"Ms. Rivera","role":"school secretary","roleEs":"secretaria de la escuela","look":{"skin":"#c68642","hair":"#2b1b12","style":"bun","shirt":"#2f6f9f","acc":"glasses"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"Good morning. You look like you are in a hurry. What do you need?","sayEs":"Buenos días. Parece que tienes prisa. ¿Qué necesitas?","mood":"neutral","choices":[{"id":"a","say":"Hello. I need late pass.","sayEs":"Hola. Necesito pase de tardanza.","tag":"request","q":1,"why":"She understands what you need. Add 'a' and 'please' to sound more polite.","whyEs":"Ella entiende lo que necesitas. Agrega 'a' y 'please' para sonar más amable.","next":"n3"},{"id":"b","say":"Good morning, Ms. Rivera. I need a little help, please.","sayEs":"Buenos días, Sra. Rivera. Necesito un poco de ayuda, por favor.","tag":"greet","q":2,"why":"You greeted her by name and asked kindly. A warm start makes the listener want to help you.","whyEs":"La saludaste por su nombre y pediste con amabilidad. Un inicio cálido hace que quieran ayudarte.","next":"n2"},{"id":"c","say":"Pass. Now.","sayEs":"Pase. Ya.","tag":"request","q":0,"why":"Two words sound like an order. Without 'please' or a full sentence, the listener may feel disrespected.","whyEs":"Dos palabras suenan como una orden. Sin 'please' ni una oración completa, la persona puede sentirse irrespetada.","next":"n4"}]},"n2":{"who":"npc","say":"Good morning! Of course I can help you. What is the problem?","sayEs":"¡Buenos días! Claro que te puedo ayudar. ¿Cuál es el problema?","mood":"happy","choices":[{"id":"a","say":"It is not my fault.","sayEs":"No es mi culpa.","tag":"explain","q":0,"why":"This sounds defensive and skips the apology. The listener may feel you are blaming her.","whyEs":"Esto suena a la defensiva y omite la disculpa. La persona puede sentir que la culpas.","next":"n4"},{"id":"b","say":"Sorry. Bus late.","sayEs":"Perdón. Autobús tarde.","tag":"apologize","q":1,"why":"She can guess your meaning. Use full sentences, like 'I am sorry. The bus was late.'","whyEs":"Ella puede adivinar lo que quieres decir. Usa oraciones completas: 'I am sorry. The bus was late.'","next":"n5"},{"id":"c","say":"I am sorry I am late. My bus came late today.","sayEs":"Lamento llegar tarde. Mi autobús llegó tarde hoy.","tag":"apologize","q":2,"why":"You said 'I am sorry' and gave a clear reason. That shows respect and helps her understand.","whyEs":"Dijiste 'I am sorry' y diste una razón clara. Eso muestra respeto y la ayuda a entender.","next":"n5"}]},"n3":{"who":"npc","say":"A late pass? I can write one. Why are you late today?","sayEs":"¿Un pase de tardanza? Te puedo escribir uno. ¿Por qué llegaste tarde hoy?","mood":"puzzled","choices":[{"id":"a","say":"My bus was late because there was a lot of traffic.","sayEs":"Mi autobús llegó tarde porque había mucho tráfico.","tag":"explain","q":2,"why":"You used 'because' to give a clear reason. Reasons help the listener understand your situation.","whyEs":"Usaste 'because' para dar una razón clara. Las razones ayudan a la persona a entender tu situación.","next":"n5"},{"id":"b","say":"I do not know. Just write it.","sayEs":"No sé. Solo escríbelo.","tag":"explain","q":0,"why":"'Just write it' sounds bossy, and 'I do not know' gives no reason. She cannot help well.","whyEs":"'Just write it' suena mandón y 'I do not know' no da ninguna razón. Ella no puede ayudar bien.","next":"n6"},{"id":"c","say":"Bus late. Many cars.","sayEs":"Autobús tarde. Muchos carros.","tag":"explain","q":1,"why":"She gets the idea. Use 'because' and a full sentence to make your reason clearer.","whyEs":"Ella entiende la idea. Usa 'because' y una oración completa para que tu razón sea más clara.","next":"n5"}]},"n4":{"who":"npc","say":"Hmm, that did not sound friendly. Let us start again. What do you need?","sayEs":"Mmm, eso no sonó amable. Empecemos otra vez. ¿Qué necesitas?","mood":"concerned","choices":[{"id":"a","say":"Sorry. Pass, please.","sayEs":"Perdón. Un pase, por favor.","tag":"apologize","q":1,"why":"'Please' helps, but the sentence is very short. Try 'Could I have a pass, please?'","whyEs":"'Please' ayuda, pero la oración es muy corta. Prueba 'Could I have a pass, please?'","next":"n6"},{"id":"b","say":"I already said it.","sayEs":"Ya lo dije.","tag":"request","q":0,"why":"This sounds impatient. When someone does not understand, repeat kindly instead of getting upset.","whyEs":"Esto suena impaciente. Cuando alguien no entiende, repite con amabilidad en vez de molestarte.","next":"n6"},{"id":"c","say":"I am sorry, Ms. Rivera. Could I please have a late pass?","sayEs":"Lo siento, Sra. Rivera. ¿Podría tener un pase de tardanza, por favor?","tag":"request","q":2,"why":"You repaired the problem with 'I am sorry' and 'Could I please'. Polite words help her say yes.","whyEs":"Arreglaste el problema con 'I am sorry' y 'Could I please'. Las palabras amables la ayudan a decir que sí.","next":"n5"}]},"n5":{"who":"npc","say":"I will write your pass now. Can I have your name and your teacher's name?","sayEs":"Ahora te escribo el pase. ¿Me das tu nombre y el nombre de tu maestro?","mood":"happy","choices":[{"id":"a","say":"Why do you need to know?","sayEs":"¿Para qué necesitas saberlo?","tag":"question","q":0,"why":"This question sounds rude and slows things down. A simple answer would get your pass faster.","whyEs":"Esta pregunta suena grosera y hace todo más lento. Una respuesta simple te daría el pase más rápido.","next":"n6"},{"id":"b","say":"My name is Lucia. Do you need my teacher's name too?","sayEs":"Me llamo Lucía. ¿También necesitas el nombre de mi maestro?","tag":"question","q":2,"why":"You answered first, then asked a yes/no question with 'Do you...' to check what else she needs.","whyEs":"Respondiste primero y luego hiciste una pregunta de sí o no con 'Do you...' para saber qué más necesita.","next":"n7"},{"id":"c","say":"Lucia. Teacher is Mr. Chen.","sayEs":"Lucía. El maestro es el Sr. Chen.","tag":"explain","q":1,"why":"She has what she needs. A full sentence like 'My name is Lucia' sounds more natural.","whyEs":"Ella tiene lo que necesita. Una oración completa como 'My name is Lucia' suena más natural.","next":"n7"}]},"n6":{"who":"npc","say":"Hmm, I am not sure I understand. Please tell me again what you need.","sayEs":"Mmm, no estoy segura de entender. Dime otra vez qué necesitas, por favor.","mood":"puzzled","choices":[{"id":"a","say":"I need a late pass for class, please. I am sorry I am late.","sayEs":"Necesito un pase de tardanza para la clase, por favor. Lamento llegar tarde.","tag":"request","q":2,"why":"You stated your need, added 'please', and apologized. Clear, polite lines let her fix things fast.","whyEs":"Dijiste lo que necesitas, agregaste 'please' y te disculpaste. Líneas claras y amables la ayudan a resolverlo rápido.","next":"n7"},{"id":"b","say":"Late pass. Please.","sayEs":"Pase de tardanza. Por favor.","tag":"request","q":1,"why":"'Please' is polite, and she gets the idea. A full sentence would sound smoother.","whyEs":"'Please' es amable y ella entiende la idea. Una oración completa sonaría mejor.","next":"end2"},{"id":"c","say":"Never mind. I will just go.","sayEs":"No importa. Me voy.","tag":"refuse","q":0,"why":"Walking away leaves the problem unsolved. Without a pass, you may not be allowed into class.","whyEs":"Irte deja el problema sin resolver. Sin un pase, quizás no te dejen entrar a clase.","next":"end3"}]},"n7":{"who":"npc","say":"Here is your pass. Please try to leave home a little earlier tomorrow. Okay?","sayEs":"Aquí está tu pase. Trata de salir de casa un poco más temprano mañana. ¿De acuerdo?","mood":"pleased","choices":[{"id":"a","say":"Okay. Thanks.","sayEs":"Está bien. Gracias.","tag":"thank","q":1,"why":"Saying thanks is polite. Add her name and a promise to sound warmer.","whyEs":"Dar las gracias es amable. Agrega su nombre y una promesa para sonar más cálido.","next":"end2"},{"id":"b","say":"That is not possible. Bye.","sayEs":"Eso no es posible. Adiós.","tag":"refuse","q":0,"why":"Saying no with no reason ends the talk coldly. A polite explanation keeps a good relationship.","whyEs":"Decir que no sin razón termina la conversación con frialdad. Una explicación amable mantiene la buena relación.","next":"end3"},{"id":"c","say":"Thank you, Ms. Rivera. I will leave earlier tomorrow.","sayEs":"Gracias, Sra. Rivera. Saldré más temprano mañana.","tag":"thank","q":2,"why":"You thanked her and promised to improve. That leaves a good feeling and shows responsibility.","whyEs":"Le diste las gracias y prometiste mejorar. Eso deja una buena impresión y muestra responsabilidad.","next":"end1"}]},"end1":{"who":"npc","say":"Have a good day! You can go to class now.","sayEs":"¡Que tengas un buen día! Ya puedes ir a clase.","mood":"pleased","end":true,"outcome":"strong","wrap":"You greeted her, said sorry, and asked politely, so you got your pass fast. Polite words made the visit easy.","wrapEs":"La saludaste, pediste perdón y preguntaste con cortesía, así que obtuviste tu pase rápido. Las palabras amables hicieron fácil la visita."},"end2":{"who":"npc","say":"Here you go. Hurry to class, please.","sayEs":"Aquí tienes. Apúrate a clase, por favor.","mood":"neutral","end":true,"outcome":"ok","wrap":"You got your pass, but the talk was short and a little rough. Full sentences with 'please' and 'sorry' sound warmer.","wrapEs":"Obtuviste tu pase, pero la conversación fue corta y algo brusca. Las oraciones completas con 'please' y 'sorry' suenan más cálidas."},"end3":{"who":"npc","say":"I cannot write a pass yet. Come back and try again with polite words.","sayEs":"Todavía no puedo escribir el pase. Vuelve e inténtalo otra vez con palabras amables.","mood":"concerned","end":true,"outcome":"retry","wrap":"The talk stopped before you got a pass. Try again with a greeting, 'I am sorry', and 'May I please...'.","wrapEs":"La conversación terminó antes de que obtuvieras el pase. Inténtalo otra vez con un saludo, 'I am sorry' y 'May I please...'."}}},
  {"id":"s35-nurse-visit","b":"3-5","title":"Visiting the nurse","titleEs":"Visitar a la enfermera","place":"clinic","goal":"Tell the nurse what hurts and get help.","goalEs":"Decirle a la enfermera qué te duele y recibir ayuda.","focus":["describe","question","thank"],"npc":{"name":"Nurse Okafor","role":"school nurse","roleEs":"enfermera de la escuela","look":{"skin":"#5c3a21","hair":"#1a1a1a","style":"braids","shirt":"#3a8f6b","acc":"none"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"Hi there. Come in and sit down. What is wrong?","sayEs":"Hola. Pasa y siéntate. ¿Qué te pasa?","mood":"concerned","choices":[{"id":"a","say":"My stomach hurts. It started after lunch.","sayEs":"Me duele el estómago. Empezó después del almuerzo.","tag":"describe","q":2,"why":"You named the problem and said when it began. Clear details help the nurse know what to check.","whyEs":"Nombraste el problema y dijiste cuándo empezó. Los detalles claros ayudan a la enfermera a saber qué revisar.","next":"n2"},{"id":"b","say":"I just feel bad.","sayEs":"Simplemente me siento mal.","tag":"describe","q":0,"why":"'Bad' is too general. The nurse cannot tell what hurts, so she must ask many questions.","whyEs":"'Bad' es muy general. La enfermera no sabe qué te duele y tiene que hacer muchas preguntas.","next":"n4"},{"id":"c","say":"My stomach. It hurt.","sayEs":"Mi estómago. Dolió.","tag":"describe","q":1,"why":"She can guess the problem. Say 'My stomach hurts' to be clear and use the right tense.","whyEs":"Ella puede adivinar el problema. Di 'My stomach hurts' para ser claro y usar el tiempo correcto.","next":"n3"}]},"n2":{"who":"npc","say":"I am sorry you feel sick. Does it hurt a lot, or just a little?","sayEs":"Lamento que te sientas mal. ¿Te duele mucho o solo un poco?","mood":"concerned","choices":[{"id":"a","say":"A little. It hurts.","sayEs":"Un poco. Duele.","tag":"describe","q":1,"why":"She understands the pain is small. A full sentence like 'It hurts a little' is clearer.","whyEs":"Ella entiende que el dolor es pequeño. Una oración completa como 'It hurts a little' es más clara.","next":"n5"},{"id":"b","say":"I do not want to say.","sayEs":"No quiero decirlo.","tag":"refuse","q":0,"why":"Keeping details private makes it hard for the nurse to help. Say what you can, even simply.","whyEs":"Guardar los detalles hace difícil que la enfermera ayude. Di lo que puedas, aunque sea simple.","next":"n4"},{"id":"c","say":"It hurts a little. It feels like a tight knot.","sayEs":"Duele un poco. Se siente como un nudo apretado.","tag":"describe","q":2,"why":"You said how strong the pain is and what it feels like. Details help her decide how to help.","whyEs":"Dijiste qué tan fuerte es el dolor y cómo se siente. Los detalles la ayudan a decidir cómo ayudarte.","next":"n5"}]},"n3":{"who":"npc","say":"Your stomach hurts? Okay. When did it start?","sayEs":"¿Te duele el estómago? Está bien. ¿Cuándo empezó?","mood":"neutral","choices":[{"id":"a","say":"After lunch.","sayEs":"Después del almuerzo.","tag":"describe","q":1,"why":"Short but correct. Adding 'It started' makes a full, clear sentence.","whyEs":"Corto pero correcto. Agregar 'It started' forma una oración completa y clara.","next":"n5"},{"id":"b","say":"It started after lunch, so I think I ate too fast.","sayEs":"Empezó después del almuerzo, así que creo que comí muy rápido.","tag":"explain","q":2,"why":"You used 'so' to share a reason. Reasons give the nurse more clues about what is wrong.","whyEs":"Usaste 'so' para dar una razón. Las razones le dan más pistas a la enfermera.","next":"n5"},{"id":"c","say":"I do not know. Why are you asking?","sayEs":"No sé. ¿Por qué preguntas?","tag":"question","q":0,"why":"Answering with a question makes the nurse repeat herself. Share the time you remember.","whyEs":"Responder con una pregunta hace que la enfermera se repita. Comparte la hora que recuerdes.","next":"n6"}]},"n4":{"who":"npc","say":"I want to help, but I need more information. Can you show me where it hurts?","sayEs":"Quiero ayudarte, pero necesito más información. ¿Puedes mostrarme dónde te duele?","mood":"puzzled","choices":[{"id":"a","say":"No. Nothing hurts.","sayEs":"No. Nada me duele.","tag":"refuse","q":0,"why":"Saying nothing hurts after you came in confuses her. Be honest so she can help you.","whyEs":"Decir que nada duele después de venir la confunde. Sé honesto para que pueda ayudarte.","next":"n6"},{"id":"b","say":"It hurts here, on the left side of my stomach.","sayEs":"Me duele aquí, en el lado izquierdo del estómago.","tag":"describe","q":2,"why":"You used 'here' and a body location. Showing and naming the place gives her the clue she needs.","whyEs":"Usaste 'here' y un lugar del cuerpo. Mostrar y nombrar el lugar le da la pista que necesita.","next":"n5"},{"id":"c","say":"Here. It hurts.","sayEs":"Aquí. Duele.","tag":"describe","q":1,"why":"Pointing and saying 'here' works. Naming the body part makes it clearer.","whyEs":"Señalar y decir 'here' funciona. Nombrar la parte del cuerpo lo hace más claro.","next":"n6"}]},"n5":{"who":"npc","say":"Thank you for telling me. Let me check your temperature. Do you have any questions?","sayEs":"Gracias por decírmelo. Voy a revisar tu temperatura. ¿Tienes alguna pregunta?","mood":"pleased","choices":[{"id":"a","say":"Can I go home?","sayEs":"¿Puedo ir a casa?","tag":"question","q":1,"why":"'Can I' is a good question form. Adding 'please' or a reason would sound softer.","whyEs":"'Can I' es una buena forma de preguntar. Agregar 'please' o una razón sonaría más suave.","next":"n7"},{"id":"b","say":"You check how?","sayEs":"¿Tú revisar cómo?","tag":"question","q":0,"why":"The word order is not correct. Say 'How will you check?' A clear question gets a clear answer.","whyEs":"El orden de las palabras no es correcto. Di 'How will you check?' Una pregunta clara recibe una respuesta clara.","next":"n6"},{"id":"c","say":"Yes. Do I need to go home, or can I rest here?","sayEs":"Sí. ¿Tengo que ir a casa o puedo descansar aquí?","tag":"question","q":2,"why":"You asked a clear question with 'Do I...' and gave two choices. This helps her plan the next step.","whyEs":"Hiciste una pregunta clara con 'Do I...' y diste dos opciones. Esto la ayuda a planear el siguiente paso.","next":"n7"}]},"n6":{"who":"npc","say":"Hmm, I am not sure what you need yet. Do you want to rest for a bit?","sayEs":"Mmm, todavía no sé qué necesitas. ¿Quieres descansar un rato?","mood":"neutral","choices":[{"id":"a","say":"Yes, please. I would like to rest for a little while.","sayEs":"Sí, por favor. Me gustaría descansar un rato.","tag":"accept","q":2,"why":"You accepted politely with 'Yes, please' and said what you need. That tells her how to help.","whyEs":"Aceptaste con cortesía con 'Yes, please' y dijiste lo que necesitas. Eso le dice cómo ayudarte.","next":"n7"},{"id":"b","say":"Yes. Rest.","sayEs":"Sí. Descansar.","tag":"accept","q":1,"why":"You said yes, and she understands. A full sentence with 'please' sounds friendlier.","whyEs":"Dijiste que sí y ella entiende. Una oración completa con 'please' suena más amable.","next":"end2"},{"id":"c","say":"No. I want to leave.","sayEs":"No. Quiero irme.","tag":"refuse","q":0,"why":"A flat no with no reason, when you are sick, leaves her unsure how to help.","whyEs":"Un no seco sin razón, cuando estás enfermo, la deja sin saber cómo ayudar.","next":"end3"}]},"n7":{"who":"npc","say":"Okay. Rest here. Drink some water and tell me if it gets worse. Is that okay?","sayEs":"Bien. Descansa aquí. Toma agua y dime si empeora. ¿Está bien?","mood":"happy","choices":[{"id":"a","say":"I do not need water.","sayEs":"No necesito agua.","tag":"refuse","q":0,"why":"Saying no without a reason can sound like ignoring her advice. Thank her and ask a question instead.","whyEs":"Decir que no sin razón puede sonar como ignorar su consejo. Mejor agradece y haz una pregunta.","next":"end3"},{"id":"b","say":"Thanks. Okay.","sayEs":"Gracias. Está bien.","tag":"thank","q":1,"why":"Thanks is polite. Adding her name and what you will do sounds warmer.","whyEs":"Dar las gracias es amable. Agregar su nombre y lo que harás suena más cálido.","next":"end2"},{"id":"c","say":"Thank you, Nurse Okafor. I will tell you if it hurts more.","sayEs":"Gracias, enfermera Okafor. Te diré si me duele más.","tag":"thank","q":2,"why":"You thanked her and promised to share new symptoms. That builds trust and keeps you safe.","whyEs":"Le diste las gracias y prometiste avisar si hay cambios. Eso genera confianza y te cuida.","next":"end1"}]},"end1":{"who":"npc","say":"I am glad you told me clearly. Rest now, and I will call your teacher.","sayEs":"Me alegra que me lo dijeras con claridad. Descansa ahora y llamaré a tu maestro.","mood":"pleased","end":true,"outcome":"strong","wrap":"You described your pain and asked clear questions, so the nurse could help quickly. Clear details and 'thank you' worked well.","wrapEs":"Describiste tu dolor y hiciste preguntas claras, así que la enfermera pudo ayudarte rápido. Los detalles claros y 'thank you' funcionaron bien."},"end2":{"who":"npc","say":"You can rest for a while. Come back if it hurts more.","sayEs":"Puedes descansar un rato. Vuelve si te duele más.","mood":"neutral","end":true,"outcome":"ok","wrap":"You got help, but the nurse had to ask many questions. Telling her what hurts, where, and when makes visits faster.","wrapEs":"Recibiste ayuda, pero la enfermera tuvo que hacer muchas preguntas. Decirle qué duele, dónde y cuándo hace las visitas más rápidas."},"end3":{"who":"npc","say":"I still do not know how to help. Let us try again. Tell me what hurts.","sayEs":"Todavía no sé cómo ayudarte. Intentemos otra vez. Dime qué te duele.","mood":"concerned","end":true,"outcome":"retry","wrap":"The nurse could not learn enough to help. Next time, say what hurts, where it hurts, and when it began.","wrapEs":"La enfermera no pudo saber lo suficiente para ayudar. La próxima vez, di qué duele, dónde duele y cuándo empezó."}}},
  {"id":"s35-bus-stop","b":"3-5","title":"On the school bus","titleEs":"En el autobús escolar","place":"bus","goal":"Ask about your stop and find a seat.","goalEs":"Preguntar por tu parada y encontrar un asiento.","focus":["question","clarify","thank"],"npc":{"name":"Mr. Abdi","role":"bus driver","roleEs":"conductor del autobús","look":{"skin":"#8d5524","hair":"#2b1b12","style":"cap","shirt":"#8a3b2e","acc":"none"}},"npc2":{"name":"Mei","role":"classmate","roleEs":"compañera de clase","look":{"skin":"#f1c9a5","hair":"#1a1a1a","style":"ponytail","shirt":"#7b4fa3","acc":"headphones"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"Good afternoon. Step up, please. Are you looking for something?","sayEs":"Buenas tardes. Sube, por favor. ¿Buscas algo?","mood":"neutral","choices":[{"id":"a","say":"Why is this bus so loud?","sayEs":"¿Por qué este autobús es tan ruidoso?","tag":"question","q":0,"why":"This is a good wh- question, but it is off-topic. He cannot help with your stop from it.","whyEs":"Es una buena pregunta con 'why', pero no tiene que ver con tu parada. Él no puede ayudarte con eso.","next":"n4"},{"id":"b","say":"Bus go Maple Street?","sayEs":"¿Autobús va calle Maple?","tag":"question","q":1,"why":"He can understand you. Add 'Does' and 'to' for a complete question: 'Does this bus go to Maple Street?'","whyEs":"Él puede entenderte. Agrega 'Does' y 'to' para una pregunta completa: 'Does this bus go to Maple Street?'","next":"n3"},{"id":"c","say":"Hello. Does this bus stop at Maple Street, please?","sayEs":"Hola. ¿Este autobús para en la calle Maple, por favor?","tag":"question","q":2,"why":"You used 'Does this bus...' and added 'please'. A polite yes/no question gets a quick answer.","whyEs":"Usaste 'Does this bus...' y agregaste 'please'. Una pregunta amable de sí o no recibe una respuesta rápida.","next":"n2"}]},"n2":{"who":"npc","say":"Yes, we stop at Maple Street. It is the fourth stop. Do you need anything else?","sayEs":"Sí, paramos en la calle Maple. Es la cuarta parada. ¿Necesitas algo más?","mood":"happy","choices":[{"id":"a","say":"Seat open?","sayEs":"¿Asiento libre?","tag":"question","q":1,"why":"He will understand. Use 'Is there an open seat?' to make a full question.","whyEs":"Él entenderá. Usa 'Is there an open seat?' para hacer una pregunta completa.","next":"n5"},{"id":"b","say":"Yes, thank you. Is there an open seat near the front?","sayEs":"Sí, gracias. ¿Hay un asiento libre cerca del frente?","tag":"question","q":2,"why":"You thanked him and asked a clear question with 'Is there...'. That moves the talk forward.","whyEs":"Le diste las gracias e hiciste una pregunta clara con 'Is there...'. Eso hace avanzar la conversación.","next":"n5"},{"id":"c","say":"No. I will find it myself.","sayEs":"No. Yo lo encuentro solo.","tag":"refuse","q":0,"why":"That cuts off help. Seats may be full, and a short question would save time.","whyEs":"Eso corta la ayuda. Quizás los asientos estén llenos y una pregunta corta ahorraría tiempo.","next":"n4"}]},"n3":{"who":"npc","say":"Maple. Fourth stop, after the park, before the school. You get it?","sayEs":"Maple. Cuarta parada, después del parque y antes de la escuela. ¿Entiendes?","mood":"puzzled","choices":[{"id":"a","say":"Could you say that again, please? Please speak a little slower.","sayEs":"¿Podrías repetirlo, por favor? Habla un poco más despacio.","tag":"clarify","q":2,"why":"'Could you say that again' and 'slower' politely ask for repeating. This is a strong way to clarify.","whyEs":"'Could you say that again' y 'slower' piden con cortesía que repita. Es una forma muy buena de aclarar.","next":"n5"},{"id":"b","say":"Yes, yes.","sayEs":"Sí, sí.","tag":"clarify","q":0,"why":"Saying yes when you did not understand can make you miss your stop. It is okay to ask for help.","whyEs":"Decir que sí cuando no entendiste puede hacerte perder tu parada. Está bien pedir ayuda.","next":"n6"},{"id":"c","say":"What? Again, please.","sayEs":"¿Qué? Otra vez, por favor.","tag":"clarify","q":1,"why":"He knows you need him to repeat. 'Could you repeat that?' sounds more polite than 'What?'","whyEs":"Él sabe que necesitas que repita. 'Could you repeat that?' suena más amable que 'What?'","next":"n5"}]},"n4":{"who":"npc","say":"Sorry, I am watching the road. What do you need?","sayEs":"Perdón, estoy mirando el camino. ¿Qué necesitas?","mood":"neutral","choices":[{"id":"a","say":"Maple Street? Yes or no?","sayEs":"¿Calle Maple? ¿Sí o no?","tag":"question","q":1,"why":"He gets your question, but 'Yes or no?' sounds a bit pushy. Add 'please'.","whyEs":"Él entiende tu pregunta, pero 'Yes or no?' suena algo insistente. Agrega 'please'.","next":"n6"},{"id":"b","say":"Never mind.","sayEs":"No importa.","tag":"refuse","q":0,"why":"Dropping your question may mean missing your stop. Ask again, even if you feel nervous.","whyEs":"Dejar tu pregunta puede hacer que pierdas tu parada. Pregunta otra vez, aunque estés nervioso.","next":"n6"},{"id":"c","say":"Sorry. Does this bus go to Maple Street?","sayEs":"Perdón. ¿Este autobús va a la calle Maple?","tag":"question","q":2,"why":"You said sorry and asked a full yes/no question. Now he knows exactly what you need.","whyEs":"Dijiste perdón e hiciste una pregunta completa de sí o no. Ahora él sabe exactamente qué necesitas.","next":"n5"}]},"n5":{"who":"npc2","say":"Hi! I heard you. I get off at Maple too. Do you want to sit with me?","sayEs":"¡Hola! Te escuché. Yo también me bajo en Maple. ¿Quieres sentarte conmigo?","mood":"happy","choices":[{"id":"a","say":"Yes, please. How many stops are there before Maple?","sayEs":"Sí, por favor. ¿Cuántas paradas hay antes de Maple?","tag":"question","q":2,"why":"You accepted and asked a 'How many' question. Wh- questions get number or detail answers.","whyEs":"Aceptaste y preguntaste con 'How many'. Las preguntas con wh- reciben respuestas con números o detalles.","next":"n7"},{"id":"b","say":"Yes. Sit with you.","sayEs":"Sí. Sentarme contigo.","tag":"accept","q":1,"why":"She understands you said yes. Try 'Yes, I would like that' to sound smoother.","whyEs":"Ella entiende que dijiste que sí. Prueba 'Yes, I would like that' para sonar mejor.","next":"n7"},{"id":"c","say":"No. I do not know you.","sayEs":"No. No te conozco.","tag":"refuse","q":0,"why":"That is true, but it sounds cold. A polite no, like 'No, thank you', keeps things friendly.","whyEs":"Es verdad, pero suena frío. Un no amable, como 'No, thank you', mantiene un buen ambiente.","next":"n6"}]},"n6":{"who":"npc2","say":"Hmm, you look unsure. I can help. Do you want me to tell you when we are at Maple?","sayEs":"Mmm, pareces no estar seguro. Te puedo ayudar. ¿Quieres que te avise cuando lleguemos a Maple?","mood":"neutral","choices":[{"id":"a","say":"I do not need help.","sayEs":"No necesito ayuda.","tag":"refuse","q":0,"why":"This sounds closed off. You may miss your stop. A polite 'No, thanks' with a reason is kinder.","whyEs":"Esto suena cerrado. Puedes perder tu parada. Un 'No, thanks' con una razón es más amable.","next":"end3"},{"id":"b","say":"Yes, please. That would help me a lot. Thank you!","sayEs":"Sí, por favor. Me ayudaría mucho. ¡Gracias!","tag":"thank","q":2,"why":"You accepted help and thanked her in one go. Warm words build friendships.","whyEs":"Aceptaste la ayuda y le diste las gracias a la vez. Las palabras cálidas construyen amistades.","next":"n7"},{"id":"c","say":"Yes. Tell me.","sayEs":"Sí. Dime.","tag":"accept","q":1,"why":"She understands you. 'Please' makes a request sound kind instead of bossy.","whyEs":"Ella te entiende. 'Please' hace que una petición suene amable y no mandona.","next":"end2"}]},"n7":{"who":"npc2","say":"Our stop is next. Are you ready to get off?","sayEs":"Nuestra parada es la próxima. ¿Estás listo para bajar?","mood":"happy","choices":[{"id":"a","say":"Yes. Thanks.","sayEs":"Sí. Gracias.","tag":"thank","q":1,"why":"Thanks is polite. Say what you are thankful for to sound warmer.","whyEs":"Dar las gracias es amable. Di por qué estás agradecido para sonar más cálido.","next":"end2"},{"id":"b","say":"Do not rush me.","sayEs":"No me apures.","tag":"refuse","q":0,"why":"This sounds rude when she is helping. Say 'One moment, please' instead.","whyEs":"Esto suena grosero cuando ella te ayuda. Mejor di 'One moment, please'.","next":"end3"},{"id":"c","say":"Yes, I am ready. Thank you for helping me today.","sayEs":"Sí, estoy listo. Gracias por ayudarme hoy.","tag":"thank","q":2,"why":"You answered the question and thanked her for a specific thing. That makes thanks feel real.","whyEs":"Respondiste la pregunta y le diste las gracias por algo concreto. Eso hace que el agradecimiento se sienta sincero.","next":"end1"}]},"end1":{"who":"npc2","say":"Great! See you tomorrow on the bus, okay?","sayEs":"¡Genial! Nos vemos mañana en el autobús, ¿sí?","mood":"pleased","end":true,"outcome":"strong","wrap":"You asked clear questions, asked for repeats, and said thank you, so you found your stop and a new friend.","wrapEs":"Hiciste preguntas claras, pediste repetir y diste las gracias, así que encontraste tu parada y una nueva amiga."},"end2":{"who":"npc","say":"Okay. Hold the rail and be careful on the steps.","sayEs":"Bien. Sujétate del pasamanos y ten cuidado en los escalones.","mood":"neutral","end":true,"outcome":"ok","wrap":"You got off at the right stop, but some questions were unclear. Full questions and 'Could you repeat that?' help on a noisy bus.","wrapEs":"Te bajaste en la parada correcta, pero algunas preguntas no fueron claras. Preguntas completas y 'Could you repeat that?' ayudan en un autobús ruidoso."},"end3":{"who":"npc","say":"Hold on! This is not your stop yet. Please ask again if you are unsure.","sayEs":"¡Espera! Todavía no es tu parada. Pregunta otra vez si no estás seguro.","mood":"concerned","end":true,"outcome":"retry","wrap":"You almost missed your stop because the questions were unclear. Ask 'Does this bus go to...?' and ask for repeats.","wrapEs":"Casi pierdes tu parada porque las preguntas no fueron claras. Pregunta 'Does this bus go to...?' y pide que repitan."}}},
  {"id":"s35-lunch-new","b":"3-5","title":"A new student at lunch","titleEs":"Una estudiante nueva en el almuerzo","place":"lunch","goal":"Greet a new student and invite her to sit.","goalEs":"Saludar a una estudiante nueva e invitarla a sentarse.","focus":["greet","invite","question"],"npc":{"name":"Noor","role":"new student","roleEs":"estudiante nueva","look":{"skin":"#e0ac84","hair":"#2b1b12","style":"long","shirt":"#c0562b","acc":"none"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"Hi. I am new here. I do not know where to sit.","sayEs":"Hola. Soy nueva aquí. No sé dónde sentarme.","mood":"neutral","choices":[{"id":"a","say":"Hi. You new? Sit here.","sayEs":"Hola. ¿Eres nueva? Siéntate aquí.","tag":"greet","q":1,"why":"A friendly idea, but short. 'Are you new?' is the full form, and 'You can sit here' sounds kinder.","whyEs":"Una idea amable, pero corta. 'Are you new?' es la forma completa y 'You can sit here' suena más amable.","next":"n3"},{"id":"b","say":"Why are you standing there?","sayEs":"¿Por qué estás parada ahí?","tag":"question","q":0,"why":"This sounds like a complaint. A new student may feel embarrassed. Start with hello instead.","whyEs":"Esto suena a queja. Una estudiante nueva puede sentirse avergonzada. Mejor empieza con un saludo.","next":"n4"},{"id":"c","say":"Hi! Welcome to our school. What is your name?","sayEs":"¡Hola! Bienvenida a nuestra escuela. ¿Cómo te llamas?","tag":"greet","q":2,"why":"You said hello, welcomed her, and asked her name. That makes a new person feel safe.","whyEs":"Dijiste hola, la recibiste y le preguntaste su nombre. Eso hace que una persona nueva se sienta segura.","next":"n2"}]},"n2":{"who":"npc","say":"Thanks! I am Noor. I just moved here from another city. This lunchroom is big!","sayEs":"¡Gracias! Soy Noor. Me mudé aquí desde otra ciudad. ¡Este comedor es grande!","mood":"happy","choices":[{"id":"a","say":"You will probably get lost here.","sayEs":"Probablemente te perderás aquí.","tag":"describe","q":0,"why":"Describing only the scary side may worry her more. Offer help or an invitation instead.","whyEs":"Describir solo el lado asustador puede preocuparla más. Ofrece ayuda o una invitación.","next":"n4"},{"id":"b","say":"Nice to meet you, Noor. Would you like to sit with us?","sayEs":"Mucho gusto, Noor. ¿Te gustaría sentarte con nosotros?","tag":"invite","q":2,"why":"'Would you like to...' is a polite invitation. It lets Noor choose and feels welcoming.","whyEs":"'Would you like to...' es una invitación amable. Deja que Noor elija y se siente acogedora.","next":"n5"},{"id":"c","say":"Sit with us.","sayEs":"Siéntate con nosotros.","tag":"invite","q":1,"why":"She gets the invitation. Adding 'Would you like to' or 'please' makes it feel like a choice.","whyEs":"Ella entiende la invitación. Agregar 'Would you like to' o 'please' hace que se sienta como una opción.","next":"n5"}]},"n3":{"who":"npc","say":"Oh. Yes, I am new. I am Noor. Is this seat free?","sayEs":"Ah. Sí, soy nueva. Soy Noor. ¿Está libre este asiento?","mood":"neutral","choices":[{"id":"a","say":"Yes, it is free. What do you like to eat for lunch?","sayEs":"Sí, está libre. ¿Qué te gusta comer en el almuerzo?","tag":"question","q":2,"why":"You answered her and asked a 'What' question about her. That starts a friendly talk.","whyEs":"Le respondiste y le hiciste una pregunta con 'What' sobre ella. Eso inicia una conversación amable.","next":"n5"},{"id":"b","say":"Yes. You like pizza?","sayEs":"Sí. ¿Te gusta la pizza?","tag":"question","q":1,"why":"A friendly question. The full form is 'Do you like pizza?'","whyEs":"Una pregunta amable. La forma completa es 'Do you like pizza?'","next":"n5"},{"id":"c","say":"No. My friend sits there.","sayEs":"No. Mi amigo se sienta ahí.","tag":"refuse","q":0,"why":"A flat no to a new student can feel unkind. Offer another seat to stay friendly.","whyEs":"Un no seco a una estudiante nueva puede parecer poco amable. Ofrece otro asiento para ser amigable.","next":"n6"}]},"n4":{"who":"npc","say":"Oh, um, sorry. I will find another table.","sayEs":"Ah, perdón. Buscaré otra mesa.","mood":"concerned","choices":[{"id":"a","say":"You can sit here, too.","sayEs":"Puedes sentarte aquí también.","tag":"invite","q":1,"why":"A nice invitation, but it needs a 'sorry' and 'please' to sound sincere.","whyEs":"Una buena invitación, pero necesita un 'sorry' y 'please' para sonar sincera.","next":"n6"},{"id":"b","say":"Wait, I am sorry. Please sit with us! We have a seat.","sayEs":"Espera, lo siento. ¡Por favor siéntate con nosotros! Tenemos un lugar.","tag":"invite","q":2,"why":"You apologized and then invited her kindly. Repair first, then invite: that fixes a rough start.","whyEs":"Te disculpaste y luego la invitaste con amabilidad. Primero reparas y luego invitas: así arreglas un mal inicio.","next":"n5"},{"id":"c","say":"Okay. Bye.","sayEs":"Está bien. Adiós.","tag":"greet","q":0,"why":"Letting her leave ends the chance to be kind. It is not rude, but it misses the moment.","whyEs":"Dejar que se vaya termina la oportunidad de ser amable. No es grosero, pero pierdes el momento.","next":"n6"}]},"n5":{"who":"npc","say":"That sounds great! What do you usually do after lunch? I do not know the school yet.","sayEs":"¡Suena bien! ¿Qué suelen hacer después del almuerzo? Todavía no conozco la escuela.","mood":"pleased","choices":[{"id":"a","say":"I do not know. Ask someone else.","sayEs":"No sé. Pregúntale a otra persona.","tag":"refuse","q":0,"why":"This closes the talk and leaves her alone. Share one thing you do, even a small one.","whyEs":"Esto cierra la conversación y la deja sola. Cuéntale algo que haces, aunque sea pequeño.","next":"n6"},{"id":"b","say":"Play soccer. You come?","sayEs":"Jugamos fútbol. ¿Vienes?","tag":"invite","q":1,"why":"She can follow you. Use 'We play soccer. Do you want to come?' for a full invitation.","whyEs":"Ella te puede seguir. Usa 'We play soccer. Do you want to come?' para una invitación completa.","next":"n7"},{"id":"c","say":"We play soccer outside. Would you like to join us?","sayEs":"Jugamos fútbol afuera. ¿Te gustaría jugar con nosotros?","tag":"invite","q":2,"why":"You shared what you do and used 'Would you like to...' to invite her. That helps her make friends.","whyEs":"Compartiste lo que haces y usaste 'Would you like to...' para invitarla. Eso la ayuda a hacer amigos.","next":"n7"}]},"n6":{"who":"npc","say":"Hmm. I am still a little shy. Can you tell me about your school?","sayEs":"Mmm. Todavía me da un poco de pena. ¿Puedes contarme sobre tu escuela?","mood":"puzzled","choices":[{"id":"a","say":"Our teachers are kind. Do you want to see the library?","sayEs":"Nuestros maestros son amables. ¿Quieres ver la biblioteca?","tag":"question","q":2,"why":"You described something good and asked a question to include her. That helps a shy person relax.","whyEs":"Describiste algo bueno e hiciste una pregunta para incluirla. Eso ayuda a una persona tímida a relajarse.","next":"n7"},{"id":"b","say":"It is boring.","sayEs":"Es aburrida.","tag":"describe","q":0,"why":"Calling the school boring may make her feel worse. Share something positive or helpful.","whyEs":"Decir que la escuela es aburrida puede hacerla sentir peor. Comparte algo positivo o útil.","next":"end3"},{"id":"c","say":"School is okay. Big.","sayEs":"La escuela está bien. Es grande.","tag":"describe","q":1,"why":"She gets a little information. Add details, like 'The school is big, but friendly'.","whyEs":"Ella recibe poca información. Agrega detalles, como 'The school is big, but friendly'.","next":"end2"}]},"n7":{"who":"npc","say":"Thanks for being so kind. Can I sit with you again tomorrow?","sayEs":"Gracias por ser tan amable. ¿Puedo sentarme con ustedes mañana otra vez?","mood":"happy","choices":[{"id":"a","say":"Maybe. I will think about it.","sayEs":"Quizás. Lo pensaré.","tag":"refuse","q":0,"why":"'Maybe' with no reason can feel like a no. A new student needs a clear, warm answer.","whyEs":"'Maybe' sin razón puede sentirse como un no. Una estudiante nueva necesita una respuesta clara y cálida.","next":"end3"},{"id":"b","say":"Of course! I will save you a seat tomorrow.","sayEs":"¡Claro! Mañana te guardo un asiento.","tag":"accept","q":2,"why":"'Of course' says yes warmly, and saving a seat shows care. She will feel she belongs.","whyEs":"'Of course' dice que sí con calidez y guardar un asiento muestra cariño. Ella sentirá que pertenece.","next":"end1"},{"id":"c","say":"Yes. Come tomorrow.","sayEs":"Sí. Ven mañana.","tag":"accept","q":1,"why":"You said yes, and she is happy. Add 'of course' or 'I would like that' to sound warmer.","whyEs":"Dijiste que sí y ella está contenta. Agrega 'of course' o 'I would like that' para sonar más cálido.","next":"end2"}]},"end1":{"who":"npc","say":"I feel better already. Thank you for being my first friend here.","sayEs":"Ya me siento mejor. Gracias por ser mi primera amiga aquí.","mood":"pleased","end":true,"outcome":"strong","wrap":"You greeted Noor, asked questions, and invited her. Kind words helped a new student feel welcome.","wrapEs":"Saludaste a Noor, hiciste preguntas y la invitaste. Las palabras amables ayudaron a una estudiante nueva a sentirse bienvenida."},"end2":{"who":"npc","say":"Thanks. I will sit here for now.","sayEs":"Gracias. Me sentaré aquí por ahora.","mood":"neutral","end":true,"outcome":"ok","wrap":"Noor sat with you, but the talk was short. Questions and invitations like 'Would you like to...?' build friendships.","wrapEs":"Noor se sentó contigo, pero la conversación fue corta. Las preguntas y las invitaciones como 'Would you like to...?' construyen amistades."},"end3":{"who":"npc","say":"I think I will eat by myself today.","sayEs":"Creo que hoy comeré sola.","mood":"concerned","end":true,"outcome":"retry","wrap":"Noor did not feel welcome yet. Try a greeting, a question about her, and an invitation.","wrapEs":"Noor todavía no se sintió bienvenida. Prueba con un saludo, una pregunta sobre ella y una invitación."}}},
  {"id":"s35-library-book","b":"3-5","title":"Asking for a book","titleEs":"Pedir un libro","place":"library","goal":"Ask the librarian to help you find a book.","goalEs":"Pedirle al bibliotecario que te ayude a encontrar un libro.","focus":["request","question","thank"],"npc":{"name":"Mr. Tanaka","role":"librarian","roleEs":"bibliotecario","look":{"skin":"#f1c9a5","hair":"#3a3a3a","style":"short","shirt":"#2d5f4a","acc":"glasses"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"Welcome to the library! Can I help you find something?","sayEs":"¡Bienvenido a la biblioteca! ¿Te puedo ayudar a encontrar algo?","mood":"happy","choices":[{"id":"a","say":"Give me a shark book.","sayEs":"Dame un libro de tiburones.","tag":"request","q":0,"why":"'Give me' is a command. It sounds rude. Use 'Could you...' or 'May I...' with please.","whyEs":"'Give me' es una orden y suena grosero. Usa 'Could you...' o 'May I...' con please.","next":"n4"},{"id":"b","say":"Yes, please. Could you help me find a book about sharks?","sayEs":"Sí, por favor. ¿Podrías ayudarme a encontrar un libro sobre tiburones?","tag":"request","q":2,"why":"You used 'Could you...' and 'please'. That is a polite request, so he will gladly help.","whyEs":"Usaste 'Could you...' y 'please'. Es una petición amable, así que te ayudará con gusto.","next":"n2"},{"id":"c","say":"Yes. I want book sharks.","sayEs":"Sí. Quiero libro tiburones.","tag":"request","q":1,"why":"He understands your topic. Say 'I would like a book about sharks, please' to sound polite.","whyEs":"Él entiende tu tema. Di 'I would like a book about sharks, please' para sonar amable.","next":"n3"}]},"n2":{"who":"npc","say":"Sharks! Great choice. Do you want a story or a book with facts?","sayEs":"¡Tiburones! Buena elección. ¿Quieres un cuento o un libro con datos?","mood":"pleased","choices":[{"id":"a","say":"Facts. Pictures too.","sayEs":"Datos. Fotos también.","tag":"request","q":1,"why":"He understands. A full sentence with 'please' sounds more polite.","whyEs":"Él entiende. Una oración completa con 'please' suena más amable.","next":"n5"},{"id":"b","say":"I do not care.","sayEs":"No me importa.","tag":"explain","q":0,"why":"This gives him no information and sounds uninterested. Pick one so he can find the right book.","whyEs":"Esto no le da información y suena a desinterés. Elige una para que encuentre el libro correcto.","next":"n4"},{"id":"c","say":"I want facts, please. Are there any with pictures?","sayEs":"Quiero datos, por favor. ¿Hay alguno con fotos?","tag":"question","q":2,"why":"You chose one and asked a 'Are there any...' question. That helps him narrow the search.","whyEs":"Elegiste una opción e hiciste una pregunta con 'Are there any...'. Eso lo ayuda a reducir la búsqueda.","next":"n5"}]},"n3":{"who":"npc","say":"We have many shark books. Do you want fiction or nonfiction?","sayEs":"Tenemos muchos libros de tiburones. ¿Quieres ficción o no ficción?","mood":"neutral","choices":[{"id":"a","say":"What does nonfiction mean? Could you explain, please?","sayEs":"¿Qué significa 'nonfiction'? ¿Podrías explicarlo, por favor?","tag":"clarify","q":2,"why":"You asked what a new word means and said 'please'. Clarifying helps you choose the right book.","whyEs":"Preguntaste qué significa una palabra nueva y dijiste 'please'. Aclarar te ayuda a elegir el libro correcto.","next":"n5"},{"id":"b","say":"Nonfiction? What is that?","sayEs":"¿Nonfiction? ¿Qué es eso?","tag":"clarify","q":1,"why":"You asked about the word, which is good. Adding 'please' makes it more polite.","whyEs":"Preguntaste por la palabra, y eso es bueno. Agregar 'please' lo hace más amable.","next":"n5"},{"id":"c","say":"Yes.","sayEs":"Sí.","tag":"accept","q":0,"why":"'Yes' does not answer an 'or' question. Ask what the word means if it is new.","whyEs":"'Yes' no responde una pregunta con 'or'. Pregunta qué significa la palabra si es nueva.","next":"n6"}]},"n4":{"who":"npc","say":"Hmm, I want to help. Tell me what kind of book you need, and I will look.","sayEs":"Mmm, quiero ayudarte. Dime qué tipo de libro necesitas y lo busco.","mood":"puzzled","choices":[{"id":"a","say":"Book about sharks, please.","sayEs":"Un libro sobre tiburones, por favor.","tag":"request","q":1,"why":"'Please' helps, and he understands. Add 'I would like' for a full sentence.","whyEs":"'Please' ayuda y él entiende. Agrega 'I would like' para una oración completa.","next":"n6"},{"id":"b","say":"I would like a book with facts about sharks, please.","sayEs":"Quisiera un libro con datos sobre tiburones, por favor.","tag":"request","q":2,"why":"'I would like' with 'please' is a polite way to ask. Now he knows the topic and type.","whyEs":"'I would like' con 'please' es una forma amable de pedir. Ahora él sabe el tema y el tipo.","next":"n5"},{"id":"c","say":"You do not have it?","sayEs":"¿No lo tienes?","tag":"question","q":0,"why":"This sounds like blame and the question form is not clear. Ask 'Do you have any shark books?'","whyEs":"Esto suena a reproche y la forma de la pregunta no es clara. Pregunta 'Do you have any shark books?'","next":"n6"}]},"n5":{"who":"npc","say":"Here are two books. This one has big photos. This one is about ocean animals. Which one do you want?","sayEs":"Aquí hay dos libros. Este tiene fotos grandes. Este es sobre animales del océano. ¿Cuál quieres?","mood":"happy","choices":[{"id":"a","say":"The photo book looks great. How long can I keep it?","sayEs":"El libro de fotos se ve genial. ¿Cuánto tiempo puedo quedármelo?","tag":"question","q":2,"why":"You chose and asked a 'How long' question. Wh- questions help you learn the rules.","whyEs":"Elegiste y preguntaste con 'How long'. Las preguntas con wh- te ayudan a conocer las reglas.","next":"n7"},{"id":"b","say":"I do not want either one.","sayEs":"No quiero ninguno.","tag":"refuse","q":0,"why":"He found two books for you. A flat no with no reason can seem ungrateful. Say what is missing.","whyEs":"Él encontró dos libros para ti. Un no seco sin razón puede parecer desagradecido. Di qué falta.","next":"n6"},{"id":"c","say":"Photo book. How long?","sayEs":"El libro de fotos. ¿Cuánto tiempo?","tag":"question","q":1,"why":"He understands. A full question is 'How long can I keep it?'","whyEs":"Él entiende. Una pregunta completa es 'How long can I keep it?'","next":"n7"}]},"n6":{"who":"npc","say":"Hmm. I think I am missing something. Do you still want a shark book?","sayEs":"Mmm. Creo que me falta algo. ¿Todavía quieres un libro de tiburones?","mood":"concerned","choices":[{"id":"a","say":"No, forget it.","sayEs":"No, olvídalo.","tag":"refuse","q":0,"why":"Giving up leaves you with no book. Say what you need, even if you are unsure.","whyEs":"Rendirte te deja sin libro. Di lo que necesitas, aunque no estés seguro.","next":"end3"},{"id":"b","say":"Yes. Show me.","sayEs":"Sí. Muéstrame.","tag":"request","q":1,"why":"He understands. 'Please' and 'Could you' make it sound polite.","whyEs":"Él entiende. 'Please' y 'Could you' lo hacen sonar amable.","next":"end2"},{"id":"c","say":"Yes, please. Could you show me the shark books again?","sayEs":"Sí, por favor. ¿Podrías mostrarme los libros de tiburones otra vez?","tag":"request","q":2,"why":"You said yes and asked politely to start again. A fresh, polite request helps him help you.","whyEs":"Dijiste que sí y pediste con cortesía empezar de nuevo. Una petición amable ayuda a que te ayude.","next":"n7"}]},"n7":{"who":"npc","say":"Okay! You can check it out for one week. Here is your card. Is that okay?","sayEs":"¡Bien! Puedes llevártelo una semana. Aquí está tu tarjeta. ¿Está bien?","mood":"pleased","choices":[{"id":"a","say":"Okay. Thank you.","sayEs":"Está bien. Gracias.","tag":"thank","q":1,"why":"Thanks is polite. Add what you are thankful for to sound warmer.","whyEs":"Dar las gracias es amable. Agrega por qué agradeces para sonar más cálido.","next":"end2"},{"id":"b","say":"Yes, that is perfect. Thank you for your help, Mr. Tanaka.","sayEs":"Sí, es perfecto. Gracias por tu ayuda, Sr. Tanaka.","tag":"thank","q":2,"why":"You thanked him for a specific thing and used his name. That makes thanks feel sincere.","whyEs":"Le agradeciste por algo concreto y usaste su nombre. Eso hace que el agradecimiento sea sincero.","next":"end1"},{"id":"c","say":"One week is too short!","sayEs":"¡Una semana es muy poco!","tag":"disagree","q":0,"why":"Complaining sounds ungrateful. You can ask politely, 'Could I keep it a little longer, please?'","whyEs":"Quejarte suena desagradecido. Puedes preguntar con cortesía: 'Could I keep it a little longer, please?'","next":"end3"}]},"end1":{"who":"npc","say":"You are welcome! Come back and tell me what you learned.","sayEs":"¡De nada! Vuelve y cuéntame lo que aprendiste.","mood":"pleased","end":true,"outcome":"strong","wrap":"You asked politely, asked questions, and thanked him, so you left with the perfect book.","wrapEs":"Pediste con cortesía, hiciste preguntas y le diste las gracias, así que te fuiste con el libro perfecto."},"end2":{"who":"npc","say":"Here is your book. Enjoy it.","sayEs":"Aquí está tu libro. Disfrútalo.","mood":"neutral","end":true,"outcome":"ok","wrap":"You got a book, but some lines were short or unclear. 'Could you...?' and 'please' help the librarian help you.","wrapEs":"Obtuviste un libro, pero algunas frases fueron cortas o poco claras. 'Could you...?' y 'please' ayudan al bibliotecario a ayudarte."},"end3":{"who":"npc","say":"I am sorry, I could not find the right book. Come back and ask again.","sayEs":"Lo siento, no pude encontrar el libro correcto. Vuelve y pregunta otra vez.","mood":"concerned","end":true,"outcome":"retry","wrap":"The librarian could not learn what you wanted. Next time, say the topic and ask politely with 'Could you...?'","wrapEs":"El bibliotecario no pudo saber qué querías. La próxima vez, di el tema y pide con cortesía con 'Could you...?'"}}},
  {"id":"s35-teacher-help","b":"3-5","title":"Asking for help in class","titleEs":"Pedir ayuda en clase","place":"classroom","goal":"Ask your teacher to help with math homework.","goalEs":"Pedirle a tu maestra que te ayude con la tarea de matemáticas.","focus":["explain","clarify","request"],"npc":{"name":"Ms. Patel","role":"teacher","roleEs":"maestra","look":{"skin":"#c68642","hair":"#1a1a1a","style":"long","shirt":"#a33b5c","acc":"none"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"I see you are not writing. Is everything okay?","sayEs":"Veo que no estás escribiendo. ¿Todo está bien?","mood":"neutral","choices":[{"id":"a","say":"Nothing. I am fine.","sayEs":"Nada. Estoy bien.","tag":"refuse","q":0,"why":"Hiding the problem means no help. Teachers want to know when something is hard.","whyEs":"Esconder el problema significa no recibir ayuda. Las maestras quieren saber cuando algo es difícil.","next":"n4"},{"id":"b","say":"Number four. I no understand.","sayEs":"Número cuatro. No entiendo.","tag":"explain","q":1,"why":"She knows where you need help. Say 'I do not understand' and add 'because' with a reason.","whyEs":"Ella sabe dónde necesitas ayuda. Di 'I do not understand' y agrega 'because' con una razón.","next":"n3"},{"id":"c","say":"I got stuck on number four because I do not know how to start.","sayEs":"Me trabé en el número cuatro porque no sé cómo empezar.","tag":"explain","q":2,"why":"You used 'because' to give a clear reason. A reason lets the teacher choose the right help.","whyEs":"Usaste 'because' para dar una razón clara. Una razón ayuda a la maestra a elegir la ayuda correcta.","next":"n2"}]},"n2":{"who":"npc","say":"Thanks for telling me. Which part is hard: reading the problem or finding the answer?","sayEs":"Gracias por decírmelo. ¿Qué parte es difícil: leer el problema o encontrar la respuesta?","mood":"happy","choices":[{"id":"a","say":"Words hard. Long.","sayEs":"Palabras difíciles. Largas.","tag":"explain","q":1,"why":"She understands the idea. Use a full sentence with 'because' to be clearer.","whyEs":"Ella entiende la idea. Usa una oración completa con 'because' para ser más claro.","next":"n5"},{"id":"b","say":"Everything is hard.","sayEs":"Todo es difícil.","tag":"describe","q":0,"why":"'Everything' is too general. She cannot tell what to explain first.","whyEs":"'Everything' es muy general. Ella no sabe qué explicar primero.","next":"n4"},{"id":"c","say":"Reading it is hard because there are long words.","sayEs":"Leerlo es difícil porque hay palabras largas.","tag":"explain","q":2,"why":"You used 'because' to say exactly what is hard. A reason shows her how to help.","whyEs":"Usaste 'because' para decir exactamente qué es difícil. Una razón le muestra cómo ayudarte.","next":"n5"}]},"n3":{"who":"npc","say":"Number four? Let me see. First, read the question. Then circle the numbers. Do you follow?","sayEs":"¿Número cuatro? A ver. Primero lee la pregunta. Luego encierra los números en un círculo. ¿Me sigues?","mood":"neutral","choices":[{"id":"a","say":"Could you explain the first step again, please? I did not follow.","sayEs":"¿Podrías explicar el primer paso otra vez, por favor? No entendí.","tag":"clarify","q":2,"why":"You asked for a repeat with 'Could you' and said what you missed. That is a strong way to clarify.","whyEs":"Pediste que repita con 'Could you' y dijiste qué no entendiste. Es una forma muy buena de aclarar.","next":"n5"},{"id":"b","say":"Again, please? Slow.","sayEs":"¿Otra vez, por favor? Despacio.","tag":"clarify","q":1,"why":"She understands you need it again. 'Could you say it slowly?' sounds smoother.","whyEs":"Ella entiende que lo necesitas otra vez. 'Could you say it slowly?' suena mejor.","next":"n5"},{"id":"c","say":"Yes.","sayEs":"Sí.","tag":"accept","q":0,"why":"Saying yes when you are lost keeps you stuck. Say when you need it again.","whyEs":"Decir que sí cuando estás perdido te deja atascado. Di cuando necesites que lo repita.","next":"n6"}]},"n4":{"who":"npc","say":"Hmm, I think you may need some help. Can you show me your paper?","sayEs":"Mmm, creo que quizás necesites ayuda. ¿Puedes mostrarme tu hoja?","mood":"concerned","choices":[{"id":"a","say":"No. Do not look.","sayEs":"No. No mires.","tag":"refuse","q":0,"why":"Teachers help by seeing your work. Saying no means she cannot find the problem.","whyEs":"Las maestras ayudan al ver tu trabajo. Decir que no significa que ella no puede encontrar el problema.","next":"n6"},{"id":"b","say":"Yes. Could you please look at number four with me?","sayEs":"Sí. ¿Podrías ver el número cuatro conmigo, por favor?","tag":"request","q":2,"why":"You said yes and made a polite request with 'Could you please'. That points her to the exact problem.","whyEs":"Dijiste que sí e hiciste una petición amable con 'Could you please'. Eso la lleva al problema exacto.","next":"n5"},{"id":"c","say":"Yes. Look number four.","sayEs":"Sí. Mira el número cuatro.","tag":"request","q":1,"why":"She knows which problem. 'Look' sounds like an order, so use 'Could you look...?'","whyEs":"Ella sabe cuál problema. 'Look' suena como una orden, así que usa 'Could you look...?'","next":"n6"}]},"n5":{"who":"npc","say":"Okay, let us try together. First, what is the question asking you to find?","sayEs":"Bien, intentémoslo juntos. Primero, ¿qué te pide encontrar la pregunta?","mood":"pleased","choices":[{"id":"a","say":"Cost. Add?","sayEs":"¿Costo? ¿Sumar?","tag":"explain","q":1,"why":"You have the right idea. A full sentence would show more of your thinking.","whyEs":"Tienes la idea correcta. Una oración completa mostraría más de tu razonamiento.","next":"n7"},{"id":"b","say":"It asks for the total cost, so I think I should add.","sayEs":"Pide el costo total, así que creo que debo sumar.","tag":"explain","q":2,"why":"You explained your thinking with 'so I think'. Sharing your thinking shows what you already know.","whyEs":"Explicaste tu razonamiento con 'so I think'. Compartir tu razonamiento muestra lo que ya sabes.","next":"n7"},{"id":"c","say":"I do not know.","sayEs":"No sé.","tag":"explain","q":0,"why":"This gives her nothing to build on. Even a small guess helps her teach you.","whyEs":"Esto no le da nada para continuar. Incluso una pequeña idea la ayuda a enseñarte.","next":"n6"}]},"n6":{"who":"npc","say":"I am not sure I explained well. Would you like me to show an example on the board?","sayEs":"No estoy segura de haberlo explicado bien. ¿Quieres que te muestre un ejemplo en la pizarra?","mood":"neutral","choices":[{"id":"a","say":"Yes, please. Could you show one example slowly?","sayEs":"Sí, por favor. ¿Podrías mostrar un ejemplo despacio?","tag":"request","q":2,"why":"You accepted and asked for exactly what helps: one example, slowly. That is a clear, polite request.","whyEs":"Aceptaste y pediste justo lo que ayuda: un ejemplo, despacio. Es una petición clara y amable.","next":"n7"},{"id":"b","say":"Yes. Example, please.","sayEs":"Sí. Un ejemplo, por favor.","tag":"request","q":1,"why":"'Please' is polite, and she understands. A full sentence sounds smoother.","whyEs":"'Please' es amable y ella entiende. Una oración completa suena mejor.","next":"end2"},{"id":"c","say":"No. It is too hard.","sayEs":"No. Es muy difícil.","tag":"refuse","q":0,"why":"Saying no and giving up leaves you without help. Ask for a slower explanation instead.","whyEs":"Decir que no y rendirte te deja sin ayuda. Mejor pide una explicación más lenta.","next":"end3"}]},"n7":{"who":"npc","say":"Now try number four on your own. Raise your hand if you need me again. Okay?","sayEs":"Ahora intenta el número cuatro por tu cuenta. Levanta la mano si me necesitas otra vez. ¿Está bien?","mood":"pleased","choices":[{"id":"a","say":"I cannot do it alone.","sayEs":"No puedo hacerlo por mi cuenta.","tag":"explain","q":0,"why":"This is honest, but it gives no reason. Say which part is hard so she can help.","whyEs":"Es honesto, pero no da una razón. Di qué parte es difícil para que pueda ayudar.","next":"end3"},{"id":"b","say":"Okay. Check answer, please.","sayEs":"Está bien. Revisa mi respuesta, por favor.","tag":"request","q":1,"why":"She understands. Add 'Could you' to turn the order into a polite request.","whyEs":"Ella entiende. Agrega 'Could you' para convertir la orden en una petición amable.","next":"end2"},{"id":"c","say":"Okay. Could you check my answer when I finish, please?","sayEs":"Está bien. ¿Podrías revisar mi respuesta cuando termine, por favor?","tag":"request","q":2,"why":"You accepted the plan and politely asked for feedback. That shows you are ready to learn.","whyEs":"Aceptaste el plan y pediste con cortesía una revisión. Eso muestra que estás listo para aprender.","next":"end1"}]},"end1":{"who":"npc","say":"Great job asking! I will come back and check it soon.","sayEs":"¡Muy bien por pedir ayuda! Volveré a revisarlo pronto.","mood":"happy","end":true,"outcome":"strong","wrap":"You explained what was hard, asked her to repeat, and made polite requests, so you understood the problem.","wrapEs":"Explicaste qué era difícil, pediste que repitiera e hiciste peticiones amables, así que entendiste el problema."},"end2":{"who":"npc","say":"Good. Keep trying. I am here if you need me.","sayEs":"Bien. Sigue intentando. Estoy aquí si me necesitas.","mood":"neutral","end":true,"outcome":"ok","wrap":"You got some help, but a few answers were short. Giving reasons with 'because' helps teachers know how to help.","wrapEs":"Recibiste algo de ayuda, pero algunas respuestas fueron cortas. Dar razones con 'because' ayuda a las maestras a saber cómo ayudar."},"end3":{"who":"npc","say":"I want to help, but I am not sure what is hard. Let us try again.","sayEs":"Quiero ayudar, pero no sé qué es difícil. Intentémoslo otra vez.","mood":"concerned","end":true,"outcome":"retry","wrap":"The teacher could not learn what was hard. Next time, say the problem, give a reason, and ask for help politely.","wrapEs":"La maestra no pudo saber qué era difícil. La próxima vez, di el problema, da una razón y pide ayuda con cortesía."}}},
  {"id":"s35-group-roles","b":"3-5","title":"Who does what?","titleEs":"¿Quién hace qué?","place":"classroom","goal":"Disagree politely and agree on jobs for a group poster.","goalEs":"Estar en desacuerdo con amabilidad y acordar tareas para un cartel de grupo.","focus":["disagree","offer","refuse"],"npc":{"name":"Jonah","role":"group partner","roleEs":"compañero de grupo","look":{"skin":"#f5d5b8","hair":"#8a5a2b","style":"curly","shirt":"#c4572a","acc":"headphones"}},"npc2":{"name":"Aaliyah","role":"group partner","roleEs":"compañera de grupo","look":{"skin":"#5c3a21","hair":"#1a1a1a","style":"ponytail","shirt":"#2b6cb0","acc":"none"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"I will draw the pictures. You can do all the writing, okay?","sayEs":"Yo dibujo las imágenes. Tú haces toda la escritura, ¿sí?","mood":"neutral","choices":[{"id":"a","say":"I see your point, but that is not fair. Can we share the writing?","sayEs":"Entiendo tu punto, pero eso no es justo. ¿Podemos compartir la escritura?","tag":"disagree","q":2,"why":"'I see your point, but...' disagrees kindly. Then you offered a fair option, so he is likely to listen.","whyEs":"'I see your point, but...' expresa desacuerdo con amabilidad. Luego ofreciste una opción justa, así que probablemente te escuche.","next":"n2"},{"id":"b","say":"Fine. Whatever you say.","sayEs":"Bien. Lo que tú digas.","tag":"accept","q":0,"why":"Agreeing with an annoyed tone hides the real problem. The unfair split stays, and you may feel upset later.","whyEs":"Aceptar con tono molesto esconde el problema real. El reparto injusto sigue y luego puedes sentirte mal.","next":"n4"},{"id":"c","say":"No. Not fair. I not want.","sayEs":"No. No es justo. No quiero.","tag":"disagree","q":1,"why":"He knows you disagree. Soften it with 'I think' and give a different idea.","whyEs":"Él sabe que no estás de acuerdo. Suavízalo con 'I think' y da otra idea.","next":"n3"}]},"n2":{"who":"npc","say":"Hmm, okay. I did not think about that. What part of the writing do you want?","sayEs":"Mmm, está bien. No había pensado en eso. ¿Qué parte de la escritura quieres?","mood":"pleased","choices":[{"id":"a","say":"I do not want to write anything.","sayEs":"No quiero escribir nada.","tag":"refuse","q":0,"why":"Saying no to all the writing brings back the fairness problem. Offer one small part to keep it fair.","whyEs":"Decir que no a toda la escritura trae de vuelta el problema de justicia. Ofrece una parte pequeña para mantenerlo justo.","next":"n4"},{"id":"b","say":"I can write about evaporation. Do you want to write about rain?","sayEs":"Puedo escribir sobre la evaporación. ¿Quieres escribir sobre la lluvia?","tag":"offer","q":2,"why":"'I can...' offers to help, and 'Do you want to...' gives him a real choice. Both keep the plan fair.","whyEs":"'I can...' ofrece ayuda y 'Do you want to...' le da una opción real. Ambas mantienen el plan justo.","next":"n5"},{"id":"c","say":"I write first. You write last.","sayEs":"Yo escribo primero. Tú escribes al final.","tag":"offer","q":1,"why":"A clear split, but it sounds like an order. Try 'I can write...' to sound like an offer.","whyEs":"Un reparto claro, pero suena como una orden. Prueba 'I can write...' para sonar como una oferta.","next":"n5"}]},"n3":{"who":"npc","say":"You do not like my idea? I am not sure what you mean. What would you like?","sayEs":"¿No te gusta mi idea? No estoy seguro de lo que quieres decir. ¿Qué te gustaría?","mood":"puzzled","choices":[{"id":"a","say":"No writing. Too much.","sayEs":"Escribir no. Es mucho.","tag":"explain","q":1,"why":"He understands the idea. Use 'because' and a full sentence to make your reason clear.","whyEs":"Él entiende la idea. Usa 'because' y una oración completa para que tu razón sea clara.","next":"n5"},{"id":"b","say":"I think it is better to share, because then we finish sooner.","sayEs":"Creo que es mejor compartir, porque así terminamos más pronto.","tag":"explain","q":2,"why":"'I think' softens your opinion and 'because' gives a reason. Together they make a polite, clear point.","whyEs":"'I think' suaviza tu opinión y 'because' da una razón. Juntos forman un punto claro y amable.","next":"n5"},{"id":"c","say":"You always choose the easy job.","sayEs":"Siempre eliges el trabajo fácil.","tag":"disagree","q":0,"why":"Blaming with 'always' makes people defensive. Say how you feel and what you want instead.","whyEs":"Culpar con 'always' hace que la gente se ponga a la defensiva. Di cómo te sientes y qué quieres.","next":"n6"}]},"n4":{"who":"npc","say":"Wait, this is getting tense. I want us to get a good grade. What do you want to do?","sayEs":"Espera, esto se está poniendo tenso. Quiero que tengamos una buena nota. ¿Qué quieres hacer?","mood":"concerned","choices":[{"id":"a","say":"I do not like the plan.","sayEs":"No me gusta el plan.","tag":"disagree","q":1,"why":"He hears your feeling, but you gave no reason or new idea. Add 'because' and an offer.","whyEs":"Él escucha tu sentimiento, pero no diste razón ni idea nueva. Agrega 'because' y una oferta.","next":"n6"},{"id":"b","say":"I do not want to work with you.","sayEs":"No quiero trabajar contigo.","tag":"refuse","q":0,"why":"This closes the door on teamwork. A polite no to one part is better than refusing your partner.","whyEs":"Esto cierra la puerta al trabajo en equipo. Un no amable a una parte es mejor que rechazar a tu compañero.","next":"n6"},{"id":"c","say":"Sorry. I can draw the clouds, and you can write one part.","sayEs":"Perdón. Puedo dibujar las nubes y tú puedes escribir una parte.","tag":"offer","q":2,"why":"You apologized and offered a trade. Offering a job helps fix the disagreement fast.","whyEs":"Te disculpaste y ofreciste un intercambio. Ofrecer una tarea ayuda a resolver el desacuerdo rápido.","next":"n5"}]},"n5":{"who":"npc2","say":"Can I jump in? I can color the poster. Who wants to make the title?","sayEs":"¿Puedo unirme? Yo puedo colorear el cartel. ¿Quién quiere hacer el título?","mood":"happy","choices":[{"id":"a","say":"No. I will not make the title.","sayEs":"No. No haré el título.","tag":"refuse","q":0,"why":"A flat no gives your group no other option. Offer a different job instead.","whyEs":"Un no seco no le da otra opción al grupo. Ofrece otra tarea.","next":"n6"},{"id":"b","say":"I make title. You help.","sayEs":"Yo hago el título. Tú ayudas.","tag":"offer","q":1,"why":"The plan is clear, but it sounds like an order. Use 'I can...' and 'Could you...?'","whyEs":"El plan es claro, pero suena como una orden. Usa 'I can...' y 'Could you...?'","next":"n7"},{"id":"c","say":"I can make the title. Jonah, could you help me with the letters?","sayEs":"Yo puedo hacer el título. Jonah, ¿podrías ayudarme con las letras?","tag":"offer","q":2,"why":"You offered a job and asked for help with a polite question. That shares the work fairly.","whyEs":"Ofreciste una tarea y pediste ayuda con una pregunta amable. Eso reparte el trabajo con justicia.","next":"n7"}]},"n6":{"who":"npc","say":"Hmm. We still need research on clouds. Can you do it at home tonight too?","sayEs":"Mmm. Todavía falta investigar sobre las nubes. ¿Lo puedes hacer también en casa esta noche?","mood":"neutral","choices":[{"id":"a","say":"No. I cannot tonight.","sayEs":"No. Esta noche no puedo.","tag":"refuse","q":1,"why":"It is clear, but short and without a reason. Add 'thank you' and another idea.","whyEs":"Es claro, pero corto y sin razón. Agrega 'thank you' y otra idea.","next":"end2"},{"id":"b","say":"No, thank you. I have homework tonight, but I can start in class.","sayEs":"No, gracias. Tengo tarea esta noche, pero puedo empezar en clase.","tag":"refuse","q":2,"why":"A polite no with a reason, plus another idea, keeps the group friendly and the work moving.","whyEs":"Un no amable con una razón y otra idea mantiene al grupo amigable y el trabajo avanzando.","next":"n7"},{"id":"c","say":"No way. That is your job.","sayEs":"Ni lo pienses. Ese es tu trabajo.","tag":"refuse","q":0,"why":"'No way' is harsh and blames him. Say no politely and offer a different time.","whyEs":"'No way' es duro y lo culpa. Di que no con cortesía y ofrece otro momento.","next":"end3"}]},"n7":{"who":"npc2","say":"Okay, I think we have a fair plan now. Can you read our list one more time?","sayEs":"Bien, creo que ahora tenemos un plan justo. ¿Puedes leer nuestra lista una vez más?","mood":"pleased","choices":[{"id":"a","say":"Sure. I read it.","sayEs":"Claro. Yo la leo.","tag":"accept","q":1,"why":"You said yes, and she understands. Add an offer, like 'I can also check spelling'.","whyEs":"Dijiste que sí y ella entiende. Agrega una oferta, como 'I can also check spelling'.","next":"end2"},{"id":"b","say":"Read it yourself.","sayEs":"Léela tú misma.","tag":"refuse","q":0,"why":"This sounds rude after you made a plan together. Say 'Could you read it? I am finishing my part.'","whyEs":"Esto suena grosero después de hacer un plan juntos. Di 'Could you read it? I am finishing my part.'","next":"end3"},{"id":"c","say":"Sure. I can also check our spelling while I read. Is that okay?","sayEs":"Claro. También puedo revisar la ortografía mientras leo. ¿Está bien?","tag":"offer","q":2,"why":"You said yes and offered extra help with 'I can also'. Offers like this make a team stronger.","whyEs":"Dijiste que sí y ofreciste ayuda extra con 'I can also'. Las ofertas así fortalecen a un equipo.","next":"end1"}]},"end1":{"who":"npc","say":"Great plan. This poster is going to look awesome.","sayEs":"Gran plan. Este cartel se va a ver increíble.","mood":"pleased","end":true,"outcome":"strong","wrap":"You disagreed politely, offered ideas, and said no kindly, so your group made a fair plan.","wrapEs":"Estuviste en desacuerdo con cortesía, ofreciste ideas y dijiste que no con amabilidad, así que tu grupo hizo un plan justo."},"end2":{"who":"npc","say":"Okay, let us start. We have a lot to do.","sayEs":"Bien, empecemos. Tenemos mucho que hacer.","mood":"neutral","end":true,"outcome":"ok","wrap":"The group has a plan, but some lines sounded short or bossy. 'I think...' and 'I can...' keep teamwork friendly.","wrapEs":"El grupo tiene un plan, pero algunas frases sonaron cortas o mandonas. 'I think...' y 'I can...' mantienen el trabajo en equipo amable."},"end3":{"who":"npc","say":"I think we need to talk about the plan again later.","sayEs":"Creo que tenemos que hablar del plan otra vez más tarde.","mood":"concerned","end":true,"outcome":"retry","wrap":"The disagreement is still open. Try 'I see your point, but...', give a reason, and offer a job.","wrapEs":"El desacuerdo sigue abierto. Prueba 'I see your point, but...', da una razón y ofrece una tarea."}}},
  {"id":"s35-recess-join","b":"3-5","title":"Joining a game at recess","titleEs":"Unirte a un juego en el recreo","place":"playground","goal":"Ask to join a game and make a friend.","goalEs":"Pedir unirte a un juego y hacer un amigo.","focus":["request","invite","accept"],"npc":{"name":"Tyrone","role":"classmate","roleEs":"compañero de clase","look":{"skin":"#8d5524","hair":"#1a1a1a","style":"cap","shirt":"#1f7a4d","acc":"none"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"Hey. We are playing basketball. Do you want something?","sayEs":"Oye. Estamos jugando baloncesto. ¿Quieres algo?","mood":"neutral","choices":[{"id":"a","say":"Can I play?","sayEs":"¿Puedo jugar?","tag":"request","q":1,"why":"'Can I' is a fine request and short. Adding 'please' or his name makes it warmer.","whyEs":"'Can I' es una petición correcta y corta. Agregar 'please' o su nombre la hace más cálida.","next":"n3"},{"id":"b","say":"Hi, Tyrone. May I play with you, please?","sayEs":"Hola, Tyrone. ¿Puedo jugar con ustedes, por favor?","tag":"request","q":2,"why":"You used his name, 'May I', and 'please'. That is a polite request that is easy to say yes to.","whyEs":"Usaste su nombre, 'May I' y 'please'. Es una petición amable a la que es fácil decir que sí.","next":"n2"},{"id":"c","say":"Give me the ball.","sayEs":"Dame la pelota.","tag":"request","q":0,"why":"This is a command. He will probably say no because you did not ask nicely.","whyEs":"Esto es una orden. Probablemente dirá que no porque no pediste con amabilidad.","next":"n4"}]},"n2":{"who":"npc","say":"Sure! We need one more player. Do you want to be on my team?","sayEs":"¡Claro! Nos falta un jugador. ¿Quieres estar en mi equipo?","mood":"happy","choices":[{"id":"a","say":"Give me the ball first.","sayEs":"Dame la pelota primero.","tag":"request","q":0,"why":"That is a command to someone who just invited you. It sounds bossy.","whyEs":"Es una orden a alguien que acaba de invitarte. Suena mandón.","next":"n4"},{"id":"b","say":"Yes. I play.","sayEs":"Sí. Juego.","tag":"accept","q":1,"why":"He understands you said yes. Try 'Yes, I would like that' to sound friendlier.","whyEs":"Él entiende que dijiste que sí. Prueba 'Yes, I would like that' para sonar más amable.","next":"n5"},{"id":"c","say":"Yes, I would love to! Thanks for letting me play.","sayEs":"¡Sí, me encantaría! Gracias por dejarme jugar.","tag":"accept","q":2,"why":"You accepted warmly with 'I would love to' and thanked him. That makes him glad he asked.","whyEs":"Aceptaste con calidez con 'I would love to' y le diste las gracias. Eso le alegra haber preguntado.","next":"n5"}]},"n3":{"who":"npc","say":"Sure, I guess. We need to finish this game first. Do you want to wait?","sayEs":"Bueno, supongo. Primero tenemos que terminar este juego. ¿Quieres esperar?","mood":"puzzled","choices":[{"id":"a","say":"Yes, I can wait. Thanks. May I sit on the bench?","sayEs":"Sí, puedo esperar. Gracias. ¿Puedo sentarme en la banca?","tag":"accept","q":2,"why":"You accepted the plan, thanked him, and asked politely. That shows patience and good manners.","whyEs":"Aceptaste el plan, le diste las gracias y pediste con cortesía. Eso muestra paciencia y buenos modales.","next":"n5"},{"id":"b","say":"Okay. I wait here.","sayEs":"Está bien. Espero aquí.","tag":"accept","q":1,"why":"He understands. 'I can wait here' sounds more natural.","whyEs":"Él entiende. 'I can wait here' suena más natural.","next":"n5"},{"id":"c","say":"No. I want to play now.","sayEs":"No. Quiero jugar ahora.","tag":"refuse","q":0,"why":"Pushing to play now ignores the game in progress. Waiting politely gets you a turn sooner.","whyEs":"Insistir en jugar ahora ignora el juego en curso. Esperar con cortesía te da un turno más pronto.","next":"n6"}]},"n4":{"who":"npc","say":"Hey, that is my ball. Please ask nicely.","sayEs":"Oye, esa es mi pelota. Pídelo con amabilidad, por favor.","mood":"concerned","choices":[{"id":"a","say":"Sorry. Can I play?","sayEs":"Perdón. ¿Puedo jugar?","tag":"request","q":1,"why":"He hears your sorry and your question. 'Please' would make it sound even kinder.","whyEs":"Él escucha tu perdón y tu pregunta. 'Please' lo haría sonar aún más amable.","next":"n6"},{"id":"b","say":"It is just a ball.","sayEs":"Es solo una pelota.","tag":"disagree","q":0,"why":"This ignores his feelings and keeps the argument going. Apologize first, then ask again.","whyEs":"Esto ignora sus sentimientos y mantiene la discusión. Primero discúlpate y luego pregunta otra vez.","next":"n6"},{"id":"c","say":"I am sorry. Could I please play with you?","sayEs":"Lo siento. ¿Podría jugar con ustedes, por favor?","tag":"request","q":2,"why":"You apologized and asked again with 'Could I please'. Repairing with polite words works.","whyEs":"Te disculpaste y pediste otra vez con 'Could I please'. Reparar con palabras amables funciona.","next":"n5"}]},"n5":{"who":"npc","say":"Okay, you are on my team. Can you also invite Priya? She is standing alone by the fence.","sayEs":"Bien, estás en mi equipo. ¿Puedes invitar también a Priya? Está sola junto a la cerca.","mood":"pleased","choices":[{"id":"a","say":"No. We have enough players.","sayEs":"No. Ya tenemos suficientes jugadores.","tag":"refuse","q":0,"why":"Leaving a classmate out can hurt. Invite her kindly, or say the next game has room.","whyEs":"Dejar fuera a una compañera puede doler. Invítala con amabilidad o di que el próximo juego tiene lugar.","next":"n6"},{"id":"b","say":"Good idea. Hi Priya, would you like to play with us?","sayEs":"Buena idea. Hola Priya, ¿te gustaría jugar con nosotros?","tag":"invite","q":2,"why":"'Would you like to...' is a kind invitation. You included someone who was alone.","whyEs":"'Would you like to...' es una invitación amable. Incluiste a alguien que estaba sola.","next":"n7"},{"id":"c","say":"Priya, play with us.","sayEs":"Priya, juega con nosotros.","tag":"invite","q":1,"why":"She understands. 'Would you like to play?' sounds like a choice instead of an order.","whyEs":"Ella entiende. 'Would you like to play?' suena como una opción y no como una orden.","next":"n7"}]},"n6":{"who":"npc","say":"Hmm. Okay. Do you want to join the next game, or are you going to do something else?","sayEs":"Mmm. Bueno. ¿Quieres unirte al próximo juego o vas a hacer otra cosa?","mood":"neutral","choices":[{"id":"a","say":"I would like to join the next game, please. Thank you for asking.","sayEs":"Me gustaría unirme al próximo juego, por favor. Gracias por preguntar.","tag":"accept","q":2,"why":"You accepted clearly with 'I would like to' and thanked him. That is polite and warm.","whyEs":"Aceptaste con claridad con 'I would like to' y le diste las gracias. Es amable y cálido.","next":"n7"},{"id":"b","say":"I do not care. Bye.","sayEs":"No me importa. Adiós.","tag":"refuse","q":0,"why":"This sounds like you do not want to be friends. Say what you want, even if it is small.","whyEs":"Esto suena como si no quisieras ser su amigo. Di lo que quieres, aunque sea poco.","next":"end3"},{"id":"c","say":"Yes. Next game.","sayEs":"Sí. El próximo juego.","tag":"accept","q":1,"why":"He gets your answer. Add 'I would like to join' for a full, friendly sentence.","whyEs":"Él entiende tu respuesta. Agrega 'I would like to join' para una oración completa y amable.","next":"end2"}]},"n7":{"who":"npc","say":"That was a fun game! Do you want to play with us again tomorrow?","sayEs":"¡Qué juego tan divertido! ¿Quieres jugar con nosotros otra vez mañana?","mood":"happy","choices":[{"id":"a","say":"Yes. Tomorrow.","sayEs":"Sí. Mañana.","tag":"accept","q":1,"why":"He understands you said yes. A full sentence with 'I would love to' sounds friendlier.","whyEs":"Él entiende que dijiste que sí. Una oración completa con 'I would love to' suena más amable.","next":"end2"},{"id":"b","say":"Maybe. I do not know.","sayEs":"Quizás. No sé.","tag":"refuse","q":0,"why":"'Maybe' with no reason can feel like a no. A clear answer helps a new friend.","whyEs":"'Maybe' sin razón puede sentirse como un no. Una respuesta clara ayuda a un nuevo amigo.","next":"end3"},{"id":"c","say":"Yes, I would love to play again tomorrow. See you here!","sayEs":"Sí, me encantaría jugar otra vez mañana. ¡Nos vemos aquí!","tag":"accept","q":2,"why":"You accepted warmly and made a plan to meet. That shows you want to be friends.","whyEs":"Aceptaste con calidez y planeaste encontrarse. Eso muestra que quieres ser su amigo.","next":"end1"}]},"end1":{"who":"npc","say":"Great! See you at recess tomorrow.","sayEs":"¡Genial! Nos vemos mañana en el recreo.","mood":"pleased","end":true,"outcome":"strong","wrap":"You asked politely, accepted kindly, and invited another classmate, so you joined the game and made friends.","wrapEs":"Pediste con cortesía, aceptaste con amabilidad e invitaste a otra compañera, así que te uniste al juego y hiciste amigos."},"end2":{"who":"npc","say":"Okay. See you around.","sayEs":"Bien. Nos vemos por ahí.","mood":"neutral","end":true,"outcome":"ok","wrap":"You got to play, but some lines were short. 'May I...' and 'I would love to...' sound friendlier.","wrapEs":"Pudiste jugar, pero algunas frases fueron cortas. 'May I...' y 'I would love to...' suenan más amables."},"end3":{"who":"npc","say":"Maybe next time, okay? Please ask nicely.","sayEs":"Quizás la próxima vez, ¿sí? Pide con amabilidad, por favor.","mood":"concerned","end":true,"outcome":"retry","wrap":"The game went on without you. Try again with 'May I play, please?' and accept with 'I would love to.'","wrapEs":"El juego siguió sin ti. Inténtalo otra vez con 'May I play, please?' y acepta con 'I would love to.'"}}},
  {"id":"s35-lost-jacket","b":"3-5","title":"Lost and found","titleEs":"Objetos perdidos","place":"hallway","goal":"Describe your lost jacket and find it.","goalEs":"Describir tu chaqueta perdida y encontrarla.","focus":["describe","question","thank"],"npc":{"name":"Kwame","role":"hallway helper","roleEs":"ayudante del pasillo","look":{"skin":"#8d5524","hair":"#1a1a1a","style":"afro","shirt":"#d89b1c","acc":"none"}},"npc2":{"name":"Ms. Dubois","role":"lost-and-found teacher","roleEs":"maestra de objetos perdidos","look":{"skin":"#f1c9a5","hair":"#7a4a2a","style":"ponytail","shirt":"#5a4fa3","acc":"glasses"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"Hi! Are you looking for something? You seem worried.","sayEs":"¡Hola! ¿Buscas algo? Parece que algo te preocupa.","mood":"neutral","choices":[{"id":"a","say":"I lost jacket. Blue one.","sayEs":"Perdí chaqueta. La azul.","tag":"describe","q":1,"why":"He can guess your meaning. Use 'my jacket' and 'It is blue' to be clear.","whyEs":"Él puede adivinar lo que quieres decir. Usa 'my jacket' y 'It is blue' para ser claro.","next":"n3"},{"id":"b","say":"Somebody took my jacket!","sayEs":"¡Alguien se llevó mi chaqueta!","tag":"describe","q":0,"why":"Blaming someone without proof can upset people. Say 'I lost my jacket' and describe it instead.","whyEs":"Culpar a alguien sin pruebas puede molestar a las personas. Di 'I lost my jacket' y descríbela.","next":"n4"},{"id":"c","say":"Yes, I lost my jacket. It is blue and has a hood.","sayEs":"Sí, perdí mi chaqueta. Es azul y tiene capucha.","tag":"describe","q":2,"why":"You said the problem, the color, and one detail. Clear details help him know what to look for.","whyEs":"Dijiste el problema, el color y un detalle. Los detalles claros lo ayudan a saber qué buscar.","next":"n2"}]},"n2":{"who":"npc","say":"Okay, blue with a hood. Where did you see it last?","sayEs":"Bien, azul con capucha. ¿Dónde la viste por última vez?","mood":"happy","choices":[{"id":"a","say":"I last saw it in the gym, near the door.","sayEs":"La vi por última vez en el gimnasio, cerca de la puerta.","tag":"describe","q":2,"why":"You said where you saw it. A clear place narrows the search a lot.","whyEs":"Dijiste dónde la viste. Un lugar claro reduce mucho la búsqueda.","next":"n5"},{"id":"b","say":"Gym. After class.","sayEs":"Gimnasio. Después de clase.","tag":"describe","q":1,"why":"He understands. A full sentence, like 'I saw it in the gym', is clearer.","whyEs":"Él entiende. Una oración completa, como 'I saw it in the gym', es más clara.","next":"n5"},{"id":"c","say":"I do not know. It is gone.","sayEs":"No sé. Ya no está.","tag":"describe","q":0,"why":"With no place to look, he cannot help. Think of one place, even if you are not sure.","whyEs":"Sin un lugar donde buscar, él no puede ayudar. Piensa en un lugar, aunque no estés seguro.","next":"n4"}]},"n3":{"who":"npc","say":"A blue jacket? Is it big or small? Does it have anything on it?","sayEs":"¿Una chaqueta azul? ¿Es grande o pequeña? ¿Tiene algo escrito o dibujado?","mood":"puzzled","choices":[{"id":"a","say":"It is just a jacket.","sayEs":"Es solo una chaqueta.","tag":"describe","q":0,"why":"That gives no clues, so he cannot tell yours from the others. Mention size, color, or a mark.","whyEs":"Eso no da pistas y él no puede distinguir la tuya. Menciona el tamaño, el color o una marca.","next":"n6"},{"id":"b","say":"It is medium size. It has a white stripe on one sleeve.","sayEs":"Es de talla mediana. Tiene una raya blanca en una manga.","tag":"describe","q":2,"why":"You gave the size and a special mark. These details tell yours apart from the others.","whyEs":"Diste el tamaño y una marca especial. Estos detalles distinguen la tuya de las demás.","next":"n5"},{"id":"c","say":"Medium. Stripe white.","sayEs":"Mediana. Raya blanca.","tag":"describe","q":1,"why":"He gets the key facts. Say 'It has a white stripe' to put the words in order.","whyEs":"Él entiende los datos clave. Di 'It has a white stripe' para poner las palabras en orden.","next":"n5"}]},"n4":{"who":"npc","say":"Oh no. I want to help. Can you tell me more about it? What does it look like?","sayEs":"Ay, no. Quiero ayudarte. ¿Puedes contarme más? ¿Cómo es?","mood":"concerned","choices":[{"id":"a","say":"Blue. Big hood.","sayEs":"Azul. Capucha grande.","tag":"describe","q":1,"why":"He gets some clues. A full sentence gives him more to search with.","whyEs":"Él recibe algunas pistas. Una oración completa le da más para buscar.","next":"n6"},{"id":"b","say":"It is a blue jacket with a hood and a white stripe.","sayEs":"Es una chaqueta azul con capucha y una raya blanca.","tag":"describe","q":2,"why":"You joined three details with 'with' and 'and'. That paints a clear picture for him.","whyEs":"Uniste tres detalles con 'with' y 'and'. Eso le da una imagen clara.","next":"n5"},{"id":"c","say":"Can you not just find it?","sayEs":"¿No puedes simplemente encontrarla?","tag":"question","q":0,"why":"This question sounds impatient and gives no clues. He can help more if you describe the jacket.","whyEs":"Esta pregunta suena impaciente y no da pistas. Él puede ayudar más si describes la chaqueta.","next":"n6"}]},"n5":{"who":"npc2","say":"I run the lost and found. We have two blue jackets. How can you tell yours?","sayEs":"Yo estoy a cargo de objetos perdidos. Tenemos dos chaquetas azules. ¿Cómo puedes saber cuál es la tuya?","mood":"pleased","choices":[{"id":"a","say":"Mine has a white stripe. Does one of them have a stripe?","sayEs":"La mía tiene una raya blanca. ¿Alguna de ellas tiene una raya?","tag":"question","q":2,"why":"You gave a clue and asked a 'Does...' question. That helps her find yours.","whyEs":"Diste una pista e hiciste una pregunta con 'Does...'. Eso la ayuda a encontrar la tuya.","next":"n7"},{"id":"b","say":"Just give me one.","sayEs":"Solo dame una.","tag":"request","q":0,"why":"That is a command, and you could take the wrong jacket. Describe yours and ask to look.","whyEs":"Eso es una orden y podrías llevarte la chaqueta equivocada. Describe la tuya y pide verlas.","next":"n6"},{"id":"c","say":"Stripe white. Is this?","sayEs":"Raya blanca. ¿Es esta?","tag":"question","q":1,"why":"She can follow you. 'Is this one mine?' is the complete question form.","whyEs":"Ella te puede seguir. 'Is this one mine?' es la forma completa de la pregunta.","next":"n7"}]},"n6":{"who":"npc","say":"Hmm, I want to be sure. Is there a name or a mark inside the jacket?","sayEs":"Mmm, quiero asegurarme. ¿Hay un nombre o una marca adentro de la chaqueta?","mood":"neutral","choices":[{"id":"a","say":"I do not know. Forget it.","sayEs":"No sé. Olvídalo.","tag":"refuse","q":0,"why":"Giving up leaves your jacket lost. Check the collar or pocket before you decide.","whyEs":"Rendirte deja tu chaqueta perdida. Revisa el cuello o el bolsillo antes de decidir.","next":"end3"},{"id":"b","say":"Name inside. Maybe.","sayEs":"Nombre adentro. Quizás.","tag":"describe","q":1,"why":"He gets the idea. Say 'I think my name is inside' to sound clearer.","whyEs":"Él entiende la idea. Di 'I think my name is inside' para sonar más claro.","next":"end2"},{"id":"c","say":"Yes, my initials are inside the collar.","sayEs":"Sí, mis iniciales están dentro del cuello.","tag":"describe","q":2,"why":"You gave a private detail only the owner knows. That proves it is your jacket.","whyEs":"Diste un detalle privado que solo el dueño conoce. Eso prueba que es tu chaqueta.","next":"n7"}]},"n7":{"who":"npc","say":"Look, here is a blue jacket with a white stripe. Is this yours?","sayEs":"Mira, aquí hay una chaqueta azul con una raya blanca. ¿Es la tuya?","mood":"pleased","choices":[{"id":"a","say":"Yes. Thank you.","sayEs":"Sí. Gracias.","tag":"thank","q":1,"why":"Thanks is polite. Add what you are thankful for to sound warmer.","whyEs":"Dar las gracias es amable. Agrega por qué agradeces para sonar más cálido.","next":"end2"},{"id":"b","say":"Yes, that is mine! Thank you so much for helping me.","sayEs":"¡Sí, es la mía! Muchas gracias por ayudarme.","tag":"thank","q":2,"why":"You said yes, then thanked him for helping. Specific thanks make people feel appreciated.","whyEs":"Dijiste que sí y luego le agradeciste por ayudar. Un agradecimiento concreto hace que se sientan valorados.","next":"end1"},{"id":"c","say":"Yes. Finally. You took forever.","sayEs":"Sí. Por fin. Tardaste mucho.","tag":"thank","q":0,"why":"Complaining while someone helps can hurt feelings. Say thank you instead.","whyEs":"Quejarte mientras alguien ayuda puede herir sus sentimientos. Mejor di gracias.","next":"end3"}]},"end1":{"who":"npc","say":"Great! Next time put your name on the tag, okay?","sayEs":"¡Genial! La próxima vez pon tu nombre en la etiqueta, ¿sí?","mood":"happy","end":true,"outcome":"strong","wrap":"You described your jacket clearly, asked a good question, and said thank you, so you found it fast.","wrapEs":"Describiste tu chaqueta con claridad, hiciste una buena pregunta y diste las gracias, así que la encontraste rápido."},"end2":{"who":"npc","say":"Here you go. Check your pockets, okay?","sayEs":"Aquí tienes. Revisa tus bolsillos, ¿sí?","mood":"neutral","end":true,"outcome":"ok","wrap":"You found your jacket, but some details were short. Color, size, and a mark help helpers find things quickly.","wrapEs":"Encontraste tu chaqueta, pero algunos detalles fueron cortos. El color, el tamaño y una marca ayudan a encontrar las cosas rápido."},"end3":{"who":"npc","say":"I am sorry, I could not find it. Come back when you remember more details.","sayEs":"Lo siento, no pude encontrarla. Vuelve cuando recuerdes más detalles.","mood":"concerned","end":true,"outcome":"retry","wrap":"The helper did not have enough clues. Next time, describe the color, size, and a mark, and say thank you.","wrapEs":"El ayudante no tuvo suficientes pistas. La próxima vez, describe el color, el tamaño y una marca, y di gracias."}}},
  {"id":"s68-schedule-change","b":"6-8","title":"Changing a class schedule","titleEs":"Cambiar un horario de clases","place":"office","goal":"Ask the counselor to switch you from one elective class to another.","goalEs":"Pedirle al consejero que te cambie de una clase optativa a otra.","focus":["greet","request","thank"],"npc":{"name":"Mr. Okafor","role":"school counselor","roleEs":"consejero escolar","look":{"skin":"#5c3a21","hair":"#1a1a1a","style":"short","shirt":"#7a3e8e","acc":"glasses"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"Hi there, come on in. I am Mr. Okafor, one of the school counselors. What can I do for you today?","sayEs":"Hola, pasa. Soy el Sr. Okafor, uno de los consejeros escolares. ¿En qué te puedo ayudar hoy?","mood":"neutral","choices":[{"id":"a","say":"I want a new schedule. Change my art class right now.","sayEs":"Quiero un horario nuevo. Cambia mi clase de arte ahora mismo.","tag":"request","q":0,"why":"A command with no greeting or 'please' sounds demanding, so the counselor has to pause and ask what you mean.","whyEs":"Una orden sin saludo ni 'por favor' suena exigente, y el consejero tiene que detenerse a preguntarte qué quieres decir.","next":"n2b"},{"id":"b","say":"Hello, Mr. Okafor. Thank you for seeing me. I would like to talk with you about changing my schedule.","sayEs":"Hola, Sr. Okafor. Gracias por recibirme. Me gustaría hablar contigo sobre cambiar mi horario.","tag":"greet","q":2,"why":"You greeted him, thanked him, and used 'I would like to' to begin politely. That sets a friendly tone.","whyEs":"Lo saludaste, le diste las gracias y usaste 'I would like to' para empezar con cortesía. Eso crea un ambiente amable.","next":"n2"},{"id":"c","say":"Hi. I need change my schedule, please.","sayEs":"Hola. Necesito cambiar mi horario, por favor.","tag":"request","q":1,"why":"'Please' is polite, but the sentence needs 'to': 'I need to change my schedule.' He still understands you.","whyEs":"'Please' es cortés, pero falta 'to': 'I need to change my schedule'. Aun así, él te entiende.","next":"n2b"}]},"n2":{"who":"npc","say":"Welcome. Have a seat. What would you like to change?","sayEs":"Bienvenido. Toma asiento. ¿Qué te gustaría cambiar?","mood":"pleased","choices":[{"id":"a","say":"I want to leave art. I like music more.","sayEs":"Quiero dejar arte. Me gusta más la música.","tag":"explain","q":1,"why":"You gave a clear reason, but it sounds like a demand. Add 'Could I...' to ask for the change politely.","whyEs":"Diste una razón clara, pero suena como una exigencia. Agrega 'Could I...' para pedir el cambio con cortesía.","next":"n3"},{"id":"b","say":"Why is my schedule wrong? Who made it like this?","sayEs":"¿Por qué mi horario está mal? ¿Quién lo hizo así?","tag":"question","q":0,"why":"This question sounds like blame, and it does not say what you want. The counselor needs a clear request.","whyEs":"Esta pregunta suena a reproche y no dice lo que quieres. El consejero necesita una petición clara.","next":"n2b"},{"id":"c","say":"Could I please switch from art to band? I think I would learn more there, and I really enjoy playing drums.","sayEs":"¿Podría cambiarme de arte a banda, por favor? Creo que aprendería más allí y disfruto mucho tocar la batería.","tag":"request","q":2,"why":"'Could I please' is a polite request, and your reason with 'I think' shows you thought about it.","whyEs":"'Could I please' es una petición cortés, y tu razón con 'I think' muestra que lo pensaste.","next":"n3"}]},"n2b":{"who":"npc","say":"I want to help, but I am not sure what you need yet. Which class do you want to change, and to which one?","sayEs":"Quiero ayudarte, pero todavía no estoy seguro de lo que necesitas. ¿Qué clase quieres cambiar y por cuál?","mood":"puzzled","choices":[{"id":"a","say":"Of course. Could I please move from Art to Band? Band is open during the same period.","sayEs":"Claro. ¿Podría pasarme de Arte a Banda, por favor? Banda está abierta en el mismo periodo.","tag":"request","q":2,"why":"You named both classes and used 'Could I please'. A specific, polite request is easy for him to act on.","whyEs":"Nombraste ambas clases y usaste 'Could I please'. Una petición específica y cortés es fácil de atender.","next":"n3"},{"id":"b","say":"Please change art. I want band.","sayEs":"Por favor cambia arte. Quiero banda.","tag":"request","q":1,"why":"Naming the classes helps. 'Could you change...?' and 'I would like...' would sound more polite.","whyEs":"Nombrar las clases ayuda. 'Could you change...?' e 'I would like...' sonarían más corteses.","next":"n3"},{"id":"c","say":"Just change it. I do not like it.","sayEs":"Solo cámbialo. No me gusta.","tag":"explain","q":0,"why":"'It' does not say which class, and the tone is blunt. He still does not know what to do.","whyEs":"'It' no dice qué clase es y el tono es brusco. Él todavía no sabe qué hacer.","next":"end3"}]},"n3":{"who":"npc","say":"Let me check. Band has two open seats. Your art teacher would need to sign a change form. Does that work for you?","sayEs":"Déjame revisar. Banda tiene dos lugares libres. Tu maestro de arte tendría que firmar un formulario de cambio. ¿Te funciona?","mood":"neutral","choices":[{"id":"a","say":"Why do I need a signature? That is silly.","sayEs":"¿Por qué necesito una firma? Eso es tonto.","tag":"question","q":0,"why":"Calling a rule silly sounds rude. Asking 'Could you explain why the form is needed?' is more respectful.","whyEs":"Decir que una regla es tonta suena grosero. Preguntar 'Could you explain why the form is needed?' es más respetuoso.","next":"end3"},{"id":"b","say":"Yes, that works. Thank you for checking. I will ask my art teacher for the signature today.","sayEs":"Sí, me funciona. Gracias por revisar. Hoy le pediré la firma a mi maestro de arte.","tag":"thank","q":2,"why":"You accepted the plan, thanked him, and said what you will do. That shows responsibility.","whyEs":"Aceptaste el plan, le diste las gracias y dijiste lo que harás. Eso muestra responsabilidad.","next":"n4"},{"id":"c","say":"Okay. I ask the teacher. Thanks.","sayEs":"Está bien. Le pregunto al maestro. Gracias.","tag":"accept","q":1,"why":"You agreed and thanked him, which is good. Add 'I will' and a full sentence to sound more confident.","whyEs":"Aceptaste y le diste las gracias, lo cual está bien. Agrega 'I will' y una oración completa para sonar más seguro.","next":"n4"}]},"n4":{"who":"npc","say":"Good plan. Bring the signed form back by Friday. Is there anything else you need from me?","sayEs":"Buen plan. Trae el formulario firmado a más tardar el viernes. ¿Necesitas algo más de mí?","mood":"pleased","choices":[{"id":"a","say":"Give me the form now. I am in a hurry.","sayEs":"Dame el formulario ahora. Tengo prisa.","tag":"request","q":0,"why":"A direct command with no 'please' sounds impatient. 'May I have the form, please?' is polite.","whyEs":"Una orden directa sin 'please' suena impaciente. 'May I have the form, please?' es cortés.","next":"end3"},{"id":"b","say":"No. Thank you. Bye.","sayEs":"No. Gracias. Adiós.","tag":"thank","q":1,"why":"Thanking him is good, but it is very short. Add his name and your plan to sound warm.","whyEs":"Darle las gracias está bien, pero es muy corto. Agrega su nombre y tu plan para sonar amable.","next":"end2"},{"id":"c","say":"That is all for now. Thank you for your help, Mr. Okafor. I will bring the form back on Thursday.","sayEs":"Eso es todo por ahora. Gracias por tu ayuda, Sr. Okafor. Traeré el formulario el jueves.","tag":"thank","q":2,"why":"You thanked him by name and gave a clear plan. That ends the visit politely and builds trust.","whyEs":"Le agradeciste por su nombre y diste un plan claro. Eso termina la visita con cortesía y genera confianza.","next":"end1"}]},"end1":{"who":"npc","say":"Perfect. See you Thursday, and enjoy band!","sayEs":"Perfecto. Nos vemos el jueves, ¡y disfruta banda!","mood":"happy","end":true,"outcome":"strong","wrap":"Mr. Okafor approved the plan. Greeting him, asking with 'Could I please', and thanking him made the visit smooth.","wrapEs":"El Sr. Okafor aprobó el plan. Saludar, pedir con 'Could I please' y agradecer hicieron fácil la visita."},"end2":{"who":"npc","say":"Okay. Remember, the form is due Friday.","sayEs":"Está bien. Recuerda, el formulario vence el viernes.","mood":"pleased","end":true,"outcome":"ok","wrap":"You got what you needed, but short answers sounded rushed. Add a reason and a full thank-you next time.","wrapEs":"Conseguiste lo que necesitabas, pero las respuestas cortas sonaron apuradas. La próxima vez agrega una razón y un agradecimiento completo."},"end3":{"who":"npc","say":"I think we should talk again another day. My door is always open.","sayEs":"Creo que deberíamos hablar otro día. Mi puerta siempre está abierta.","mood":"concerned","end":true,"outcome":"retry","wrap":"The request was unclear or sounded demanding. Try a greeting, name the class, and use 'Could I please' to ask.","wrapEs":"La petición no fue clara o sonó exigente. Intenta saludar, nombrar la clase y usar 'Could I please' para pedir."}}},
  {"id":"s68-extension","b":"6-8","title":"Asking for more time and help","titleEs":"Pedir más tiempo y ayuda","place":"classroom","goal":"Ask your teacher for more time on a report and for extra help.","goalEs":"Pedirle a tu maestra más tiempo para un informe y ayuda extra.","focus":["apologize","explain","request"],"npc":{"name":"Ms. Nakamura","role":"science teacher","roleEs":"maestra de ciencias","look":{"skin":"#f1c9a5","hair":"#1a1a1a","style":"ponytail","shirt":"#2e7d6b","acc":"none"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"Hi. I noticed your lab report was not turned in yesterday. Would you like to talk about it?","sayEs":"Hola. Noté que ayer no entregaste tu informe de laboratorio. ¿Quieres hablar de eso?","mood":"concerned","choices":[{"id":"a","say":"Yes, thank you. I am sorry I did not turn it in. I would like to explain what happened.","sayEs":"Sí, gracias. Lamento no haberlo entregado. Me gustaría explicarte lo que pasó.","tag":"apologize","q":2,"why":"You said 'I am sorry' first and offered to explain. That shows respect and makes the teacher ready to listen.","whyEs":"Primero dijiste 'I am sorry' y ofreciste explicar. Eso muestra respeto y hace que la maestra quiera escuchar.","next":"n2"},{"id":"b","say":"It is not my fault. The report was too long and too hard.","sayEs":"No es mi culpa. El informe era demasiado largo y difícil.","tag":"explain","q":0,"why":"Blaming the assignment before saying sorry sounds defensive. The teacher may stop listening to your reason.","whyEs":"Culpar a la tarea antes de pedir perdón suena a defensa. La maestra podría dejar de escuchar tu razón.","next":"n2b"},{"id":"c","say":"Yes. Sorry, teacher. I not finish my report.","sayEs":"Sí. Perdón, maestra. No terminé mi informe.","tag":"apologize","q":1,"why":"Saying sorry is good. Use the past tense: 'I did not finish my report.' The meaning is still clear.","whyEs":"Pedir perdón está bien. Usa el pasado: 'I did not finish my report'. El significado igual es claro.","next":"n2b"}]},"n2":{"who":"npc","say":"Thank you for coming to me. Tell me what happened.","sayEs":"Gracias por venir a hablar conmigo. Cuéntame qué pasó.","mood":"pleased","choices":[{"id":"a","say":"I need more days. Please give me more days.","sayEs":"Necesito más días. Por favor, dame más días.","tag":"request","q":1,"why":"'Please' helps, but you gave no reason and used a command. Try 'Could I have until Friday?'","whyEs":"'Please' ayuda, pero no diste razón y usaste una orden. Prueba 'Could I have until Friday?'","next":"n3"},{"id":"b","say":"My family had visitors this weekend, so I only finished the data table. Could I have until Friday for the rest?","sayEs":"Mi familia tuvo visitas este fin de semana, así que solo terminé la tabla de datos. ¿Podría tener hasta el viernes para el resto?","tag":"explain","q":2,"why":"You gave a reason with 'so' and asked with 'Could I'. A reason plus a polite request is persuasive.","whyEs":"Diste una razón con 'so' y pediste con 'Could I'. Una razón junto con una petición cortés convence.","next":"n3"},{"id":"c","say":"Just give me extra time. Other teachers always say yes.","sayEs":"Solo dame tiempo extra. Otros maestros siempre dicen que sí.","tag":"request","q":0,"why":"A command and a comparison with other teachers sounds pushy. It gives her no reason to agree.","whyEs":"Una orden y una comparación con otros maestros suena insistente. No le da razones para aceptar.","next":"n2b"}]},"n2b":{"who":"npc","say":"I want to help, but I need to understand. What got in the way of finishing the report?","sayEs":"Quiero ayudarte, pero necesito entender. ¿Qué te impidió terminar el informe?","mood":"puzzled","choices":[{"id":"a","say":"Conclusion is hard. I wait too long.","sayEs":"La conclusión es difícil. Esperé demasiado.","tag":"explain","q":1,"why":"Your reason is honest and clear. Use full sentences: 'I waited too long because the conclusion was hard.'","whyEs":"Tu razón es honesta y clara. Usa oraciones completas: 'I waited too long because the conclusion was hard'.","next":"n3"},{"id":"b","say":"Whatever. Can I just skip that part?","sayEs":"Lo que sea. ¿Puedo saltarme esa parte?","tag":"request","q":0,"why":"'Whatever' sounds like you do not care, and asking to skip work does not solve the problem.","whyEs":"'Whatever' suena como si no te importara, y pedir saltarte el trabajo no resuelve el problema.","next":"end3"},{"id":"c","say":"I am sorry for the confusion. I did not understand the conclusion, so I waited too long to start.","sayEs":"Lamento la confusión. No entendí la conclusión, así que esperé demasiado para empezar.","tag":"explain","q":2,"why":"You apologized and used 'so' to link the reason to the result. That makes the problem easy to understand.","whyEs":"Pediste perdón y usaste 'so' para unir la razón con el resultado. Así el problema se entiende fácilmente.","next":"n3"}]},"n3":{"who":"npc","say":"Thank you for telling me the truth. You may have until Friday. Would you also like some extra help with the conclusion?","sayEs":"Gracias por decirme la verdad. Puedes tener hasta el viernes. ¿También quieres ayuda extra con la conclusión?","mood":"pleased","choices":[{"id":"a","say":"No. I do not need help from anybody.","sayEs":"No. No necesito ayuda de nadie.","tag":"refuse","q":0,"why":"A blunt no sounds closed off. 'No, thank you, I will try first' keeps the door open.","whyEs":"Un no seco suena cerrado. 'No, thank you, I will try first' deja la puerta abierta.","next":"end2"},{"id":"b","say":"Yes, please. Could we meet at lunch on Wednesday? I would like to show you my draft and ask some questions.","sayEs":"Sí, por favor. ¿Podríamos reunirnos el miércoles en el almuerzo? Me gustaría mostrarte mi borrador y hacerte algunas preguntas.","tag":"request","q":2,"why":"'Could we' and 'I would like to' ask for help politely, and you gave a specific day and plan.","whyEs":"'Could we' e 'I would like to' piden ayuda con cortesía, y diste un día y un plan específicos.","next":"n4"},{"id":"c","say":"Yes. Wednesday lunch is okay for me.","sayEs":"Sí. El almuerzo del miércoles me parece bien.","tag":"accept","q":1,"why":"You accepted and named a day, which is good. Add 'please' and why you want help to sound warmer.","whyEs":"Aceptaste y nombraste un día, lo cual está bien. Agrega 'please' y por qué quieres ayuda para sonar más amable.","next":"n4"}]},"n4":{"who":"npc","say":"Great. Wednesday at lunch, in my room. Bring your draft and your questions. Anything else?","sayEs":"Perfecto. El miércoles en el almuerzo, en mi salón. Trae tu borrador y tus preguntas. ¿Algo más?","mood":"happy","choices":[{"id":"a","say":"No. Thank you, teacher.","sayEs":"No. Gracias, maestra.","tag":"thank","q":1,"why":"Thanking her is polite. A little more detail, like what you will bring, shows you are ready.","whyEs":"Darle las gracias es cortés. Un poco más de detalle, como lo que traerás, muestra que estás preparado.","next":"end2"},{"id":"b","say":"I might not come. I will see if I feel like it.","sayEs":"Quizás no vaya. Veré si tengo ganas.","tag":"explain","q":0,"why":"This takes back your request. It sounds like you do not value her time.","whyEs":"Esto retira tu petición. Suena como si no valoraras su tiempo.","next":"end3"},{"id":"c","say":"That is all. Thank you for being patient, Ms. Nakamura. I will bring my draft and my questions on Wednesday.","sayEs":"Eso es todo. Gracias por tener paciencia, Sra. Nakamura. Traeré mi borrador y mis preguntas el miércoles.","tag":"thank","q":2,"why":"You thanked her by name and repeated the plan. This shows you listened and will follow through.","whyEs":"Le agradeciste por su nombre y repetiste el plan. Esto muestra que escuchaste y cumplirás.","next":"end1"}]},"end1":{"who":"npc","say":"Wonderful. I will see you Wednesday, and we will make that conclusion strong.","sayEs":"Excelente. Te veo el miércoles y haremos que esa conclusión quede muy bien.","mood":"happy","end":true,"outcome":"strong","wrap":"You apologized, explained with 'so', and asked politely. Ms. Nakamura gave you time and set up extra help.","wrapEs":"Pediste perdón, explicaste con 'so' y pediste con cortesía. La Sra. Nakamura te dio tiempo y organizó ayuda extra."},"end2":{"who":"npc","say":"Okay. You have until Friday. My offer to help is still open.","sayEs":"Está bien. Tienes hasta el viernes. Mi oferta de ayuda sigue abierta.","mood":"pleased","end":true,"outcome":"ok","wrap":"You got more time, but you missed or rushed the chance for help. A polite 'yes, please' makes help easier.","wrapEs":"Conseguiste más tiempo, pero perdiste o apuraste la oportunidad de recibir ayuda. Un 'yes, please' cortés facilita la ayuda."},"end3":{"who":"npc","say":"Let us talk again tomorrow when you have a plan. I do want to help.","sayEs":"Hablemos de nuevo mañana, cuando tengas un plan. Sí quiero ayudarte.","mood":"concerned","end":true,"outcome":"retry","wrap":"The reason or tone made it hard for her to help. Try 'I am sorry' plus 'because' or 'so', and ask with 'Could I'.","wrapEs":"La razón o el tono le dificultaron ayudarte. Prueba 'I am sorry' con 'because' o 'so', y pide con 'Could I'."}}},
  {"id":"s68-group-plan","b":"6-8","title":"Disagreeing in a group project","titleEs":"No estar de acuerdo en un trabajo en grupo","place":"classroom","goal":"Disagree politely about the project plan and help your group reach a compromise.","goalEs":"No estar de acuerdo con respeto sobre el plan del proyecto y ayudar a tu grupo a llegar a un acuerdo.","focus":["disagree","offer","accept"],"npc":{"name":"Kwame","role":"group member","roleEs":"compañero de equipo","look":{"skin":"#5c3a21","hair":"#1a1a1a","style":"cap","shirt":"#c0561b","acc":"none"}},"npc2":{"name":"Mei","role":"group member","roleEs":"compañera de equipo","look":{"skin":"#f5d5b8","hair":"#1a1a1a","style":"long","shirt":"#2f5fa0","acc":"glasses"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"I think we should split the slides, work alone at home, and put everything together on Friday. That is the fastest way.","sayEs":"Yo pienso que deberíamos dividir las diapositivas, trabajar solos en casa y juntar todo el viernes. Es la forma más rápida.","mood":"neutral","choices":[{"id":"a","say":"I do not agree. Working alone is not good idea.","sayEs":"No estoy de acuerdo. Trabajar solos no es buena idea.","tag":"disagree","q":1,"why":"You said what you think, but it sounds blunt and gives no reason. 'I see your point, but...' is softer.","whyEs":"Dijiste lo que piensas, pero suena directo y sin razón. 'I see your point, but...' es más suave.","next":"n2b"},{"id":"b","say":"That is a dumb plan. I am not doing it.","sayEs":"Ese plan es tonto. No lo voy a hacer.","tag":"disagree","q":0,"why":"Insulting the plan hurts feelings and stops teamwork. Polite disagreement attacks the problem, not the person.","whyEs":"Insultar el plan hiere sentimientos y detiene el trabajo en equipo. El desacuerdo cortés ataca el problema, no a la persona.","next":"n2b"},{"id":"c","say":"I see your point, Kwame, but I worry our slides will not match. Maybe we could plan the design together first?","sayEs":"Entiendo tu punto, Kwame, pero me preocupa que las diapositivas no combinen. ¿Quizás podríamos planear el diseño juntos primero?","tag":"disagree","q":2,"why":"'I see your point, but' respects his idea, and 'maybe we could' suggests a change gently.","whyEs":"'I see your point, but' respeta su idea, y 'maybe we could' sugiere un cambio con suavidad.","next":"n2"}]},"n2":{"who":"npc2","say":"I like that idea. A shared design would help. But I am busy after school, so who can start it?","sayEs":"Me gusta esa idea. Un diseño compartido ayudaría. Pero estoy ocupada después de la escuela, ¿quién puede empezarlo?","mood":"pleased","choices":[{"id":"a","say":"I can make a simple template tonight with colors and fonts. Then each of us can add our own slides to it.","sayEs":"Yo puedo hacer una plantilla sencilla esta noche con colores y letras. Luego cada uno puede agregar sus propias diapositivas.","tag":"offer","q":2,"why":"'I can' offers help with a clear job, and 'then' explains the next step. Offers like this move a group forward.","whyEs":"'I can' ofrece ayuda con una tarea clara, y 'then' explica el siguiente paso. Ofertas así hacen avanzar al grupo.","next":"n3"},{"id":"b","say":"I can do the template. Then you do slides.","sayEs":"Yo puedo hacer la plantilla. Luego tú haces las diapositivas.","tag":"offer","q":1,"why":"Your offer is clear, but 'you do slides' sounds like an order. Say 'each of us can add slides'.","whyEs":"Tu oferta es clara, pero 'you do slides' suena a orden. Di 'each of us can add slides'.","next":"n3"},{"id":"c","say":"Why are you always busy? You never help.","sayEs":"¿Por qué siempre estás ocupada? Nunca ayudas.","tag":"question","q":0,"why":"This blames Mei instead of solving the problem. Offering help or asking 'What day works for you?' is kinder.","whyEs":"Esto culpa a Mei en lugar de resolver el problema. Ofrecer ayuda o preguntar 'What day works for you?' es más amable.","next":"n2b"}]},"n2b":{"who":"npc","say":"Hold on. I only want us to finish on time. What exactly do you want to change about my plan?","sayEs":"Espera. Solo quiero que terminemos a tiempo. ¿Qué quieres cambiar exactamente de mi plan?","mood":"concerned","choices":[{"id":"a","say":"Nothing. Do it your way. I do not care.","sayEs":"Nada. Hazlo a tu manera. No me importa.","tag":"refuse","q":0,"why":"Giving up sounds angry and leaves the problem unsolved. It also tells your group you do not want to help.","whyEs":"Rendirte suena a enojo y deja el problema sin resolver. También le dice al grupo que no quieres ayudar.","next":"end3"},{"id":"b","say":"Sorry, I said that badly. I think our slides need the same look, so maybe we should plan together first.","sayEs":"Perdón, lo dije de mala manera. Creo que nuestras diapositivas necesitan el mismo estilo, así que quizás deberíamos planear juntos primero.","tag":"disagree","q":2,"why":"You apologized, then used 'I think' and 'maybe' to disagree gently with a reason. That repairs the conversation.","whyEs":"Pediste perdón y luego usaste 'I think' y 'maybe' para disentir con suavidad y con una razón. Eso repara la conversación.","next":"n3"},{"id":"c","say":"I want same look for slides. We plan together.","sayEs":"Quiero el mismo estilo en las diapositivas. Planeemos juntos.","tag":"explain","q":1,"why":"Your reason is understandable. Adding 'I think' and 'maybe' would make it a polite disagreement.","whyEs":"Tu razón se entiende. Agregar 'I think' y 'maybe' lo convertiría en un desacuerdo cortés.","next":"n3"}]},"n3":{"who":"npc","say":"Okay, but I still like working alone at home. Is there a middle option?","sayEs":"Está bien, pero todavía me gusta trabajar solo en casa. ¿Hay una opción intermedia?","mood":"neutral","choices":[{"id":"a","say":"We plan in class. Then alone at home. Then together.","sayEs":"Planeamos en clase. Luego solos en casa. Luego juntos.","tag":"offer","q":1,"why":"Your steps are clear, but a full sentence like 'How about we plan first?' sounds friendlier.","whyEs":"Tus pasos son claros, pero una oración completa como 'How about we plan first?' suena más amable.","next":"n4"},{"id":"b","say":"No middle option. Either we plan together or I quit.","sayEs":"No hay opción intermedia. O planeamos juntos o me salgo.","tag":"disagree","q":0,"why":"An ultimatum leaves no room for compromise. Polite disagreement keeps talking and offers choices.","whyEs":"Un ultimátum no deja espacio para un acuerdo. El desacuerdo cortés sigue conversando y ofrece opciones.","next":"end3"},{"id":"c","say":"How about this: we plan together in class tomorrow, work alone at home, and meet Thursday to combine everything?","sayEs":"¿Qué tal esto? Planeamos juntos mañana en clase, trabajamos solos en casa y nos reunimos el jueves para juntar todo.","tag":"offer","q":2,"why":"'How about' offers a compromise using both sides' ideas. A clear plan makes it easy to say yes.","whyEs":"'How about' ofrece un acuerdo con las ideas de ambos lados. Un plan claro facilita decir que sí.","next":"n4"}]},"n4":{"who":"npc","say":"Okay, I can try that. One more thing: somebody has to check the final slides. Who wants to do it?","sayEs":"Está bien, puedo intentarlo. Algo más: alguien tiene que revisar las diapositivas finales. ¿Quién quiere hacerlo?","mood":"pleased","choices":[{"id":"a","say":"I can do that. Thank you both for listening. I think this plan is fair for everyone.","sayEs":"Yo puedo hacerlo. Gracias a los dos por escuchar. Creo que este plan es justo para todos.","tag":"accept","q":2,"why":"'I can do that' accepts a job, and thanking them shows respect. The compromise now feels fair.","whyEs":"'I can do that' acepta una tarea, y agradecerles muestra respeto. El acuerdo ahora se siente justo.","next":"end1"},{"id":"b","say":"Okay. I check. Fine plan.","sayEs":"Está bien. Yo reviso. Buen plan.","tag":"accept","q":1,"why":"You accepted the job, which helps the group. Use 'I will check them' and 'It is a good plan'.","whyEs":"Aceptaste la tarea, lo cual ayuda al grupo. Usa 'I will check them' e 'It is a good plan'.","next":"end2"},{"id":"c","say":"Not me. Ask Mei, she knows more than me.","sayEs":"Yo no. Pídeselo a Mei, ella sabe más que yo.","tag":"refuse","q":0,"why":"Passing the job to someone else sounds like avoiding teamwork. Offer something you can do instead.","whyEs":"Pasarle la tarea a otra persona suena a evitar el trabajo en equipo. Mejor ofrece algo que sí puedas hacer.","next":"end3"}]},"end1":{"who":"npc","say":"Great. Now we have a real plan. Let us start in class tomorrow.","sayEs":"Muy bien. Ahora sí tenemos un plan. Empecemos mañana en clase.","mood":"happy","end":true,"outcome":"strong","wrap":"You disagreed politely, offered a compromise, and accepted a job. The group agreed, and everyone's ideas were used.","wrapEs":"No estuviste de acuerdo con cortesía, ofreciste un acuerdo y aceptaste una tarea. El grupo estuvo de acuerdo y se usaron las ideas de todos."},"end2":{"who":"npc2","say":"Fine, we have a plan. We can fix the details tomorrow.","sayEs":"Bien, ya tenemos un plan. Podemos arreglar los detalles mañana.","mood":"pleased","end":true,"outcome":"ok","wrap":"The group reached a plan, but short answers left details unclear. Use full sentences when you accept or offer.","wrapEs":"El grupo llegó a un plan, pero las respuestas cortas dejaron detalles poco claros. Usa oraciones completas al aceptar u ofrecer."},"end3":{"who":"npc","say":"This is not working. Let us ask the teacher how to decide.","sayEs":"Esto no está funcionando. Preguntemos a la maestra cómo decidir.","mood":"concerned","end":true,"outcome":"retry","wrap":"The tone made the disagreement personal, so no compromise was reached. Try 'I see your point, but...' and 'How about...'.","wrapEs":"El tono hizo personal el desacuerdo, así que no hubo acuerdo. Prueba 'I see your point, but...' y 'How about...'."}}},
  {"id":"s68-lunch-newcomer","b":"6-8","title":"A new student at lunch","titleEs":"Un estudiante nuevo en el almuerzo","place":"lunch","goal":"Welcome a new student and ask friendly questions at the lunch table.","goalEs":"Dar la bienvenida a un estudiante nuevo y hacerle preguntas amables en la mesa del almuerzo.","focus":["greet","invite","question"],"npc":{"name":"Yusuf","role":"new student","roleEs":"estudiante nuevo","look":{"skin":"#c68642","hair":"#2b1b12","style":"curly","shirt":"#c0562b","acc":"none"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"Hi. Is it okay if I sit here? I am new, and I do not know anyone yet.","sayEs":"Hola. ¿Puedo sentarme aquí? Soy nuevo y todavía no conozco a nadie.","mood":"concerned","choices":[{"id":"a","say":"Yes, sit. Hello.","sayEs":"Sí, siéntate. Hola.","tag":"greet","q":1,"why":"You welcomed him, which is kind. A full sentence like 'Yes, please sit here' sounds warmer.","whyEs":"Lo recibiste, lo cual es amable. Una oración completa como 'Yes, please sit here' suena más cálida.","next":"n2b"},{"id":"b","say":"Whatever. Just do not take my seat.","sayEs":"Lo que sea. Solo no tomes mi asiento.","tag":"greet","q":0,"why":"This sounds unfriendly to someone who feels nervous. A smile and a welcome would help him feel safe.","whyEs":"Esto suena poco amistoso para alguien nervioso. Una sonrisa y una bienvenida lo ayudarían a sentirse seguro.","next":"n2b"},{"id":"c","say":"Hi, welcome to our school! Please sit here with us. It is nice to meet you.","sayEs":"¡Hola, bienvenido a nuestra escuela! Siéntate aquí con nosotros, por favor. Mucho gusto.","tag":"greet","q":2,"why":"You greeted him, invited him to sit, and said 'nice to meet you'. That makes a new student feel welcome.","whyEs":"Lo saludaste, lo invitaste a sentarse y dijiste 'nice to meet you'. Eso hace que un estudiante nuevo se sienta bienvenido.","next":"n2"}]},"n2":{"who":"npc","say":"Thanks. I am Yusuf. I moved here from another city last week, and everything feels different.","sayEs":"Gracias. Soy Yusuf. Me mudé aquí desde otra ciudad la semana pasada y todo se siente diferente.","mood":"happy","choices":[{"id":"a","say":"Why you come here? Your old school was bad?","sayEs":"¿Por qué vienes aquí? ¿Tu escuela anterior era mala?","tag":"question","q":0,"why":"The question form is wrong ('Why did you move here?') and it asks something personal. He may feel judged.","whyEs":"La forma de la pregunta es incorrecta ('Why did you move here?') y pregunta algo personal. Él puede sentirse juzgado.","next":"n2b"},{"id":"b","say":"Welcome, Yusuf! How is your first week going so far? Is there anything you would like to know about our school?","sayEs":"¡Bienvenido, Yusuf! ¿Cómo va tu primera semana hasta ahora? ¿Hay algo que quieras saber sobre nuestra escuela?","tag":"question","q":2,"why":"Wh- and yes/no questions are both formed correctly, and they show you care about his experience.","whyEs":"Las preguntas con wh- y las de sí o no están bien formadas, y muestran que te importa su experiencia.","next":"n3"},{"id":"c","say":"You like school? What is your class?","sayEs":"¿Te gusta la escuela? ¿Cuál es tu clase?","tag":"question","q":1,"why":"Your questions are understandable. 'Which classes do you have?' and 'How do you like it?' sound more natural.","whyEs":"Tus preguntas se entienden. 'Which classes do you have?' y 'How do you like it?' suenan más naturales.","next":"n3"}]},"n2b":{"who":"npc","say":"Sorry, I am a little nervous and I did not catch that. Could you say it another way?","sayEs":"Perdón, estoy un poco nervioso y no entendí bien. ¿Podrías decirlo de otra manera?","mood":"puzzled","choices":[{"id":"a","say":"I say: you sit. You welcome. Okay?","sayEs":"Dije: siéntate. Eres bienvenido. ¿Está bien?","tag":"clarify","q":1,"why":"Your meaning comes through. Try 'I said you can sit here, and you are welcome.' It sounds more fluent.","whyEs":"Tu mensaje se entiende. Prueba 'I said you can sit here, and you are welcome'. Suena más fluido.","next":"n3"},{"id":"b","say":"Never mind. It is not important.","sayEs":"No importa. No es importante.","tag":"question","q":0,"why":"Dropping the topic can make a nervous person feel ignored. Repeating more slowly would help him.","whyEs":"Dejar el tema puede hacer que una persona nerviosa se sienta ignorada. Repetir más despacio lo ayudaría.","next":"end3"},{"id":"c","say":"Sure, let me say it more slowly. You are welcome to eat with us. I wanted to know how your week is going.","sayEs":"Claro, lo diré más despacio. Eres bienvenido a comer con nosotros. Quería saber cómo va tu semana.","tag":"clarify","q":2,"why":"You rephrased more slowly in simple words. Repeating kindly helps a nervous listener understand.","whyEs":"Lo dijiste de nuevo, más despacio y con palabras sencillas. Repetir con amabilidad ayuda a un oyente nervioso a entender.","next":"n3"}]},"n3":{"who":"npc","say":"It is going okay. The halls are big and I got lost twice. What do you usually do at lunch?","sayEs":"Va bien. Los pasillos son grandes y me perdí dos veces. ¿Qué haces normalmente en el almuerzo?","mood":"pleased","choices":[{"id":"a","say":"We usually eat here and play cards for a few minutes. Would you like to join us tomorrow too?","sayEs":"Normalmente comemos aquí y jugamos cartas unos minutos. ¿Quieres unirte a nosotros mañana también?","tag":"invite","q":2,"why":"'Would you like to join us' is a friendly, polite invitation, and you explained what the group does.","whyEs":"'Would you like to join us' es una invitación amable y cortés, y explicaste lo que hace el grupo.","next":"n4"},{"id":"b","say":"I do not know. I am looking at my phone.","sayEs":"No sé. Estoy mirando mi teléfono.","tag":"question","q":0,"why":"Ignoring his question hurts a new student's confidence. Answering and asking back keeps the conversation going.","whyEs":"Ignorar su pregunta lastima la confianza de un estudiante nuevo. Responder y preguntar de vuelta mantiene la conversación.","next":"end3"},{"id":"c","say":"You come tomorrow. We play cards.","sayEs":"Ven mañana. Jugamos cartas.","tag":"invite","q":1,"why":"The invitation is kind and clear. Add 'Would you like to...?' to make it a question and sound polite.","whyEs":"La invitación es amable y clara. Agrega 'Would you like to...?' para hacerla pregunta y sonar cortés.","next":"n4"}]},"n4":{"who":"npc","say":"I would love to join you. Is there anything you want to ask me, too?","sayEs":"Me encantaría unirme. ¿Quieres preguntarme algo a mí también?","mood":"happy","choices":[{"id":"a","say":"Nope. I am eating now.","sayEs":"No. Ahora estoy comiendo.","tag":"question","q":0,"why":"Short and cold, it closes the conversation. A question about him would show you want to be friends.","whyEs":"Corta y fría, cierra la conversación. Una pregunta sobre él mostraría que quieres ser su amigo.","next":"end3"},{"id":"b","say":"What you like? Music? Games?","sayEs":"¿Qué te gusta? ¿Música? ¿Juegos?","tag":"question","q":1,"why":"Your meaning is clear. Use 'What do you like?' with 'do' so the question is correct.","whyEs":"Tu mensaje es claro. Usa 'What do you like?' con 'do' para que la pregunta sea correcta.","next":"end2"},{"id":"c","say":"Yes! What do you like to do after school? Maybe we have something in common.","sayEs":"¡Sí! ¿Qué te gusta hacer después de la escuela? Quizás tenemos algo en común.","tag":"question","q":2,"why":"A correct wh- question shows interest, and 'maybe' opens a way to connect.","whyEs":"Una pregunta correcta con wh- muestra interés, y 'maybe' abre una forma de conectar.","next":"end1"}]},"end1":{"who":"npc","say":"I like drawing and soccer. This is going to be a good lunch table.","sayEs":"Me gusta dibujar y el fútbol. Esta va a ser una buena mesa de almuerzo.","mood":"happy","end":true,"outcome":"strong","wrap":"You welcomed Yusuf, asked kind questions, and invited him back. A friendly greeting and good questions made him feel at home.","wrapEs":"Le diste la bienvenida a Yusuf, hiciste preguntas amables y lo invitaste de nuevo. Un saludo amistoso y buenas preguntas lo hicieron sentirse en casa."},"end2":{"who":"npc","say":"I like music and games. Okay, see you tomorrow.","sayEs":"Me gustan la música y los juegos. Bueno, nos vemos mañana.","mood":"pleased","end":true,"outcome":"ok","wrap":"Yusuf felt included, but your short questions were a little hard to follow. Full questions with 'do' sound more friendly.","wrapEs":"Yusuf se sintió incluido, pero tus preguntas cortas fueron algo difíciles de seguir. Las preguntas completas con 'do' suenan más amistosas."},"end3":{"who":"npc","say":"Oh, okay. I think I will eat quietly for now.","sayEs":"Ah, está bien. Creo que comeré en silencio por ahora.","mood":"concerned","end":true,"outcome":"retry","wrap":"Short or unfriendly answers made Yusuf feel left out. A warm greeting, a real answer, and a question back would help.","wrapEs":"Las respuestas cortas o poco amistosas hicieron que Yusuf se sintiera excluido. Un saludo cálido, una respuesta real y una pregunta de vuelta ayudarían."}}},
  {"id":"s68-bus-seat","b":"6-8","title":"A mix-up on the bus","titleEs":"Un malentendido en el autobús","place":"bus","goal":"Apologize for taking someone's seat and ask the driver to repeat the seat rule.","goalEs":"Pedir perdón por tomar el asiento de alguien y pedirle al conductor que repita la regla de los asientos.","focus":["apologize","describe","clarify"],"npc":{"name":"Aaliyah","role":"classmate","roleEs":"compañera de clase","look":{"skin":"#5c3a21","hair":"#2b1b12","style":"braids","shirt":"#2c5aa0","acc":"none"}},"npc2":{"name":"Mr. Alvarez","role":"bus driver","roleEs":"conductor del autobús","look":{"skin":"#e0ac84","hair":"#3a3a3a","style":"short","shirt":"#4a6a2f","acc":"none"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"Oh, hi. Um, that is my seat. I left my jacket here this morning.","sayEs":"Ay, hola. Este es mi asiento. Dejé mi chaqueta aquí esta mañana.","mood":"puzzled","choices":[{"id":"a","say":"There was no jacket. The seat was empty, so it is mine.","sayEs":"No había chaqueta. El asiento estaba vacío, así que es mío.","tag":"describe","q":0,"why":"Arguing about what you saw sounds like blame. Describe the problem calmly and say sorry first.","whyEs":"Discutir sobre lo que viste suena a reproche. Describe el problema con calma y pide perdón primero.","next":"n2b"},{"id":"b","say":"Oh, I am sorry! I did not see your jacket under the bag. I can move right now.","sayEs":"¡Ay, lo siento! No vi tu chaqueta debajo de la mochila. Me puedo mover ahora mismo.","tag":"apologize","q":2,"why":"You apologized, gave a short reason, and offered to fix it. That makes the other person relax.","whyEs":"Pediste perdón, diste una razón breve y ofreciste arreglarlo. Eso tranquiliza a la otra persona.","next":"n2"},{"id":"c","say":"Sorry. I not see jacket. Is okay?","sayEs":"Perdón. No vi la chaqueta. ¿Está bien?","tag":"apologize","q":1,"why":"Saying sorry is the right start. Use 'I did not see your jacket' to be clear.","whyEs":"Pedir perdón es un buen comienzo. Usa 'I did not see your jacket' para ser claro.","next":"n2b"}]},"n2":{"who":"npc","say":"It is okay, thanks for saying sorry. The driver said something about new seats this week, but I did not hear it. Do you know the rule?","sayEs":"Está bien, gracias por pedir perdón. El conductor dijo algo sobre asientos nuevos esta semana, pero no lo escuché. ¿Sabes cuál es la regla?","mood":"pleased","choices":[{"id":"a","say":"Rules are boring. Just sit anywhere, nobody checks.","sayEs":"Las reglas son aburridas. Siéntate donde quieras, nadie revisa.","tag":"describe","q":0,"why":"Ignoring the rule could get you in trouble. Saying what you do know, then asking for help, works better.","whyEs":"Ignorar la regla podría meterte en problemas. Decir lo que sí sabes y luego pedir ayuda funciona mejor.","next":"n2b"},{"id":"b","say":"No, I not know. We ask driver?","sayEs":"No, no sé. ¿Le preguntamos al conductor?","tag":"clarify","q":1,"why":"Your idea is good. Say 'I do not know. Should we ask the driver?' to be more correct and polite.","whyEs":"Tu idea es buena. Di 'I do not know. Should we ask the driver?' para ser más correcto y cortés.","next":"n3"},{"id":"c","say":"I did not hear it either. Maybe we can ask the driver to explain the new seat rule again.","sayEs":"Yo tampoco lo escuché. Quizás podemos pedirle al conductor que explique otra vez la nueva regla de los asientos.","tag":"clarify","q":2,"why":"You said you did not understand and suggested asking someone to explain again. That is a good clarifying step.","whyEs":"Dijiste que no entendiste y sugeriste pedir que lo expliquen de nuevo. Es un buen paso para aclarar.","next":"n3"}]},"n2b":{"who":"npc","say":"Hmm, I do not want any trouble. The driver changes seats when kids are too loud. What should we do?","sayEs":"Mmm, no quiero problemas. El conductor cambia los asientos cuando los niños hacen mucho ruido. ¿Qué hacemos?","mood":"concerned","choices":[{"id":"a","say":"Nothing. Sit somewhere else, then.","sayEs":"Nada. Entonces siéntate en otro lado.","tag":"refuse","q":0,"why":"This pushes her away and solves nothing. You are the one who needs to repair the mix-up.","whyEs":"Esto la aleja y no resuelve nada. Tú eres quien debe reparar el malentendido.","next":"end3"},{"id":"b","say":"The seat looked empty. I not know it is yours.","sayEs":"El asiento parecía vacío. No sabía que era tuyo.","tag":"describe","q":1,"why":"You described the problem clearly. Use 'I did not know it was yours' for the correct past tense.","whyEs":"Describiste el problema con claridad. Usa 'I did not know it was yours' para el pasado correcto.","next":"n3"},{"id":"c","say":"Let me explain my side. I sat here because it looked empty, and I did not mean to take your place.","sayEs":"Déjame explicar mi parte. Me senté aquí porque parecía vacío y no quise tomar tu lugar.","tag":"describe","q":2,"why":"You described what happened in order and used 'because' for your reason. That calms the problem down.","whyEs":"Describiste lo que pasó en orden y usaste 'because' para tu razón. Eso calma el problema.","next":"n3"}]},"n3":{"who":"npc2","say":"Everything okay back there? I need everyone seated so I can start driving.","sayEs":"¿Todo bien allá atrás? Necesito que todos estén sentados para empezar a manejar.","mood":"neutral","choices":[{"id":"a","say":"The bus is too loud and the seats are confusing! Nobody can hear you!","sayEs":"¡El autobús tiene demasiado ruido y los asientos son confusos! ¡Nadie te escucha!","tag":"describe","q":0,"why":"Shouting a complaint sounds rude to the driver. Describe your problem calmly and ask for help.","whyEs":"Gritar una queja suena grosero para el conductor. Describe tu problema con calma y pide ayuda.","next":"end3"},{"id":"b","say":"Sorry to bother you. Could you please repeat the new seat rule? We did not hear it, and we want to follow it.","sayEs":"Perdona la molestia. ¿Podrías repetir la nueva regla de los asientos, por favor? No la escuchamos y queremos cumplirla.","tag":"clarify","q":2,"why":"'Could you please repeat' asks for clarification politely, and your reason shows you want to follow the rule.","whyEs":"'Could you please repeat' pide aclaración con cortesía, y tu razón muestra que quieres cumplir la regla.","next":"n4"},{"id":"c","say":"Driver, what is seat rule? We not hear.","sayEs":"Conductor, ¿cuál es la regla de los asientos? No escuchamos.","tag":"clarify","q":1,"why":"Your question is understandable. Add 'please' and 'Could you repeat...' so it sounds polite.","whyEs":"Tu pregunta se entiende. Agrega 'please' y 'Could you repeat...' para que suene cortés.","next":"n4"}]},"n4":{"who":"npc2","say":"Thanks for asking. Everyone keeps the same seat every day, so I know who is on the bus. Does that make sense?","sayEs":"Gracias por preguntar. Cada persona mantiene el mismo asiento todos los días, para que yo sepa quién está en el autobús. ¿Tiene sentido?","mood":"pleased","choices":[{"id":"a","say":"Whatever. I will sit where I want.","sayEs":"Lo que sea. Me sentaré donde quiera.","tag":"refuse","q":0,"why":"This ignores the rule you just asked about and sounds disrespectful. The driver may assign you a seat.","whyEs":"Esto ignora la regla por la que acabas de preguntar y suena irrespetuoso. El conductor podría asignarte un asiento.","next":"end3"},{"id":"b","say":"Okay. Same seat every day. I understand.","sayEs":"Está bien. El mismo asiento todos los días. Entiendo.","tag":"clarify","q":1,"why":"You show you understood, which is good. Adding a question about where to sit would finish the plan.","whyEs":"Muestras que entendiste, lo cual está bien. Agregar una pregunta sobre dónde sentarse completaría el plan.","next":"end2"},{"id":"c","say":"Yes, I think so. We each keep one seat every day. Is it okay if Aaliyah and I share this one?","sayEs":"Sí, creo que sí. Cada uno mantiene un asiento todos los días. ¿Está bien si Aaliyah y yo compartimos este?","tag":"clarify","q":2,"why":"You repeated the rule in your own words and asked a question to check. That confirms you understood.","whyEs":"Repetiste la regla con tus propias palabras y hiciste una pregunta para confirmar. Eso demuestra que entendiste.","next":"end1"}]},"end1":{"who":"npc2","say":"Perfect. Sit together, and thanks for working it out nicely.","sayEs":"Perfecto. Siéntense juntos y gracias por resolverlo con buena actitud.","mood":"happy","end":true,"outcome":"strong","wrap":"You apologized, described what happened, and asked the driver to repeat the rule. Clear, polite language solved the mix-up.","wrapEs":"Pediste perdón, describiste lo que pasó y le pediste al conductor que repitiera la regla. Un lenguaje claro y cortés resolvió el malentendido."},"end2":{"who":"npc2","say":"Okay, that works. Let us get going.","sayEs":"Está bien, eso funciona. Pongámonos en marcha.","mood":"pleased","end":true,"outcome":"ok","wrap":"The seat problem was solved, but your answers were short. Full sentences and a check question show more clearly that you understood.","wrapEs":"El problema del asiento se resolvió, pero tus respuestas fueron cortas. Las oraciones completas y una pregunta de confirmación muestran mejor que entendiste."},"end3":{"who":"npc2","say":"I will assign seats if this keeps happening. Please sit down for now.","sayEs":"Asignaré los asientos si esto sigue pasando. Por ahora, siéntense, por favor.","mood":"concerned","end":true,"outcome":"retry","wrap":"The tone or unclear words made the mix-up bigger. Say sorry first, describe calmly, and ask 'Could you repeat that?'.","wrapEs":"El tono o las palabras poco claras agrandaron el malentendido. Pide perdón primero, describe con calma y pregunta 'Could you repeat that?'."}}},
  {"id":"s68-club-signup","b":"6-8","title":"Signing up for a club","titleEs":"Inscribirse en un club","place":"hallway","goal":"Ask about a club and its requirements before you sign up.","goalEs":"Preguntar sobre un club y sus requisitos antes de inscribirte.","focus":["question","request","accept"],"npc":{"name":"Ms. Patel","role":"robotics club advisor","roleEs":"asesora del club de robótica","look":{"skin":"#c68642","hair":"#1a1a1a","style":"long","shirt":"#8a2f4a","acc":"none"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"Hi! Are you interested in the robotics club? We are signing up students at this table.","sayEs":"¡Hola! ¿Te interesa el club de robótica? Estamos inscribiendo estudiantes en esta mesa.","mood":"happy","choices":[{"id":"a","say":"Yes. What is club? When meet?","sayEs":"Sí. ¿Qué es el club? ¿Cuándo se reúnen?","tag":"question","q":1,"why":"Your questions are clear. Use 'What do students do?' and 'When does it meet?' so the grammar is correct.","whyEs":"Tus preguntas son claras. Usa 'What do students do?' y 'When does it meet?' para que la gramática sea correcta.","next":"n2b"},{"id":"b","say":"Give me the paper. I will sign it. I do not need to know anything.","sayEs":"Dame el papel. Lo firmo. No necesito saber nada.","tag":"request","q":0,"why":"Commands with no 'please' sound rude, and signing without questions can lead to surprises.","whyEs":"Las órdenes sin 'please' suenan groseras, y firmar sin preguntar puede traer sorpresas.","next":"n2b"},{"id":"c","say":"Yes, I think so! What do students do in the club, and when does it meet?","sayEs":"¡Sí, creo que sí! ¿Qué hacen los estudiantes en el club y cuándo se reúne?","tag":"question","q":2,"why":"Two correctly formed wh- questions show real interest and get the key facts at once.","whyEs":"Dos preguntas con wh- bien formadas muestran interés real y consiguen los datos clave de una vez.","next":"n2"}]},"n2":{"who":"npc","say":"We build small robots and take them to a friendly contest in the spring. We meet Tuesdays after school, from 3:15 to 4:30.","sayEs":"Construimos robots pequeños y los llevamos a un concurso amistoso en la primavera. Nos reunimos los martes después de clases, de 3:15 a 4:30.","mood":"pleased","choices":[{"id":"a","say":"Tuesday is a bad day. Change it to Friday.","sayEs":"El martes es un mal día. Cámbialo al viernes.","tag":"request","q":0,"why":"Telling an advisor to change the schedule is a demand. Ask 'Is there another day?' politely instead.","whyEs":"Decirle a una asesora que cambie el horario es una exigencia. Mejor pregunta con cortesía 'Is there another day?'.","next":"n2b"},{"id":"b","say":"That sounds fun. Do I need any experience, or can beginners join? Also, is there a fee or anything I must bring?","sayEs":"Suena divertido. ¿Necesito experiencia o pueden unirse principiantes? Además, ¿hay una cuota o algo que deba llevar?","tag":"question","q":2,"why":"Yes/no questions with 'Do I' and 'is there' ask about requirements clearly and politely.","whyEs":"Las preguntas de sí o no con 'Do I' e 'is there' preguntan por los requisitos con claridad y cortesía.","next":"n3"},{"id":"c","say":"Need experience? Need money?","sayEs":"¿Necesito experiencia? ¿Necesito dinero?","tag":"question","q":1,"why":"The topics are right. Add 'Do I need...?' to make full, polite questions.","whyEs":"Los temas son correctos. Agrega 'Do I need...?' para hacer preguntas completas y corteses.","next":"n3"}]},"n2b":{"who":"npc","say":"Let me explain another way. It is a beginner-friendly club that meets once a week. Do you have any questions about joining?","sayEs":"Déjame explicarlo de otra manera. Es un club para principiantes que se reúne una vez a la semana. ¿Tienes preguntas sobre cómo unirte?","mood":"neutral","choices":[{"id":"a","say":"How I join? I need paper?","sayEs":"¿Cómo me uno? ¿Necesito un papel?","tag":"request","q":1,"why":"Your meaning is clear. Say 'How do I join?' and 'Do I need a form?' to use the right question form.","whyEs":"Tu mensaje es claro. Di 'How do I join?' y 'Do I need a form?' para usar la forma correcta de pregunta.","next":"n3"},{"id":"b","say":"No questions. I already know everything about robots.","sayEs":"Sin preguntas. Ya sé todo sobre robots.","tag":"refuse","q":0,"why":"Refusing to ask can cause mix-ups later, and it sounds a bit rude. Asking one question shows interest.","whyEs":"Negarte a preguntar puede causar confusiones después y suena algo grosero. Hacer una pregunta muestra interés.","next":"end3"},{"id":"c","say":"Yes, thank you. Could you tell me whether there is a form to fill out and if I need permission?","sayEs":"Sí, gracias. ¿Podrías decirme si hay un formulario que llenar y si necesito permiso?","tag":"request","q":2,"why":"'Could you tell me' is a polite indirect request, which sounds respectful when asking an adult.","whyEs":"'Could you tell me' es una petición indirecta y cortés, que suena respetuosa al hablar con un adulto.","next":"n3"}]},"n3":{"who":"npc","say":"No experience needed, and the club is free. You do need a parent or guardian signature on a form. Would you like one?","sayEs":"No se necesita experiencia y el club es gratis. Sí necesitas la firma de un padre, una madre o un tutor en un formulario. ¿Quieres uno?","mood":"happy","choices":[{"id":"a","say":"A signature? That is too much work. Forget it.","sayEs":"¿Una firma? Es demasiado trabajo. Olvídalo.","tag":"refuse","q":0,"why":"Dismissing the requirement sounds rude, and you lose a chance to join. Asking 'How long does it take?' is better.","whyEs":"Descartar el requisito suena grosero y pierdes la oportunidad de unirte. Es mejor preguntar 'How long does it take?'.","next":"end3"},{"id":"b","say":"Yes. I take form. I bring back.","sayEs":"Sí. Tomo el formulario. Lo traigo de vuelta.","tag":"accept","q":1,"why":"You accepted and gave a plan, which is great. Use 'I will take it and bring it back'.","whyEs":"Aceptaste y diste un plan, lo cual es muy bueno. Usa 'I will take it and bring it back'.","next":"n4"},{"id":"c","say":"Yes, please. May I take a form home today? I will ask my parents to sign it and bring it back.","sayEs":"Sí, por favor. ¿Puedo llevarme un formulario hoy? Les pediré a mis padres que lo firmen y lo traeré de vuelta.","tag":"request","q":2,"why":"'May I' with 'please' is a polite request, and your plan shows you will follow the rules.","whyEs":"'May I' con 'please' es una petición cortés, y tu plan muestra que cumplirás las reglas.","next":"n4"}]},"n4":{"who":"npc","say":"Wonderful. Here is the form. The first meeting is next Tuesday in room 108. Should I add your name to the interest list too?","sayEs":"Qué bien. Aquí está el formulario. La primera reunión es el próximo martes en el salón 108. ¿Agrego tu nombre a la lista de interesados también?","mood":"pleased","choices":[{"id":"a","say":"Maybe. I do not know if I want to come.","sayEs":"Quizás. No sé si quiero ir.","tag":"question","q":0,"why":"A vague answer after all her help leaves her unsure. Say yes or ask for time to decide.","whyEs":"Una respuesta vaga después de toda su ayuda la deja con dudas. Di que sí o pide tiempo para decidir.","next":"end3"},{"id":"b","say":"Okay. Put my name. Thanks.","sayEs":"Está bien. Pon mi nombre. Gracias.","tag":"accept","q":1,"why":"You accepted and thanked her. 'Yes, please add my name' sounds more polite than a command.","whyEs":"Aceptaste y le diste las gracias. 'Yes, please add my name' suena más cortés que una orden.","next":"end2"},{"id":"c","say":"Yes, please add my name. Thank you, Ms. Patel. I am excited, and I will see you on Tuesday.","sayEs":"Sí, por favor agrega mi nombre. Gracias, Sra. Patel. Me emociona mucho y nos vemos el martes.","tag":"accept","q":2,"why":"You accepted clearly, thanked her by name, and shared a feeling. That is a complete, friendly acceptance.","whyEs":"Aceptaste con claridad, le agradeciste por su nombre y compartiste un sentimiento. Es una aceptación completa y amable.","next":"end1"}]},"end1":{"who":"npc","say":"Welcome to robotics! Bring your form on Tuesday, and we will start building.","sayEs":"¡Te damos la bienvenida a robótica! Trae tu formulario el martes y empezaremos a construir.","mood":"happy","end":true,"outcome":"strong","wrap":"You asked clear questions, requested the form politely, and accepted with thanks. Good questions gave you all the facts before you joined.","wrapEs":"Hiciste preguntas claras, pediste el formulario con cortesía y aceptaste con agradecimiento. Las buenas preguntas te dieron todos los datos antes de unirte."},"end2":{"who":"npc","say":"Okay, you are on the list. See you Tuesday.","sayEs":"Está bien, estás en la lista. Nos vemos el martes.","mood":"pleased","end":true,"outcome":"ok","wrap":"You joined, but short answers and commands sounded rushed. Using 'please' and full questions makes a stronger impression.","wrapEs":"Te uniste, pero las respuestas cortas y las órdenes sonaron apuradas. Usar 'please' y preguntas completas causa mejor impresión."},"end3":{"who":"npc","say":"No problem. Come back if you change your mind. The table is here all week.","sayEs":"No hay problema. Vuelve si cambias de opinión. La mesa estará aquí toda la semana.","mood":"concerned","end":true,"outcome":"retry","wrap":"Without clear questions or polite requests, the sign-up did not happen. Ask 'Do I need...?' and 'May I...?' next time.","wrapEs":"Sin preguntas claras ni peticiones corteses, la inscripción no se hizo. La próxima vez pregunta 'Do I need...?' y 'May I...?'."}}},
  {"id":"s68-library-sources","b":"6-8","title":"Finding reliable sources","titleEs":"Encontrar fuentes confiables","place":"library","goal":"Ask the librarian how to find reliable sources for a science report.","goalEs":"Preguntarle al bibliotecario cómo encontrar fuentes confiables para un informe de ciencias.","focus":["question","clarify","thank"],"npc":{"name":"Mr. Haddad","role":"school librarian","roleEs":"bibliotecario escolar","look":{"skin":"#e0ac84","hair":"#3a2a1a","style":"short","shirt":"#3f6f4a","acc":"glasses"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"Welcome to the library. Are you looking for something in particular?","sayEs":"Te damos la bienvenida a la biblioteca. ¿Buscas algo en particular?","mood":"neutral","choices":[{"id":"a","say":"Find me websites about the ocean. I have no time to look.","sayEs":"Búscame sitios web sobre el océano. No tengo tiempo para buscar.","tag":"request","q":0,"why":"A command with no 'please' sounds rude, and it does not say what kind of help you need.","whyEs":"Una orden sin 'please' suena grosera y no dice qué tipo de ayuda necesitas.","next":"n2b"},{"id":"b","say":"Yes, hello. I am researching ocean pollution for science. How can I find reliable sources for my report?","sayEs":"Sí, hola. Estoy investigando la contaminación del océano para ciencias. ¿Cómo puedo encontrar fuentes confiables para mi informe?","tag":"question","q":2,"why":"You gave your topic and asked a clear 'How can I' question. That tells him exactly how to help.","whyEs":"Diste tu tema y hiciste una pregunta clara con 'How can I'. Eso le dice exactamente cómo ayudarte.","next":"n2"},{"id":"c","say":"I need information for report. Where I find good?","sayEs":"Necesito información para el informe. ¿Dónde encuentro buena?","tag":"question","q":1,"why":"Your need is understandable. Try 'Where can I find good information?' to use the correct question order.","whyEs":"Tu necesidad se entiende. Prueba 'Where can I find good information?' para usar el orden correcto de la pregunta.","next":"n2b"}]},"n2":{"who":"npc","say":"Good topic. A reliable source names the author, shows a date, and comes from a school, museum, or science group. Want to start with our databases?","sayEs":"Buen tema. Una fuente confiable nombra al autor, muestra una fecha y viene de una escuela, un museo o un grupo científico. ¿Quieres empezar con nuestras bases de datos?","mood":"pleased","choices":[{"id":"a","say":"Database? What is it? I not understand.","sayEs":"¿Base de datos? ¿Qué es? No entiendo.","tag":"clarify","q":1,"why":"You asked for help, which is good. 'I do not understand' and 'Could you explain?' sound clearer.","whyEs":"Pediste ayuda, lo cual está bien. 'I do not understand' y 'Could you explain?' suenan más claros.","next":"n3"},{"id":"b","say":"Do you have video games on the computers?","sayEs":"¿Tienen videojuegos en las computadoras?","tag":"question","q":0,"why":"It is a good question form, but it is off-topic. It tells him you are not focused on the report.","whyEs":"Es una buena forma de pregunta, pero no tiene que ver con el tema. Le dice que no estás concentrado en el informe.","next":"n2b"},{"id":"c","say":"Could you explain what a database is? How is it different from a regular search engine?","sayEs":"¿Podrías explicar qué es una base de datos? ¿En qué se diferencia de un buscador normal?","tag":"clarify","q":2,"why":"'Could you explain' asks for clarification politely, and the second question narrows what you need.","whyEs":"'Could you explain' pide aclaración con cortesía, y la segunda pregunta precisa lo que necesitas.","next":"n3"}]},"n2b":{"who":"npc","say":"I want to point you to the right place. Can you tell me your topic and what kind of sources your teacher wants?","sayEs":"Quiero indicarte el lugar correcto. ¿Puedes decirme tu tema y qué tipo de fuentes quiere tu docente?","mood":"puzzled","choices":[{"id":"a","say":"Sure. My topic is ocean pollution, and my teacher wants three sources. How can I tell if a website is trustworthy?","sayEs":"Claro. Mi tema es la contaminación del océano y mi docente quiere tres fuentes. ¿Cómo puedo saber si un sitio web es confiable?","tag":"question","q":2,"why":"You answered both parts, then asked a correct 'How can I tell' question. Clear details help him help you.","whyEs":"Respondiste ambas partes y luego hiciste una pregunta correcta con 'How can I tell'. Los detalles claros le ayudan a ayudarte.","next":"n3"},{"id":"b","say":"Ocean topic. Three sources. How I know true?","sayEs":"Tema del océano. Tres fuentes. ¿Cómo sé si es verdad?","tag":"question","q":1,"why":"You gave the right facts. Use 'How do I know if it is true?' for the correct question form.","whyEs":"Diste los datos correctos. Usa 'How do I know if it is true?' para la forma correcta de la pregunta.","next":"n3"},{"id":"c","say":"I do not know. Just give me anything.","sayEs":"No sé. Dame cualquier cosa.","tag":"request","q":0,"why":"'Anything' tells him you do not care, and he cannot help without details. Also add 'please'.","whyEs":"'Anything' le dice que no te importa, y él no puede ayudar sin detalles. Además, agrega 'please'.","next":"end3"}]},"n3":{"who":"npc","say":"A database has articles checked by editors. You type keywords, then filter by date. Try 'ocean plastic' and read the first two results.","sayEs":"Una base de datos tiene artículos revisados por editores. Escribes palabras clave y luego filtras por fecha. Prueba 'ocean plastic' y lee los dos primeros resultados.","mood":"happy","choices":[{"id":"a","say":"That is too many steps. I will just use the first website I see.","sayEs":"Son demasiados pasos. Usaré el primer sitio web que vea.","tag":"question","q":0,"why":"The first website is not always reliable. This answer skips the help you came for.","whyEs":"El primer sitio web no siempre es confiable. Esta respuesta se salta la ayuda por la que viniste.","next":"end3"},{"id":"b","say":"Slow, please. Keywords first? Then date?","sayEs":"Más despacio, por favor. ¿Primero palabras clave? ¿Luego la fecha?","tag":"clarify","q":1,"why":"Asking him to slow down is smart. A full sentence, 'Could you say that more slowly?', is more polite.","whyEs":"Pedirle que vaya más despacio es inteligente. Una oración completa, 'Could you say that more slowly?', es más cortés.","next":"n4"},{"id":"c","say":"Sorry, could you say that more slowly? Do I type my keywords first, and then choose the date filter?","sayEs":"Perdón, ¿podrías decirlo más despacio? ¿Escribo mis palabras clave primero y luego elijo el filtro de fecha?","tag":"clarify","q":2,"why":"You asked him to slow down politely, then checked your understanding with a yes/no question. That is strong clarifying.","whyEs":"Le pediste con cortesía que fuera más despacio y luego confirmaste con una pregunta de sí o no. Eso es aclarar muy bien.","next":"n4"}]},"n4":{"who":"npc","say":"Yes, exactly. Keywords first, then the date filter. If you get stuck, come back and we can check an article together.","sayEs":"Sí, exacto. Primero las palabras clave y luego el filtro de fecha. Si te atoras, vuelve y revisamos un artículo juntos.","mood":"pleased","choices":[{"id":"a","say":"Okay. Thank you. I try now.","sayEs":"Está bien. Gracias. Lo intento ahora.","tag":"thank","q":1,"why":"Thanking him is polite. 'Thank you for explaining. I will try it now' shows more appreciation.","whyEs":"Darle las gracias es cortés. 'Thank you for explaining. I will try it now' muestra más aprecio.","next":"end2"},{"id":"b","say":"That sounds great. Thank you for explaining so clearly. Now I feel confident, and I will come back if I get stuck.","sayEs":"Suena muy bien. Gracias por explicar con tanta claridad. Ahora tengo confianza y volveré si me atoro.","tag":"thank","q":2,"why":"You thanked him for something specific and said what you will do next. That shows you valued his help.","whyEs":"Le agradeciste algo específico y dijiste lo que harás después. Eso muestra que valoraste su ayuda.","next":"end1"},{"id":"c","say":"Maybe. Why does the library have so many rules?","sayEs":"Quizás. ¿Por qué la biblioteca tiene tantas reglas?","tag":"question","q":0,"why":"Complaining about rules instead of answering sounds ungrateful. A short thank you would end the help well.","whyEs":"Quejarte de las reglas en vez de responder suena desagradecido. Un breve agradecimiento cerraría bien la ayuda.","next":"end3"}]},"end1":{"who":"npc","say":"You are welcome. Good luck with your report, and come back anytime.","sayEs":"De nada. Mucha suerte con tu informe, y vuelve cuando quieras.","mood":"happy","end":true,"outcome":"strong","wrap":"You asked clear questions, asked him to explain and slow down, and thanked him. Clarifying politely got you real help.","wrapEs":"Hiciste preguntas claras, le pediste que explicara y fuera más despacio, y le agradeciste. Aclarar con cortesía te consiguió ayuda real."},"end2":{"who":"npc","say":"Okay. Try it, and ask if you need more help.","sayEs":"Está bien. Pruébalo y pregunta si necesitas más ayuda.","mood":"pleased","end":true,"outcome":"ok","wrap":"You learned the steps, but short answers did not show how much you understood. Thank people for specific help.","wrapEs":"Aprendiste los pasos, pero las respuestas cortas no mostraron cuánto entendiste. Agradece a las personas por su ayuda específica."},"end3":{"who":"npc","say":"I think you may need a different plan. Come back when your topic is ready.","sayEs":"Creo que necesitas otro plan. Vuelve cuando tu tema esté listo.","mood":"concerned","end":true,"outcome":"retry","wrap":"Without clear details or polite requests, he could not give the right help. Share your topic, ask 'How can I...?', and say thanks.","wrapEs":"Sin detalles claros ni peticiones corteses, él no pudo dar la ayuda correcta. Comparte tu tema, pregunta 'How can I...?' y da las gracias."}}},
  {"id":"s68-hallway-bump","b":"6-8","title":"Sorry in the hallway","titleEs":"Perdón en el pasillo","place":"hallway","goal":"Apologize after bumping into a classmate and offer to help.","goalEs":"Pedir perdón después de chocar con una compañera y ofrecer ayuda.","focus":["apologize","offer","thank"],"npc":{"name":"Noor","role":"classmate","roleEs":"compañera de clase","look":{"skin":"#e0ac84","hair":"#2b1b12","style":"hijab","shirt":"#1f6f8b","acc":"none"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"Oh no! My papers are all over the floor!","sayEs":"¡Ay, no! ¡Mis papeles están por todo el piso!","mood":"concerned","choices":[{"id":"a","say":"You should watch where you walk. The hallway is crowded.","sayEs":"Deberías fijarte por dónde caminas. El pasillo está lleno.","tag":"explain","q":0,"why":"Blaming her when you bumped her is unfair. Starting with 'I am sorry' calms the moment.","whyEs":"Culparla cuando tú chocaste con ella es injusto. Empezar con 'I am sorry' calma el momento.","next":"n2b"},{"id":"b","say":"Sorry, sorry! My fault. I help you.","sayEs":"¡Perdón, perdón! Fue mi culpa. Te ayudo.","tag":"apologize","q":1,"why":"You took responsibility and offered help, which is great. Use 'I will help you' for correct grammar.","whyEs":"Asumiste la responsabilidad y ofreciste ayuda, lo cual es excelente. Usa 'I will help you' para la gramática correcta.","next":"n2b"},{"id":"c","say":"I am so sorry, Noor! I was not looking where I was going. Are you okay? Let me help you pick them up.","sayEs":"¡Lo siento mucho, Noor! No estaba mirando por dónde iba. ¿Estás bien? Déjame ayudarte a recogerlos.","tag":"apologize","q":2,"why":"You apologized, owned the mistake, checked on her, and offered help. Each part shows care.","whyEs":"Pediste perdón, asumiste el error, le preguntaste cómo estaba y ofreciste ayuda. Cada parte muestra cuidado.","next":"n2"}]},"n2":{"who":"npc","say":"I am okay, thanks. Some papers got out of order, and my water bottle rolled away. I have class in two minutes.","sayEs":"Estoy bien, gracias. Algunos papeles se desordenaron y mi botella de agua rodó lejos. Tengo clase en dos minutos.","mood":"neutral","choices":[{"id":"a","say":"I get bottle. I carry bag?","sayEs":"Yo traigo la botella. ¿Cargo tu mochila?","tag":"offer","q":1,"why":"Your offers are kind and clear. Use 'Can I carry your bag?' or 'I can get it' for correct form.","whyEs":"Tus ofertas son amables y claras. Usa 'Can I carry your bag?' o 'I can get it' para la forma correcta.","next":"n3"},{"id":"b","say":"Do not worry, they are just papers. You can print them again.","sayEs":"No te preocupes, son solo papeles. Puedes imprimirlos otra vez.","tag":"explain","q":0,"why":"This makes her worry sound small. If the papers matter to her, an offer helps more than advice.","whyEs":"Esto hace que su preocupación parezca pequeña. Si los papeles le importan, una oferta ayuda más que un consejo.","next":"n2b"},{"id":"c","say":"I can grab your bottle while you sort the papers. Would you like me to carry your bag to class?","sayEs":"Yo puedo traer tu botella mientras ordenas los papeles. ¿Quieres que te cargue la mochila hasta la clase?","tag":"offer","q":2,"why":"'I can' and 'Would you like me to' offer help in two polite ways and split the work.","whyEs":"'I can' y 'Would you like me to' ofrecen ayuda de dos maneras corteses y reparten el trabajo.","next":"n3"}]},"n2b":{"who":"npc","say":"Okay... I am a little stressed. I need these papers in order for my next class. Can you help me?","sayEs":"Está bien... Estoy un poco estresada. Necesito estos papeles en orden para mi próxima clase. ¿Me ayudas?","mood":"puzzled","choices":[{"id":"a","say":"Yes, of course. You sort the ones you have, and I will pick up the rest. Then we can put them in order together.","sayEs":"Sí, claro. Tú ordena los que tienes y yo recojo el resto. Luego los ponemos en orden entre los dos.","tag":"offer","q":2,"why":"'I will' makes a clear offer, and 'then' gives the steps. A clear plan helps her feel calm.","whyEs":"'I will' hace una oferta clara y 'then' da los pasos. Un plan claro la ayuda a sentirse tranquila.","next":"n3"},{"id":"b","say":"I cannot, I am late for class too. Good luck.","sayEs":"No puedo, yo también llego tarde a clase. Buena suerte.","tag":"refuse","q":0,"why":"You caused the mess, so leaving sounds uncaring. Even a short offer like 'I can help for one minute' is better.","whyEs":"Tú causaste el desorden, así que irte suena indiferente. Incluso una oferta breve como 'I can help for one minute' es mejor.","next":"end3"},{"id":"c","say":"Yes. I pick up. You sort.","sayEs":"Sí. Yo recojo. Tú ordenas.","tag":"offer","q":1,"why":"The offer is clear. Add 'I will' and 'please' so it does not sound like an order.","whyEs":"La oferta es clara. Agrega 'I will' y 'please' para que no suene como una orden.","next":"n3"}]},"n3":{"who":"npc","say":"Thank you. That is faster. One page got a small wet spot from my bottle, but I think it is readable.","sayEs":"Gracias. Así es más rápido. Una hoja tiene una mancha mojada por mi botella, pero creo que se puede leer.","mood":"pleased","choices":[{"id":"a","say":"It is only a little wet. It will dry. It is not a big deal.","sayEs":"Solo está un poco mojada. Se secará. No es para tanto.","tag":"explain","q":0,"why":"Saying it is no big deal ignores her feelings. A short apology or offer shows you care.","whyEs":"Decir que no es para tanto ignora sus sentimientos. Una breve disculpa u oferta muestra que te importa.","next":"end3"},{"id":"b","say":"I am sorry about that page. If you want, I can help copy it at lunch or tell your teacher it was my fault.","sayEs":"Lamento mucho lo de esa hoja. Si quieres, puedo ayudarte a copiarla en el almuerzo o decirle a tu maestro que fue mi culpa.","tag":"apologize","q":2,"why":"You apologized again for the specific problem and offered two ways to fix it. That shows responsibility.","whyEs":"Pediste perdón otra vez por el problema específico y ofreciste dos formas de arreglarlo. Eso muestra responsabilidad.","next":"n4"},{"id":"c","say":"Sorry for the page. I can copy it at lunch.","sayEs":"Perdón por la hoja. Puedo copiarla en el almuerzo.","tag":"apologize","q":1,"why":"Your apology and offer are clear. 'I am sorry' with 'I can help' sounds more complete.","whyEs":"Tu disculpa y tu oferta son claras. 'I am sorry' con 'I can help' suena más completo.","next":"n4"}]},"n4":{"who":"npc","say":"That is kind. I can probably dry it in my notebook. Thanks for helping and for not walking away.","sayEs":"Qué amable. Seguramente la puedo secar dentro de mi cuaderno. Gracias por ayudar y por no irte.","mood":"happy","choices":[{"id":"a","say":"Thank you for being so understanding, Noor. I will be more careful in the hallway. Please tell me if I can help more.","sayEs":"Gracias por ser tan comprensiva, Noor. Tendré más cuidado en el pasillo. Dime si puedo ayudar en algo más.","tag":"thank","q":2,"why":"You thanked her for something specific, promised to improve, and offered more help. That repairs the moment well.","whyEs":"Le agradeciste algo específico, prometiste mejorar y ofreciste más ayuda. Eso repara bien el momento.","next":"end1"},{"id":"b","say":"Thanks. Sorry again. Bye.","sayEs":"Gracias. Perdón otra vez. Adiós.","tag":"thank","q":1,"why":"Thanks and sorry are both polite. A promise to be careful would make it feel sincere.","whyEs":"Gracias y perdón son ambos corteses. Una promesa de tener cuidado lo haría sentir sincero.","next":"end2"},{"id":"c","say":"Yes, I am careful. It was mostly your fault for stopping there.","sayEs":"Sí, tengo cuidado. Fue más tu culpa por detenerte ahí.","tag":"explain","q":0,"why":"Blaming her at the end undoes your apology. It makes her feel the help was not sincere.","whyEs":"Culparla al final deshace tu disculpa. Hace que ella sienta que la ayuda no fue sincera.","next":"end3"}]},"end1":{"who":"npc","say":"No problem at all. See you in class, and thanks again!","sayEs":"No hay problema. Nos vemos en clase, ¡y gracias otra vez!","mood":"happy","end":true,"outcome":"strong","wrap":"You apologized sincerely, offered specific help, and thanked Noor. Taking responsibility turned a messy bump into a kind moment.","wrapEs":"Pediste perdón con sinceridad, ofreciste ayuda específica y le agradeciste a Noor. Asumir la responsabilidad convirtió un choque desordenado en un momento amable."},"end2":{"who":"npc","say":"Okay, bye. I need to get to class.","sayEs":"Está bien, adiós. Tengo que llegar a clase.","mood":"pleased","end":true,"outcome":"ok","wrap":"You helped and said sorry, but short answers sounded rushed. Add a promise or a specific offer to show care.","wrapEs":"Ayudaste y pediste perdón, pero las respuestas cortas sonaron apuradas. Agrega una promesa o una oferta específica para mostrar cuidado."},"end3":{"who":"npc","say":"I think I can do the rest myself. I need to get to class.","sayEs":"Creo que puedo hacer el resto sola. Tengo que llegar a clase.","mood":"concerned","end":true,"outcome":"retry","wrap":"Blaming or brushing off Noor made the problem bigger. Start with 'I am sorry' and offer help with 'I can...'.","wrapEs":"Culpar a Noor o restarle importancia agrandó el problema. Empieza con 'I am sorry' y ofrece ayuda con 'I can...'."}}},
  {"id":"s68-refuse-homework","b":"6-8","title":"Saying no to sharing answers","titleEs":"Decir que no a compartir respuestas","place":"hallway","goal":"Politely refuse to share homework answers and offer to help another way.","goalEs":"Negarte con amabilidad a compartir las respuestas de la tarea y ofrecer ayuda de otra manera.","focus":["refuse","explain","offer"],"npc":{"name":"Tyrone","role":"classmate","roleEs":"compañero de clase","look":{"skin":"#5c3a21","hair":"#1a1a1a","style":"cap","shirt":"#b5541c","acc":"headphones"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"Hey. Quick thing. Did you finish the math homework? Can I copy your answers before class?","sayEs":"Oye. Algo rápido. ¿Terminaste la tarea de matemáticas? ¿Puedo copiar tus respuestas antes de la clase?","mood":"neutral","choices":[{"id":"a","say":"No, sorry. I not share homework.","sayEs":"No, perdón. No comparto la tarea.","tag":"refuse","q":1,"why":"Your polite no is clear. Use 'I do not share my homework' for correct grammar.","whyEs":"Tu no cortés es claro. Usa 'I do not share my homework' para la gramática correcta.","next":"n2b"},{"id":"b","say":"No way! That is cheating. Ask somebody else.","sayEs":"¡Ni hablar! Eso es hacer trampa. Pídeselo a otra persona.","tag":"refuse","q":0,"why":"Calling it cheating sounds like an accusation. You can say no without making him feel bad.","whyEs":"Decir que es hacer trampa suena a acusación. Puedes decir que no sin hacerlo sentir mal.","next":"n2b"},{"id":"c","say":"Hey, Tyrone. I am sorry, but I would rather not share my answers. I want us both to learn it.","sayEs":"Oye, Tyrone. Lo siento, pero prefiero no compartir mis respuestas. Quiero que los dos lo aprendamos.","tag":"refuse","q":2,"why":"'I would rather not' is a gentle no, and giving a reason keeps the friendship warm.","whyEs":"'I would rather not' es un no amable, y dar una razón mantiene cálida la amistad.","next":"n2"}]},"n2":{"who":"npc","say":"Oh. I get it, but I ran out of time last night. My little brother was sick and I had to help at home.","sayEs":"Ah. Entiendo, pero se me acabó el tiempo anoche. Mi hermano pequeño estaba enfermo y tuve que ayudar en casa.","mood":"concerned","choices":[{"id":"a","say":"Not my problem. You should plan your time better.","sayEs":"No es mi problema. Deberías planear mejor tu tiempo.","tag":"refuse","q":0,"why":"This ignores his reason and lectures him. A kind friend listens first.","whyEs":"Esto ignora su razón y le da un sermón. Un buen amigo escucha primero.","next":"n2b"},{"id":"b","say":"That sounds like a hard night. I will not give you my answers, because you would miss the practice.","sayEs":"Suena a una noche difícil. No te daré mis respuestas, porque perderías la práctica.","tag":"explain","q":2,"why":"You showed sympathy and used 'because' to explain your reason. That makes a firm no sound caring.","whyEs":"Mostraste compasión y usaste 'because' para explicar tu razón. Eso hace que un no firme suene amable.","next":"n3"},{"id":"c","say":"Hard night, I know. But I not give answers. Not fair.","sayEs":"Una noche difícil, lo sé. Pero no doy respuestas. No es justo.","tag":"explain","q":1,"why":"You showed understanding and gave a reason. Use 'I will not give answers' and 'because' to be clearer.","whyEs":"Mostraste comprensión y diste una razón. Usa 'I will not give answers' y 'because' para ser más claro.","next":"n3"}]},"n2b":{"who":"npc","say":"Wait, why are you being so serious? I just need a little help. What am I supposed to do now?","sayEs":"Espera, ¿por qué hablas con tanta seriedad? Solo necesito un poco de ayuda. ¿Qué se supone que haga ahora?","mood":"puzzled","choices":[{"id":"a","say":"Sorry, I did not mean to sound harsh. I can sit with you and explain the steps, if you want.","sayEs":"Perdón, no quise sonar duro. Puedo sentarme contigo y explicarte los pasos, si quieres.","tag":"offer","q":2,"why":"You apologized for your tone and made a friendly offer with 'I can' and 'if you want'.","whyEs":"Pediste perdón por tu tono e hiciste una oferta amable con 'I can' e 'if you want'.","next":"n3"},{"id":"b","say":"Do it yourself. I am not your teacher.","sayEs":"Hazlo tú. No soy tu docente.","tag":"refuse","q":0,"why":"This is harsh and ends the conversation. You can keep saying no and still offer help.","whyEs":"Esto es duro y termina la conversación. Puedes seguir diciendo que no y aun así ofrecer ayuda.","next":"end3"},{"id":"c","say":"Sorry. I can help. We do together.","sayEs":"Perdón. Puedo ayudar. Lo hacemos juntos.","tag":"offer","q":1,"why":"Your offer is kind and clear. Use 'We can do it together' for a smoother sentence.","whyEs":"Tu oferta es amable y clara. Usa 'We can do it together' para una oración más fluida.","next":"n3"}]},"n3":{"who":"npc","say":"Okay, that is fair. We only have ten minutes before class, though. What should we start with?","sayEs":"Está bien, es justo. Pero solo tenemos diez minutos antes de la clase. ¿Con qué empezamos?","mood":"pleased","choices":[{"id":"a","say":"Let me show you problem one, and you try problem two while I watch. Then you can ask your teacher about the rest.","sayEs":"Te muestro el problema uno y tú intentas el dos mientras yo miro. Después puedes preguntarle a tu docente por el resto.","tag":"offer","q":2,"why":"'Let me show you' is a concrete offer with a clear order. It helps him learn without handing over answers.","whyEs":"'Let me show you' es una oferta concreta con un orden claro. Lo ayuda a aprender sin darle las respuestas.","next":"n4"},{"id":"b","say":"Nothing. Ten minutes is not enough. Tell the teacher you did not do it.","sayEs":"Con nada. Diez minutos no son suficientes. Dile a tu docente que no la hiciste.","tag":"refuse","q":0,"why":"You offered help, then took it back. That feels unfair and leaves him with no plan.","whyEs":"Ofreciste ayuda y luego la retiraste. Eso se siente injusto y lo deja sin plan.","next":"end3"},{"id":"c","say":"I show you number one. Then you try.","sayEs":"Te muestro el número uno. Luego tú intentas.","tag":"offer","q":1,"why":"Your plan is clear. Use 'I will show you' and 'then you can try' to sound smoother.","whyEs":"Tu plan es claro. Usa 'I will show you' y 'then you can try' para sonar más fluido.","next":"n4"}]},"n4":{"who":"npc","say":"Oh, I see how you did that. Thanks. Should I tell Mr. Lopez I only finished part of it?","sayEs":"Ah, ya veo cómo lo hiciste. Gracias. ¿Le digo al Sr. López que solo terminé una parte?","mood":"happy","choices":[{"id":"a","say":"Yes, tell him. He understand, I think.","sayEs":"Sí, díselo. Creo que entenderá.","tag":"explain","q":1,"why":"Your advice is right. Use 'I think he will understand' and add a reason with 'because'.","whyEs":"Tu consejo es correcto. Usa 'I think he will understand' y agrega una razón con 'because'.","next":"end2"},{"id":"b","say":"Do what you want. But do not say I helped.","sayEs":"Haz lo que quieras. Pero no digas que yo ayudé.","tag":"refuse","q":0,"why":"Hiding the help makes it sound like a secret. Helping someone learn is nothing to hide.","whyEs":"Esconder la ayuda hace que parezca un secreto. Ayudar a alguien a aprender no es algo que esconder.","next":"end3"},{"id":"c","say":"Yes, I think being honest is best. Tell him what happened and ask for more time, because teachers usually understand.","sayEs":"Sí, creo que lo mejor es ser sincero. Cuéntale lo que pasó y pídele más tiempo, porque los docentes suelen entender.","tag":"explain","q":2,"why":"You gave advice with 'I think' and a reason with 'because'. Kind honesty supports him without doing his work.","whyEs":"Diste un consejo con 'I think' y una razón con 'because'. La honestidad amable lo apoya sin hacer su trabajo.","next":"end1"}]},"end1":{"who":"npc","say":"Thanks for the help, and for being straight with me. I feel ready now.","sayEs":"Gracias por la ayuda y por ser sincero conmigo. Ahora me siento listo.","mood":"happy","end":true,"outcome":"strong","wrap":"You said no politely, explained why, and offered real help. Tyrone learned the steps, and your friendship stayed strong.","wrapEs":"Dijiste que no con cortesía, explicaste por qué y ofreciste ayuda real. Tyrone aprendió los pasos y su amistad se mantuvo fuerte."},"end2":{"who":"npc","say":"Okay, I will tell him. Thanks for the lesson.","sayEs":"Está bien, se lo diré. Gracias por la lección.","mood":"pleased","end":true,"outcome":"ok","wrap":"You kept your no and still helped, but short answers lost some warmth. A reason with 'because' keeps a refusal kind.","wrapEs":"Mantuviste tu no y aun así ayudaste, pero las respuestas cortas perdieron algo de calidez. Una razón con 'because' mantiene amable una negativa."},"end3":{"who":"npc","say":"Fine. I will figure it out myself. See you in class.","sayEs":"Bien. Lo resolveré yo solo. Nos vemos en clase.","mood":"concerned","end":true,"outcome":"retry","wrap":"Your no sounded harsh, so the friendship felt tense. Use 'I would rather not', give a reason, and offer another kind of help.","wrapEs":"Tu no sonó duro, así que la amistad se sintió tensa. Usa 'I would rather not', da una razón y ofrece otro tipo de ayuda."}}},
  {"id":"c35-clinic-earache","b":"3-5","title":"At the doctor's office","titleEs":"En el consultorio de la doctora","place":"clinic","goal":"Tell the doctor about your sore ear and ask when you do not understand.","goalEs":"Contarle a la doctora sobre tu dolor de oído y pedir ayuda cuando no entiendas.","focus":["describe","clarify","thank"],"npc":{"name":"Dr. Okafor","role":"doctor","roleEs":"doctora","look":{"skin":"#8d5524","hair":"#2b1b12","style":"braids","shirt":"#2f6f9f","acc":"glasses"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"Hi, I am Dr. Okafor. What is bothering you today?","sayEs":"Hola, soy la doctora Okafor. ¿Qué te molesta hoy?","mood":"neutral","choices":[{"id":"a","say":"My ear is bad.","sayEs":"Mi oído está mal.","tag":"describe","q":1,"why":"You named the body part, but 'bad' is vague. Say 'hurts' so the doctor knows it is pain.","whyEs":"Nombraste la parte del cuerpo, pero 'bad' es vago. Di 'hurts' para que la doctora sepa que hay dolor.","next":"r1"},{"id":"b","say":"I want a sticker, please.","sayEs":"Quiero una calcomanía, por favor.","tag":"describe","q":0,"why":"This does not describe a problem, so the doctor still does not know what is wrong.","whyEs":"Esto no describe un problema, así que la doctora todavía no sabe qué pasa.","next":"r1"},{"id":"c","say":"My right ear hurts a lot, and it started last night.","sayEs":"Me duele mucho el oído derecho y empezó anoche.","tag":"describe","q":2,"why":"You described the place, the feeling, and when it began. That gives the doctor clear facts.","whyEs":"Describiste el lugar, la sensación y cuándo empezó. Eso le da datos claros a la doctora.","next":"n2"}]},"n2":{"who":"npc","say":"I am sorry to hear that. Do you have a sore throat or a fever too?","sayEs":"Lamento oír eso. ¿También tienes dolor de garganta o fiebre?","mood":"concerned","choices":[{"id":"a","say":"Yes. Hot head.","sayEs":"Sí. Cabeza caliente.","tag":"describe","q":1,"why":"The doctor can guess you mean fever, but the phrase is 'I have a fever.'","whyEs":"La doctora puede adivinar que es fiebre, pero la frase correcta es 'I have a fever'.","next":"n3"},{"id":"b","say":"My throat is sore, but I do not have a fever.","sayEs":"Me duele la garganta, pero no tengo fiebre.","tag":"describe","q":2,"why":"You used 'but' to describe two symptoms, one yes and one no. That is clear and complete.","whyEs":"Usaste 'but' para describir dos síntomas, uno sí y uno no. Es claro y completo.","next":"n3"},{"id":"c","say":"My dog is sick too.","sayEs":"Mi perro también está enfermo.","tag":"describe","q":0,"why":"This is about something else. The doctor needs to hear your symptoms, not your dog's.","whyEs":"Esto es sobre otra cosa. La doctora necesita oír tus síntomas, no los de tu perro.","next":"r2"}]},"r1":{"who":"npc","say":"Hmm, I am not sure I understand. Which part of your body hurts?","sayEs":"Mmm, no estoy segura de entender. ¿Qué parte de tu cuerpo te duele?","mood":"puzzled","choices":[{"id":"a","say":"Nothing.","sayEs":"Nada.","tag":"describe","q":0,"why":"Saying 'nothing' stops the talk. The doctor cannot help without details.","whyEs":"Decir 'nothing' detiene la conversación. La doctora no puede ayudar sin detalles.","next":"r2"},{"id":"b","say":"My left ear hurts. It feels sharp when I touch it.","sayEs":"Me duele el oído izquierdo. Siento un dolor punzante cuando lo toco.","tag":"describe","q":2,"why":"You named the ear and described the feeling with 'sharp.' Details like these help the doctor.","whyEs":"Nombraste el oído y describiste la sensación con 'sharp'. Detalles así ayudan a la doctora.","next":"n3"},{"id":"c","say":"Here. My ear hurt.","sayEs":"Aquí. Me duele el oído.","tag":"describe","q":1,"why":"Pointing and saying 'ear' helps. Use present tense: 'My ear hurts.'","whyEs":"Señalar y decir 'ear' ayuda. Usa el presente: 'My ear hurts'.","next":"n3"}]},"n3":{"who":"npc","say":"Your ear is red inside. It is an infection, so I will give you ear drops.","sayEs":"Tu oído está rojo por dentro. Es una infección, así que te daré gotas para el oído.","mood":"neutral","choices":[{"id":"a","say":"No drops. I do not like it.","sayEs":"Sin gotas. No me gusta.","tag":"clarify","q":0,"why":"Saying no without a reason can worry the doctor. Asking what drops are would help you understand.","whyEs":"Decir no sin razón puede preocupar a la doctora. Preguntar qué son las gotas te ayudaría a entender.","next":"r2"},{"id":"b","say":"Could you say that more slowly, please? What are ear drops?","sayEs":"¿Podría decirlo más despacio, por favor? ¿Qué son las gotas para el oído?","tag":"clarify","q":2,"why":"'Could you... please' politely asks for a slower repeat, and you asked a clear question.","whyEs":"'Could you... please' pide con cortesía que lo repita más despacio, y hiciste una pregunta clara.","next":"n4"},{"id":"c","say":"What is drops?","sayEs":"¿Qué es gotas?","tag":"clarify","q":1,"why":"Asking is good! Drops is plural, so say 'What are drops?'","whyEs":"¡Preguntar es bueno! 'Drops' es plural, así que di 'What are drops?'","next":"n4"}]},"r2":{"who":"npc","say":"Let me try again. You have an ear infection, and medicine can help. Do you understand?","sayEs":"Déjame intentarlo otra vez. Tienes una infección de oído y la medicina puede ayudar. ¿Entiendes?","mood":"puzzled","choices":[{"id":"a","say":"A little. Say again, please.","sayEs":"Un poco. Dígalo otra vez, por favor.","tag":"clarify","q":1,"why":"You asked for a repeat, which is good. Add 'Could you' to sound more polite.","whyEs":"Pediste que lo repita, y eso está bien. Agrega 'Could you' para sonar más cortés.","next":"n4"},{"id":"b","say":"Yes, yes. Can we go now?","sayEs":"Sí, sí. ¿Ya nos podemos ir?","tag":"clarify","q":0,"why":"Saying yes when you do not understand can cause problems. Say what is unclear instead.","whyEs":"Decir que sí cuando no entiendes puede causar problemas. Mejor di qué no está claro.","next":"e3"},{"id":"c","say":"Sorry, I do not understand. Could you explain again, please?","sayEs":"Perdón, no entiendo. ¿Podría explicar otra vez, por favor?","tag":"clarify","q":2,"why":"'Sorry' plus 'Could you explain' is a polite way to ask for help when something is unclear.","whyEs":"'Sorry' más 'Could you explain' es una forma cortés de pedir ayuda cuando algo no está claro.","next":"n4"}]},"n4":{"who":"npc","say":"Ear drops are liquid medicine for your ear. Use two drops at night. Do you have any questions?","sayEs":"Las gotas son una medicina líquida para el oído. Usa dos gotas por la noche. ¿Tienes alguna pregunta?","mood":"pleased","choices":[{"id":"a","say":"No. Thanks.","sayEs":"No. Gracias.","tag":"thank","q":1,"why":"'Thanks' is polite, but a full sentence sounds warmer: 'Thank you for helping me.'","whyEs":"'Thanks' es cortés, pero una oración completa suena más cálida: 'Thank you for helping me'.","next":"e2"},{"id":"b","say":"Finally. This took too long.","sayEs":"Por fin. Esto tardó mucho.","tag":"thank","q":0,"why":"Complaining about the visit is unkind. The doctor spent time helping you.","whyEs":"Quejarte de la visita no es amable. La doctora dedicó tiempo a ayudarte.","next":"e3"},{"id":"c","say":"No, I understand. Thank you for explaining it to me, Dr. Okafor.","sayEs":"No, entiendo. Gracias por explicármelo, doctora Okafor.","tag":"thank","q":2,"why":"You said you understand and thanked her for explaining. That shows respect and closes the visit well.","whyEs":"Dijiste que entiendes y le agradeciste por explicar. Eso muestra respeto y cierra bien la visita.","next":"e1"}]},"e1":{"who":"npc","say":"You explained it so well. Use the drops tonight, rest, and feel better soon.","sayEs":"Lo explicaste muy bien. Usa las gotas esta noche, descansa y mejórate pronto.","mood":"happy","end":true,"outcome":"strong","wrap":"You described your pain clearly, asked for a slower explanation, and said thank you. That helped the doctor care for you.","wrapEs":"Describiste tu dolor con claridad, pediste una explicación más lenta y diste las gracias. Eso ayudó a la doctora a cuidarte."},"e2":{"who":"npc","say":"Okay. Use the drops at night. Come back if your ear still hurts.","sayEs":"Muy bien. Usa las gotas por la noche. Vuelve si todavía te duele el oído.","mood":"neutral","end":true,"outcome":"ok","wrap":"The doctor helped you, but short answers left some questions. Giving details and asking 'Could you...?' works better.","wrapEs":"La doctora te ayudó, pero las respuestas cortas dejaron preguntas. Dar detalles y preguntar 'Could you...?' funciona mejor."},"e3":{"who":"npc","say":"I want to be sure you understand. Let us talk it through again, slowly.","sayEs":"Quiero asegurarme de que entiendas. Repasémoslo otra vez, despacio.","mood":"concerned","end":true,"outcome":"retry","wrap":"The visit ended before everything was clear. Next time, say what hurts and ask politely when you do not understand.","wrapEs":"La visita terminó antes de que todo estuviera claro. La próxima vez, di qué te duele y pregunta con cortesía cuando no entiendas."}}},
  {"id":"c35-phone-ride","b":"3-5","title":"Calling a family friend","titleEs":"Llamar a una amiga de la familia","place":"phone","goal":"Call a family friend, ask for a ride to practice, and say thank you.","goalEs":"Llamar a una amiga de la familia, pedir que te lleve a la práctica y dar las gracias.","focus":["greet","request","thank"],"npc":{"name":"Mrs. Nguyen","role":"family friend","roleEs":"amiga de la familia","look":{"skin":"#f1c9a5","hair":"#1f1a17","style":"ponytail","shirt":"#a8453b","acc":"none"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"Hello, this is Mrs. Nguyen.","sayEs":"Hola, habla la señora Nguyen.","mood":"neutral","choices":[{"id":"a","say":"Hello, Mrs. Nguyen. This is Mateo. How are you today?","sayEs":"Hola, señora Nguyen. Habla Mateo. ¿Cómo está hoy?","tag":"greet","q":2,"why":"You said hello, told her who you are, and asked about her day. That is a warm phone greeting.","whyEs":"Saludaste, dijiste quién eres y preguntaste por su día. Es un saludo cálido por teléfono.","next":"n2"},{"id":"b","say":"Hi. Mateo.","sayEs":"Hola. Mateo.","tag":"greet","q":1,"why":"She can tell it is you, but 'This is Mateo' and 'How are you?' sound friendlier.","whyEs":"Ella sabe que eres tú, pero 'This is Mateo' y 'How are you?' suenan más amables.","next":"r1"},{"id":"c","say":"Hey, I need a ride. Now.","sayEs":"Oye, necesito que me lleve. Ya.","tag":"greet","q":0,"why":"Starting with a demand and no greeting sounds rude. Say hello first, then ask.","whyEs":"Empezar con una exigencia y sin saludo suena grosero. Saluda primero y luego pide.","next":"r1"}]},"n2":{"who":"npc","say":"Hello, Mateo! I am fine, thank you. What can I do for you?","sayEs":"¡Hola, Mateo! Estoy bien, gracias. ¿En qué puedo ayudarte?","mood":"happy","choices":[{"id":"a","say":"Can you take me to soccer? Tomorrow at four.","sayEs":"¿Me puede llevar al fútbol? Mañana a las cuatro.","tag":"request","q":1,"why":"Your idea is clear. Adding 'please' or using 'Could you' would sound more polite.","whyEs":"Tu idea es clara. Agregar 'please' o usar 'Could you' sonaría más cortés.","next":"n3"},{"id":"b","say":"Could you please give me a ride to soccer practice tomorrow?","sayEs":"¿Podría llevarme, por favor, a la práctica de fútbol mañana?","tag":"request","q":2,"why":"'Could you please' is a polite request. You also said where and when you need the ride.","whyEs":"'Could you please' es una petición cortés. También dijiste dónde y cuándo necesitas el viaje.","next":"n3"},{"id":"c","say":"Take me to soccer. Tomorrow at four.","sayEs":"Lléveme al fútbol. Mañana a las cuatro.","tag":"request","q":0,"why":"This is a command. Without 'please' or 'Could you', it sounds like an order, not a favor.","whyEs":"Es una orden. Sin 'please' o 'Could you', suena como una orden y no como un favor.","next":"r2"}]},"r1":{"who":"npc","say":"I am sorry, I did not hear you well. Who is calling, and what do you need?","sayEs":"Perdón, no te escuché bien. ¿Quién llama y qué necesitas?","mood":"puzzled","choices":[{"id":"a","say":"Nothing. Bye.","sayEs":"Nada. Adiós.","tag":"request","q":0,"why":"Hanging up leaves her confused. If you need help, say who you are and what you need.","whyEs":"Colgar la deja confundida. Si necesitas ayuda, di quién eres y qué necesitas.","next":"r2"},{"id":"b","say":"Sorry about that. This is Mateo. Could you drive me to soccer tomorrow?","sayEs":"Perdón por eso. Habla Mateo. ¿Podría llevarme al fútbol mañana?","tag":"request","q":2,"why":"You said sorry, told her your name, and asked with 'Could you'. That fixes the confusion politely.","whyEs":"Dijiste perdón, tu nombre y pediste con 'Could you'. Eso arregla la confusión con cortesía.","next":"n3"},{"id":"c","say":"It is Mateo. I need a ride, please.","sayEs":"Soy Mateo. Necesito que me lleve, por favor.","tag":"request","q":1,"why":"You said who you are and used 'please'. Try 'Could you give me a ride?' for a softer request.","whyEs":"Dijiste quién eres y usaste 'please'. Prueba 'Could you give me a ride?' para sonar más suave.","next":"n3"}]},"n3":{"who":"npc","say":"Soccer practice at four? Yes, I can take you. I will pick you up at three thirty.","sayEs":"¿Práctica de fútbol a las cuatro? Sí, puedo llevarte. Pasaré por ti a las tres y media.","mood":"happy","choices":[{"id":"a","say":"Do not be late like last time.","sayEs":"No llegue tarde como la última vez.","tag":"thank","q":0,"why":"This sounds rude. She is doing you a favor, so thank her instead of giving orders.","whyEs":"Suena grosero. Ella te hace un favor, así que dale las gracias en vez de dar órdenes.","next":"r2"},{"id":"b","say":"OK. Good.","sayEs":"Está bien. Bueno.","tag":"thank","q":1,"why":"She knows you agree, but you did not say thanks. Say 'Thank you' when someone helps you.","whyEs":"Ella sabe que aceptas, pero no diste las gracias. Di 'Thank you' cuando alguien te ayuda.","next":"n4"},{"id":"c","say":"Thank you so much! I will be ready at three thirty.","sayEs":"¡Muchas gracias! Estaré listo a las tres y media.","tag":"thank","q":2,"why":"You thanked her warmly and repeated the time to show you will be ready.","whyEs":"Le agradeciste con calidez y repetiste la hora para mostrar que estarás listo.","next":"n4"}]},"r2":{"who":"npc","say":"Hmm, let me ask again. Do you want me to take you to practice tomorrow?","sayEs":"Mmm, déjame preguntar otra vez. ¿Quieres que te lleve a la práctica mañana?","mood":"puzzled","choices":[{"id":"a","say":"Yes. Ride, please.","sayEs":"Sí. Que me lleve, por favor.","tag":"request","q":1,"why":"'Yes' and 'please' are good. Use a full sentence like 'Yes, please take me.'","whyEs":"'Yes' y 'please' están bien. Usa una oración completa como 'Yes, please take me'.","next":"n4"},{"id":"b","say":"I do not know. My mom said ask.","sayEs":"No sé. Mi mamá dijo que preguntara.","tag":"request","q":0,"why":"This does not answer her question. Say 'Yes, please' if you need the ride.","whyEs":"Esto no responde su pregunta. Di 'Yes, please' si necesitas el viaje.","next":"e3"},{"id":"c","say":"Yes, please. Could you pick me up at three thirty?","sayEs":"Sí, por favor. ¿Podría pasar por mí a las tres y media?","tag":"request","q":2,"why":"You answered clearly, said please, and asked politely about the time with 'Could you'.","whyEs":"Respondiste con claridad, dijiste please y preguntaste con cortesía la hora con 'Could you'.","next":"n4"}]},"n4":{"who":"npc","say":"Okay, see you tomorrow at three thirty. Is there anything else?","sayEs":"Muy bien, hasta mañana a las tres y media. ¿Algo más?","mood":"neutral","choices":[{"id":"a","say":"No. Bye.","sayEs":"No. Adiós.","tag":"thank","q":1,"why":"Short and clear, but you can end with kind words like 'Thank you' and 'Have a nice day.'","whyEs":"Corto y claro, pero puedes terminar con palabras amables como 'Thank you' y 'Have a nice day'.","next":"e2"},{"id":"b","say":"Yes, can you buy me a snack too?","sayEs":"Sí, ¿también me puede comprar una merienda?","tag":"request","q":0,"why":"Asking for more right after a favor can seem pushy. Thank her and end the call kindly.","whyEs":"Pedir más justo después de un favor puede parecer insistente. Dale las gracias y termina con amabilidad.","next":"e3"},{"id":"c","say":"No, that is all. Thank you, Mrs. Nguyen. Have a nice day!","sayEs":"No, eso es todo. Gracias, señora Nguyen. ¡Que tenga un buen día!","tag":"thank","q":2,"why":"You thanked her by name and ended the call with a kind wish. That is a polite closing.","whyEs":"Le agradeciste por su nombre y cerraste con un buen deseo. Es un cierre cortés.","next":"e1"}]},"e1":{"who":"npc","say":"You are welcome, Mateo! See you tomorrow. Have a good day too.","sayEs":"¡De nada, Mateo! Hasta mañana. Que tengas un buen día también.","mood":"happy","end":true,"outcome":"strong","wrap":"You greeted her, asked politely for a ride, and thanked her. Polite words made it easy for her to say yes.","wrapEs":"La saludaste, pediste con cortesía que te lleve y le diste las gracias. Las palabras corteses le facilitaron decir que sí."},"e2":{"who":"npc","say":"Okay. Bye, Mateo.","sayEs":"Muy bien. Adiós, Mateo.","mood":"neutral","end":true,"outcome":"ok","wrap":"You got your ride, but the call ended quickly. Adding 'please' and 'thank you' makes a phone call warmer.","wrapEs":"Conseguiste el viaje, pero la llamada terminó rápido. Agregar 'please' y 'thank you' hace la llamada más cálida."},"e3":{"who":"npc","say":"Oh. Um, call me back if you still need a ride tomorrow.","sayEs":"Ah. Eh, llámame de nuevo si todavía necesitas que te lleve mañana.","mood":"puzzled","end":true,"outcome":"retry","wrap":"The call became confusing. Greet first, say what you need with 'Could you please', and end with thank you.","wrapEs":"La llamada se volvió confusa. Saluda primero, di lo que necesitas con 'Could you please' y termina con thank you."}}},
  {"id":"c35-store-notebook","b":"3-5","title":"Finding things at the store","titleEs":"Buscar cosas en la tienda","place":"store","goal":"Ask where to find a notebook, say sorry for an accident, and pay politely.","goalEs":"Preguntar dónde hay un cuaderno, disculparte por un accidente y pagar con cortesía.","focus":["question","apologize","thank"],"npc":{"name":"Mr. Mensah","role":"store clerk","roleEs":"empleado de la tienda","look":{"skin":"#5c3a21","hair":"#111111","style":"short","shirt":"#d9822b","acc":"none"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"Hi there! Are you looking for something?","sayEs":"¡Hola! ¿Buscas algo?","mood":"happy","choices":[{"id":"a","say":"Where is notebook?","sayEs":"¿Dónde está cuaderno?","tag":"question","q":1,"why":"The word 'notebook' needs 'the' or 'a'. Try 'Where is the notebook?' or 'Where are the notebooks?'","whyEs":"La palabra 'notebook' necesita 'the' o 'a'. Prueba 'Where is the notebook?' o 'Where are the notebooks?'","next":"r1"},{"id":"b","say":"No. Leave me alone.","sayEs":"No. Déjeme en paz.","tag":"question","q":0,"why":"This is unfriendly. He is offering help. Say 'Yes, please' and ask your question.","whyEs":"Es poco amable. Él ofrece ayuda. Di 'Yes, please' y haz tu pregunta.","next":"r1"},{"id":"c","say":"Yes, please. Where can I find the notebooks?","sayEs":"Sí, por favor. ¿Dónde puedo encontrar los cuadernos?","tag":"question","q":2,"why":"You said 'please' and used 'Where can I find...' That is a polite wh- question.","whyEs":"Dijiste 'please' y usaste 'Where can I find...'. Es una pregunta con wh- y es cortés.","next":"n2"}]},"n2":{"who":"npc","say":"Notebooks are in aisle three, next to the pencils. Anything else?","sayEs":"Los cuadernos están en el pasillo tres, junto a los lápices. ¿Algo más?","mood":"neutral","choices":[{"id":"a","say":"Yes. How much is this blue notebook?","sayEs":"Sí. ¿Cuánto cuesta este cuaderno azul?","tag":"question","q":2,"why":"'How much is...' is the right question for a price, and 'this blue notebook' is specific.","whyEs":"'How much is...' es la pregunta correcta para un precio, y 'this blue notebook' es específico.","next":"n3"},{"id":"b","say":"How much it is?","sayEs":"¿Cuánto cuesta?","tag":"question","q":1,"why":"Good idea to ask! The word order is 'How much is it?'","whyEs":"¡Buena idea preguntar! El orden de las palabras es 'How much is it?'","next":"n3"},{"id":"c","say":"That is far. Carry it for me.","sayEs":"Está lejos. Tráigamelo.","tag":"question","q":0,"why":"This is a command. Ask 'Could you help me?' if you need help.","whyEs":"Es una orden. Pregunta 'Could you help me?' si necesitas ayuda.","next":"r2"}]},"r1":{"who":"npc","say":"Sorry, I did not catch that. What do you need to find?","sayEs":"Perdón, no te entendí. ¿Qué necesitas encontrar?","mood":"puzzled","choices":[{"id":"a","say":"Notebook? Where?","sayEs":"¿Cuaderno? ¿Dónde?","tag":"question","q":1,"why":"One-word questions can work, but a full question is clearer: 'Where is the notebook?'","whyEs":"Las preguntas de una palabra pueden funcionar, pero una completa es más clara: 'Where is the notebook?'","next":"n2"},{"id":"b","say":"Never mind. This store is bad.","sayEs":"Olvídelo. Esta tienda es mala.","tag":"question","q":0,"why":"Complaining does not help. Say again what you need, and the clerk can point to it.","whyEs":"Quejarte no ayuda. Repite lo que necesitas y el empleado puede señalártelo.","next":"r2"},{"id":"c","say":"Sorry, I need a notebook. Where are the notebooks, please?","sayEs":"Perdón, necesito un cuaderno. ¿Dónde están los cuadernos, por favor?","tag":"question","q":2,"why":"You said sorry, told what you need, and asked politely with 'please.'","whyEs":"Dijiste perdón, explicaste qué necesitas y preguntaste con cortesía usando 'please'.","next":"n2"}]},"n3":{"who":"npc","say":"That one is two dollars. Oh no, a pencil box just fell near you!","sayEs":"Ese cuesta dos dólares. ¡Ay, no! ¡Se cayó una caja de lápices cerca de ti!","mood":"concerned","choices":[{"id":"a","say":"It was not me. The shelf is bad.","sayEs":"No fui yo. El estante está mal.","tag":"apologize","q":0,"why":"Blaming something else does not help. A short 'I am sorry' is kind, even for small accidents.","whyEs":"Culpar a otra cosa no ayuda. Un 'I am sorry' corto es amable, aun en accidentes pequeños.","next":"r2"},{"id":"b","say":"Oh, I am sorry! I bumped it. I will pick them up.","sayEs":"¡Ay, lo siento! Lo golpeé. Los voy a recoger.","tag":"apologize","q":2,"why":"'I am sorry' plus 'I will pick them up' shows you care and will fix the problem.","whyEs":"'I am sorry' más 'I will pick them up' muestra que te importa y que arreglarás el problema.","next":"n4"},{"id":"c","say":"Sorry. Pencils.","sayEs":"Perdón. Lápices.","tag":"apologize","q":1,"why":"'Sorry' is good. Add what you will do: 'I will pick them up.'","whyEs":"'Sorry' está bien. Agrega lo que harás: 'I will pick them up'.","next":"n4"}]},"r2":{"who":"npc","say":"Hmm, let us start again. Would you like to buy the notebook?","sayEs":"Mmm, empecemos otra vez. ¿Quieres comprar el cuaderno?","mood":"puzzled","choices":[{"id":"a","say":"Yes. Where pay?","sayEs":"Sí. ¿Dónde pago?","tag":"question","q":1,"why":"Good question, but add 'do I'. Say 'Where do I pay?'","whyEs":"Buena pregunta, pero agrega 'do I'. Di 'Where do I pay?'","next":"n4"},{"id":"b","say":"No. Everything costs too much here.","sayEs":"No. Aquí todo cuesta demasiado.","tag":"question","q":0,"why":"This is a complaint, not an answer. If you want the notebook, say 'Yes, please.'","whyEs":"Es una queja, no una respuesta. Si quieres el cuaderno, di 'Yes, please'.","next":"e3"},{"id":"c","say":"Yes, please. How much is it, and where do I pay?","sayEs":"Sí, por favor. ¿Cuánto cuesta y dónde pago?","tag":"question","q":2,"why":"You answered with 'please' and asked two clear questions with correct word order.","whyEs":"Respondiste con 'please' e hiciste dos preguntas claras con el orden correcto.","next":"n4"}]},"n4":{"who":"npc","say":"Great. The notebook is two dollars. You can pay here at the counter.","sayEs":"Muy bien. El cuaderno cuesta dos dólares. Puedes pagar aquí en el mostrador.","mood":"happy","choices":[{"id":"a","say":"Here. Bye.","sayEs":"Aquí tiene. Adiós.","tag":"thank","q":1,"why":"You paid, but you did not say thank you. Kind words make shopping friendlier.","whyEs":"Pagaste, pero no dijiste gracias. Las palabras amables hacen la compra más agradable.","next":"e2"},{"id":"b","say":"Here is two dollars. Thank you for your help today!","sayEs":"Aquí tiene dos dólares. ¡Gracias por su ayuda hoy!","tag":"thank","q":2,"why":"You paid and thanked him for helping. That is a polite way to finish shopping.","whyEs":"Pagaste y le agradeciste su ayuda. Es una forma cortés de terminar la compra.","next":"e1"},{"id":"c","say":"Two dollars? Too much. I give you one.","sayEs":"¿Dos dólares? Es mucho. Le doy uno.","tag":"thank","q":0,"why":"Offering less money is not polite. Pay the price, or ask kindly if there is a cheaper one.","whyEs":"Ofrecer menos dinero no es cortés. Paga el precio o pregunta con amabilidad si hay uno más barato.","next":"e3"}]},"e1":{"who":"npc","say":"Thank you! Here is your change. Enjoy your new notebook.","sayEs":"¡Gracias a ti! Aquí está tu cambio. Disfruta tu cuaderno nuevo.","mood":"happy","end":true,"outcome":"strong","wrap":"You asked where to find it, said sorry for the accident, and thanked the clerk. Polite questions made shopping easy.","wrapEs":"Preguntaste dónde encontrarlo, te disculpaste por el accidente y le diste las gracias al empleado. Las preguntas corteses facilitaron la compra."},"e2":{"who":"npc","say":"Okay. Here is your change.","sayEs":"Muy bien. Aquí está tu cambio.","mood":"neutral","end":true,"outcome":"ok","wrap":"You found the notebook and paid. Adding 'thank you' and full questions makes shopping smoother.","wrapEs":"Encontraste el cuaderno y pagaste. Agregar 'thank you' y preguntas completas hace la compra más fácil."},"e3":{"who":"npc","say":"I am sorry, I am still confused. Let us try again from the beginning.","sayEs":"Lo siento, sigo confundido. Intentemos otra vez desde el principio.","mood":"puzzled","end":true,"outcome":"retry","wrap":"The clerk could not help because the words were unclear or unkind. Ask 'Where is...' or 'How much is...' and say thank you.","wrapEs":"El empleado no pudo ayudar porque las palabras no eran claras o amables. Pregunta 'Where is...' o 'How much is...' y di thank you."}}},
  {"id":"c35-street-ball","b":"3-5","title":"Can I borrow your ball?","titleEs":"¿Me prestas tu pelota?","place":"street","goal":"Answer a neighbor who wants to borrow your ball. Say yes or no kindly and give reasons.","goalEs":"Responder a un vecino que quiere tu pelota. Decir sí o no con amabilidad y dar razones.","focus":["refuse","explain","accept"],"npc":{"name":"Yusuf","role":"neighbor","roleEs":"vecino","look":{"skin":"#c68642","hair":"#1a1a1a","style":"cap","shirt":"#2f9f6f","acc":"none"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"Hi! Can I borrow your ball for a little while?","sayEs":"¡Hola! ¿Me prestas tu pelota un ratito?","mood":"happy","choices":[{"id":"a","say":"Okay. Bring it back.","sayEs":"Está bien. Devuélvela.","tag":"accept","q":1,"why":"You said yes, but 'when' is missing. Say 'Please bring it back before dinner.'","whyEs":"Dijiste que sí, pero falta 'cuándo'. Di 'Please bring it back before dinner'.","next":"r1"},{"id":"b","say":"Yes, you can borrow it. Please bring it back before dinner.","sayEs":"Sí, te la puedo prestar. Por favor, devuélvela antes de la cena.","tag":"accept","q":2,"why":"You said yes kindly and gave a clear time with 'please.' That sets a polite limit.","whyEs":"Dijiste que sí con amabilidad y diste una hora clara con 'please'. Eso pone un límite cortés.","next":"n2"},{"id":"c","say":"No! It is mine. Go away.","sayEs":"¡No! Es mía. Vete.","tag":"refuse","q":0,"why":"Your 'no' is unkind. You can say 'Sorry, I need it' and give a reason.","whyEs":"Tu 'no' no es amable. Puedes decir 'Sorry, I need it' y dar una razón.","next":"r1"}]},"n2":{"who":"npc","say":"Thanks! Can I also keep it until tomorrow? My cousin is visiting.","sayEs":"¡Gracias! ¿También me la puedo quedar hasta mañana? Mi primo viene de visita.","mood":"happy","choices":[{"id":"a","say":"I am sorry, but I need it tomorrow for my game.","sayEs":"Lo siento, pero la necesito mañana para mi partido.","tag":"refuse","q":2,"why":"'I am sorry, but' softens the no, and 'for my game' is a clear reason.","whyEs":"'I am sorry, but' suaviza el no, y 'for my game' es una razón clara.","next":"n3"},{"id":"b","say":"No. Not tomorrow.","sayEs":"No. Mañana no.","tag":"refuse","q":1,"why":"Your answer is clear, but it sounds short. Add 'sorry' and a reason.","whyEs":"Tu respuesta es clara, pero suena corta. Agrega 'sorry' y una razón.","next":"n3"},{"id":"c","say":"You never give things back. No.","sayEs":"Tú nunca devuelves las cosas. No.","tag":"explain","q":0,"why":"This blames him and could hurt his feelings. Give a reason about yourself instead.","whyEs":"Esto lo culpa y puede herir sus sentimientos. Mejor da una razón sobre ti.","next":"r2"}]},"r1":{"who":"npc","say":"Wait, is that a yes or a no? When should I bring it back?","sayEs":"Espera, ¿es un sí o un no? ¿Cuándo debo devolverla?","mood":"puzzled","choices":[{"id":"a","say":"Whatever. I do not care.","sayEs":"Lo que sea. No me importa.","tag":"explain","q":0,"why":"This does not answer him. He needs to know yes or no and the time.","whyEs":"No le responde. Él necesita saber sí o no y la hora.","next":"r2"},{"id":"b","say":"Yes. Back at five.","sayEs":"Sí. Devuélvela a las cinco.","tag":"explain","q":1,"why":"Clear yes and time. Add a reason with 'because' so he understands.","whyEs":"Sí y hora claros. Agrega una razón con 'because' para que te entienda.","next":"n3"},{"id":"c","say":"Yes, but I need it back by five because I have practice.","sayEs":"Sí, pero la necesito de vuelta a las cinco porque tengo práctica.","tag":"explain","q":2,"why":"'Because' gives your reason, so he understands why the time matters.","whyEs":"'Because' da tu razón, así él entiende por qué importa la hora.","next":"n3"}]},"n3":{"who":"npc","say":"Okay, no problem. I will bring the ball back by five. Where can we meet?","sayEs":"Está bien, no hay problema. Te traigo la pelota antes de las cinco. ¿Dónde nos vemos?","mood":"neutral","choices":[{"id":"a","say":"My door. Okay.","sayEs":"Mi puerta. Está bien.","tag":"invite","q":1,"why":"You answered where, but a full sentence is friendlier: 'We can meet at my door.'","whyEs":"Respondiste dónde, pero una oración completa es más amable: 'We can meet at my door'.","next":"n4"},{"id":"b","say":"Do you want to play together first? We can meet at my door.","sayEs":"¿Quieres jugar juntos primero? Podemos vernos en mi puerta.","tag":"invite","q":2,"why":"'Do you want to...' is a friendly invitation, and you named a meeting place.","whyEs":"'Do you want to...' es una invitación amistosa, y nombraste un lugar para encontrarse.","next":"n4"},{"id":"c","say":"I do not care. Figure it out.","sayEs":"No me importa. Averígualo tú.","tag":"invite","q":0,"why":"This is unfriendly and gives no place. Suggest a spot, like 'my door.'","whyEs":"No es amable y no da un lugar. Sugiere un sitio, como 'my door'.","next":"r2"}]},"r2":{"who":"npc","say":"Oh, sorry. I only want to play for a little while. Is that okay?","sayEs":"Ay, perdón. Solo quiero jugar un ratito. ¿Está bien?","mood":"concerned","choices":[{"id":"a","say":"Fine. Whatever. Do not break it.","sayEs":"Bueno, lo que sea. No la rompas.","tag":"accept","q":0,"why":"This sounds angry. You can say yes and ask kindly: 'Please be careful.'","whyEs":"Suena enojado. Puedes decir que sí y pedir con amabilidad: 'Please be careful'.","next":"e3"},{"id":"b","say":"Yes, play. Bring it back.","sayEs":"Sí, juega. Devuélvela.","tag":"accept","q":1,"why":"Yes is clear. Adding 'please' and 'soon' would sound kinder.","whyEs":"El sí es claro. Agregar 'please' y 'soon' sonaría más amable.","next":"n4"},{"id":"c","say":"It is okay. Please be careful and bring it back soon.","sayEs":"Está bien. Ten cuidado y devuélvela pronto, por favor.","tag":"accept","q":2,"why":"You accepted kindly and added a polite reminder with 'please.'","whyEs":"Aceptaste con amabilidad y agregaste un recordatorio cortés con 'please'.","next":"n4"}]},"n4":{"who":"npc","say":"Thanks! One more thing: can I borrow your jump rope for my cousin?","sayEs":"¡Gracias! Una cosa más: ¿me prestas tu cuerda para saltar para mi primo?","mood":"happy","choices":[{"id":"a","say":"No. Only the ball.","sayEs":"No. Solo la pelota.","tag":"refuse","q":1,"why":"Your no is clear, but a reason makes it kinder.","whyEs":"Tu no es claro, pero una razón lo hace más amable.","next":"e2"},{"id":"b","say":"No way. You ask too much.","sayEs":"Ni hablar. Pides demasiado.","tag":"refuse","q":0,"why":"This is rude. You can say no kindly with 'Sorry, I cannot' and a reason.","whyEs":"Es grosero. Puedes decir que no con amabilidad usando 'Sorry, I cannot' y una razón.","next":"e3"},{"id":"c","say":"Sorry, I cannot. My sister is using it, so maybe next time.","sayEs":"Lo siento, no puedo. Mi hermana la está usando, así que tal vez la próxima vez.","tag":"refuse","q":2,"why":"You said sorry, gave a reason, and offered 'next time.' That is a kind no.","whyEs":"Dijiste sorry, diste una razón y ofreciste 'next time'. Es un no amable.","next":"e1"}]},"e1":{"who":"npc","say":"That is okay. I will bring the ball back soon. Thanks for sharing!","sayEs":"No hay problema. Te traigo la pelota pronto. ¡Gracias por compartir!","mood":"happy","end":true,"outcome":"strong","wrap":"You said yes with a time limit, said no kindly, and gave reasons. Yusuf still feels respected.","wrapEs":"Dijiste que sí con un límite de hora, dijiste que no con amabilidad y diste razones. Yusuf se siente respetado."},"e2":{"who":"npc","say":"Okay. I will bring the ball back later.","sayEs":"Está bien. Te traigo la pelota más tarde.","mood":"neutral","end":true,"outcome":"ok","wrap":"You were clear, but short answers can sound unfriendly. Adding 'sorry' and a reason keeps the friendship strong.","wrapEs":"Fuiste claro, pero las respuestas cortas pueden sonar poco amables. Agregar 'sorry' y una razón fortalece la amistad."},"e3":{"who":"npc","say":"Oh. I think I will go home. See you later.","sayEs":"Ay. Creo que me voy a casa. Nos vemos luego.","mood":"concerned","end":true,"outcome":"retry","wrap":"Yusuf felt upset by the rude words. Try 'Sorry, but I need it' and give a reason.","wrapEs":"Yusuf se sintió mal por las palabras groseras. Prueba 'Sorry, but I need it' y da una razón."}}},
  {"id":"c68-clinic-medicine","b":"6-8","title":"Describing symptoms to the doctor","titleEs":"Describir los síntomas al doctor","place":"clinic","goal":"Describe your symptoms and ask what the medicine is for and how to take it.","goalEs":"Describir tus síntomas y preguntar para qué sirve la medicina y cómo tomarla.","focus":["describe","question","clarify"],"npc":{"name":"Dr. Patel","role":"doctor","roleEs":"doctor","look":{"skin":"#c68642","hair":"#1a1a1a","style":"short","shirt":"#3a7d5c","acc":"glasses"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"Hello, I am Dr. Patel. Tell me what has been bothering you.","sayEs":"Hola, soy el doctor Patel. Cuéntame qué te ha estado molestando.","mood":"neutral","choices":[{"id":"a","say":"I have had a sore throat and a cough for three days, and I feel tired.","sayEs":"Tengo dolor de garganta y tos desde hace tres días, y me siento cansado.","tag":"describe","q":2,"why":"You named two symptoms, said how long, and added how you feel. That is a complete description.","whyEs":"Nombraste dos síntomas, dijiste desde cuándo y agregaste cómo te sientes. Es una descripción completa.","next":"n2"},{"id":"b","say":"Throat hurt and cough. Three days.","sayEs":"Me duele la garganta y tengo tos. Tres días.","tag":"describe","q":1,"why":"The doctor understands the main idea. Use full sentences: 'My throat hurts and I have a cough.'","whyEs":"El doctor entiende la idea principal. Usa oraciones completas: 'My throat hurts and I have a cough'.","next":"r1"},{"id":"c","say":"Nothing. My mom made me come here.","sayEs":"Nada. Mi mamá me obligó a venir.","tag":"describe","q":0,"why":"This gives no symptoms. The doctor needs facts about how you feel to help you.","whyEs":"No da síntomas. El doctor necesita datos sobre cómo te sientes para ayudarte.","next":"r1"}]},"n2":{"who":"npc","say":"That sounds uncomfortable. Does the cough get worse at night, and do you have a fever?","sayEs":"Eso suena incómodo. ¿La tos empeora por la noche y tienes fiebre?","mood":"concerned","choices":[{"id":"a","say":"Sometimes cough at night. No fever, I think.","sayEs":"A veces tengo tos de noche. Fiebre no, creo.","tag":"describe","q":1,"why":"Your meaning is clear. Try 'I sometimes cough at night, and I do not think I have a fever.'","whyEs":"Tu significado es claro. Prueba 'I sometimes cough at night, and I do not think I have a fever'.","next":"n3"},{"id":"b","say":"The cough is worse at night, and I woke up twice. I do not think I have a fever.","sayEs":"La tos empeora de noche y me desperté dos veces. No creo tener fiebre.","tag":"describe","q":2,"why":"You answered both questions with details and used 'I do not think' to show you are not sure.","whyEs":"Respondiste ambas preguntas con detalles y usaste 'I do not think' para mostrar que no estás seguro.","next":"n3"},{"id":"c","say":"I do not know. Why do you ask so many questions?","sayEs":"No sé. ¿Por qué hace tantas preguntas?","tag":"describe","q":0,"why":"The doctor asks questions to help you. Complaining blocks the help. Answer with what you notice.","whyEs":"El doctor pregunta para ayudarte. Quejarte bloquea la ayuda. Responde con lo que notas.","next":"r2"}]},"r1":{"who":"npc","say":"I want to help, but I need more details. When did it start, and where does it hurt?","sayEs":"Quiero ayudarte, pero necesito más detalles. ¿Cuándo empezó y dónde te duele?","mood":"puzzled","choices":[{"id":"a","say":"It is somewhere in my body.","sayEs":"Está en algún lugar de mi cuerpo.","tag":"describe","q":0,"why":"This is too vague to help. Name a body part and say when it began.","whyEs":"Es demasiado vago para ayudar. Nombra una parte del cuerpo y di cuándo empezó.","next":"r2"},{"id":"b","say":"It started on Monday. My throat hurts when I swallow, and I cough a lot at night.","sayEs":"Empezó el lunes. Me duele la garganta al tragar y toso mucho de noche.","tag":"describe","q":2,"why":"You gave the start day, the place, and when it hurts. 'When I swallow' is a useful detail.","whyEs":"Diste el día de inicio, el lugar y cuándo duele. 'When I swallow' es un detalle útil.","next":"n3"},{"id":"c","say":"Monday. Throat hurt. Cough.","sayEs":"El lunes. Garganta duele. Tos.","tag":"describe","q":1,"why":"Good facts, but the sentences are short. Add verbs: 'It started Monday. My throat hurts.'","whyEs":"Buenos datos, pero las oraciones son cortas. Agrega verbos: 'It started Monday. My throat hurts'.","next":"n3"}]},"n3":{"who":"npc","say":"Thank you. It looks like a throat infection, so I will prescribe an antibiotic. Do you have any questions?","sayEs":"Gracias. Parece una infección de garganta, así que te recetaré un antibiótico. ¿Tienes preguntas?","mood":"neutral","choices":[{"id":"a","say":"What medicine for? It is good?","sayEs":"¿Medicina para qué? ¿Es buena?","tag":"question","q":1,"why":"You asked, which is great. Use full questions: 'What is the medicine for? Is it safe?'","whyEs":"Preguntaste, lo cual es excelente. Usa preguntas completas: 'What is the medicine for? Is it safe?'","next":"n4"},{"id":"b","say":"Medicine is gross. I will not take it.","sayEs":"La medicina es asquerosa. No la voy a tomar.","tag":"question","q":0,"why":"Refusing without asking skips important information. A question would help you understand why it matters.","whyEs":"Negarte sin preguntar omite información importante. Una pregunta te ayudaría a entender por qué importa.","next":"r2"},{"id":"c","say":"Yes, what is the medicine for, and how long will it take to work?","sayEs":"Sí, ¿para qué sirve la medicina y cuánto tardará en hacer efecto?","tag":"question","q":2,"why":"You used two wh- questions in one sentence. They ask about purpose and time, which are useful facts.","whyEs":"Usaste dos preguntas con wh- en una oración. Preguntan por el propósito y el tiempo, datos útiles.","next":"n4"}]},"r2":{"who":"npc","say":"Let me explain more simply. The medicine fights the germs that cause the sore throat. Is that clear?","sayEs":"Déjame explicarlo más simple. La medicina combate los gérmenes que causan el dolor de garganta. ¿Está claro?","mood":"concerned","choices":[{"id":"a","say":"Sorry, what means germs?","sayEs":"Perdón, ¿qué significa gérmenes?","tag":"clarify","q":1,"why":"Asking about a word is good. The correct form is 'What does germs mean?' or 'What are germs?'","whyEs":"Preguntar por una palabra es bueno. La forma correcta es 'What are germs?'","next":"n4"},{"id":"b","say":"Yes, fine. Can we go now?","sayEs":"Sí, bien. ¿Ya podemos irnos?","tag":"clarify","q":0,"why":"Saying yes to rush the visit can cause mistakes with medicine. Ask if anything is unclear.","whyEs":"Decir que sí para apurar la visita puede causar errores con la medicina. Pregunta si algo no está claro.","next":"e3"},{"id":"c","say":"Yes, that helps. Could you repeat how often I should take it?","sayEs":"Sí, eso ayuda. ¿Podría repetir cada cuánto debo tomarla?","tag":"clarify","q":2,"why":"You confirmed you understood and politely asked for a repeat with 'Could you.' That keeps the visit safe.","whyEs":"Confirmaste que entendiste y pediste con cortesía que repita usando 'Could you'. Eso hace la visita más segura.","next":"n4"}]},"n4":{"who":"npc","say":"The medicine fights the germs that cause the infection. Take it twice a day for seven days, even if you feel better. Does that make sense?","sayEs":"La medicina combate los gérmenes que causan la infección. Tómala dos veces al día durante siete días, aunque te sientas mejor. ¿Tiene sentido?","mood":"pleased","choices":[{"id":"a","say":"Yes. Twice a day. Seven days. Okay.","sayEs":"Sí. Dos veces al día. Siete días. Está bien.","tag":"clarify","q":1,"why":"You repeated the key facts, which helps. Checking with 'right?' would make sure you are correct.","whyEs":"Repetiste los datos clave, lo cual ayuda. Confirmar con 'right?' aseguraría que estás en lo correcto.","next":"e2"},{"id":"b","say":"Seven days is too long. I will take it for two days.","sayEs":"Siete días es demasiado. La tomaré solo dos días.","tag":"clarify","q":0,"why":"Changing the plan without asking is unsafe. Say 'Why do I need seven days?' to learn the reason.","whyEs":"Cambiar el plan sin preguntar no es seguro. Di 'Why do I need seven days?' para saber la razón.","next":"e3"},{"id":"c","say":"Let me check: I take it twice a day for seven days, even when I feel better, right?","sayEs":"Déjeme confirmar: la tomo dos veces al día durante siete días, aunque me sienta mejor, ¿verdad?","tag":"clarify","q":2,"why":"'Let me check' and 'right?' confirm the plan in your own words. That shows understanding.","whyEs":"'Let me check' y 'right?' confirman el plan con tus palabras. Eso muestra comprensión.","next":"e1"}]},"e1":{"who":"npc","say":"Exactly right. You explained it well. Rest, drink water, and come back if you feel worse.","sayEs":"Exacto. Lo explicaste muy bien. Descansa, toma agua y vuelve si te sientes peor.","mood":"happy","end":true,"outcome":"strong","wrap":"You described your symptoms, asked what the medicine is for, and repeated the plan to check it. Clear language kept you safe.","wrapEs":"Describiste tus síntomas, preguntaste para qué sirve la medicina y repetiste el plan para confirmarlo. El lenguaje claro te mantuvo seguro."},"e2":{"who":"npc","say":"Good. Ask the nurse if you forget anything. Feel better soon.","sayEs":"Bien. Pregunta a la enfermera si olvidas algo. Que te mejores pronto.","mood":"neutral","end":true,"outcome":"ok","wrap":"You got the main instructions. Describing symptoms in detail and confirming with a full sentence is even safer.","wrapEs":"Entendiste las indicaciones principales. Describir los síntomas con detalle y confirmar con una oración completa es aún más seguro."},"e3":{"who":"npc","say":"I am worried we missed something. Let us go over it again so the medicine works.","sayEs":"Me preocupa que hayamos pasado algo por alto. Repasémoslo para que la medicina funcione.","mood":"concerned","end":true,"outcome":"retry","wrap":"The visit ended before the plan was clear. Take medicine exactly as directed, and ask questions when something seems wrong.","wrapEs":"La visita terminó antes de que el plan estuviera claro. Toma la medicina exactamente como se indica y haz preguntas si algo no te parece bien."}}},
  {"id":"c68-pharmacy-medicine","b":"6-8","title":"At the pharmacy","titleEs":"En la farmacia","place":"pharmacy","goal":"Ask how to take a medicine and ask the pharmacist to repeat or go slowly.","goalEs":"Preguntar cómo tomar una medicina y pedir a la farmacéutica que repita o hable más despacio.","focus":["question","clarify","thank"],"npc":{"name":"Ms. Brooks","role":"pharmacist","roleEs":"farmacéutica","look":{"skin":"#8d5524","hair":"#2b1b12","style":"afro","shirt":"#6b4c9a","acc":"glasses"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"Hi, your antibiotic is ready. Do you have any questions about it?","sayEs":"Hola, tu antibiótico está listo. ¿Tienes alguna pregunta sobre él?","mood":"neutral","choices":[{"id":"a","say":"How I take it?","sayEs":"¿Cómo la tomo?","tag":"question","q":1,"why":"Good idea to ask! The question form is 'How do I take it?'","whyEs":"¡Buena idea preguntar! La forma de la pregunta es 'How do I take it?'","next":"r1"},{"id":"b","say":"Yes, how should I take this medicine, and should I take it with food?","sayEs":"Sí, ¿cómo debo tomar esta medicina y debo tomarla con comida?","tag":"question","q":2,"why":"You used 'should' in two clear questions about method and food. These are important safety questions.","whyEs":"Usaste 'should' en dos preguntas claras sobre el modo y la comida. Son preguntas de seguridad importantes.","next":"n2"},{"id":"c","say":"No. Just give it to me.","sayEs":"No. Solo démela.","tag":"question","q":0,"why":"Skipping questions about medicine can be unsafe, and 'Just give it to me' sounds rude.","whyEs":"Omitir preguntas sobre la medicina puede ser peligroso, y 'Just give it to me' suena grosero.","next":"r1"}]},"n2":{"who":"npc","say":"Take one tablet in the morning and one at night, after you eat. Drink a full glass of water.","sayEs":"Toma una tableta por la mañana y otra por la noche, después de comer. Bebe un vaso lleno de agua.","mood":"neutral","choices":[{"id":"a","say":"You talk too fast. I cannot understand you.","sayEs":"Usted habla muy rápido. No la entiendo.","tag":"clarify","q":0,"why":"This blames her. You can ask politely: 'Could you speak more slowly, please?'","whyEs":"Esto la culpa a ella. Puedes pedir con cortesía: 'Could you speak more slowly, please?'","next":"r2"},{"id":"b","say":"Again, please. Slowly.","sayEs":"Otra vez, por favor. Despacio.","tag":"clarify","q":1,"why":"You asked for a repeat and said please. Try 'Could you repeat that slowly?'","whyEs":"Pediste que lo repita y dijiste please. Prueba 'Could you repeat that slowly?'","next":"n3"},{"id":"c","say":"I am sorry, you spoke quickly. Could you please repeat that more slowly?","sayEs":"Disculpe, habló rápido. ¿Podría repetirlo más despacio, por favor?","tag":"clarify","q":2,"why":"You said sorry, explained the problem, and asked politely with 'Could you please.' That gets better help.","whyEs":"Dijiste sorry, explicaste el problema y pediste con 'Could you please'. Así recibes mejor ayuda.","next":"n3"}]},"r1":{"who":"npc","say":"I am sorry, I did not catch your question. What would you like to know about the medicine?","sayEs":"Disculpa, no entendí tu pregunta. ¿Qué te gustaría saber sobre la medicina?","mood":"puzzled","choices":[{"id":"a","say":"How many times? Days?","sayEs":"¿Cuántas veces? ¿Días?","tag":"question","q":1,"why":"Your idea is clear. A full question is better: 'How many times a day, and for how many days?'","whyEs":"Tu idea es clara. Una pregunta completa es mejor: 'How many times a day, and for how many days?'","next":"n2"},{"id":"b","say":"Never mind. I will read the box.","sayEs":"Olvídelo. Leeré la caja.","tag":"question","q":0,"why":"Reading helps, but the pharmacist can answer your exact questions. Ask before you leave.","whyEs":"Leer ayuda, pero la farmacéutica puede responder tus preguntas exactas. Pregunta antes de irte.","next":"r2"},{"id":"c","say":"I would like to know how often I should take it, and for how many days.","sayEs":"Me gustaría saber con qué frecuencia debo tomarla y por cuántos días.","tag":"question","q":2,"why":"'I would like to know' politely introduces your questions, and 'how often' and 'how many days' are exact.","whyEs":"'I would like to know' introduce tus preguntas con cortesía, y 'how often' y 'how many days' son precisas.","next":"n2"}]},"n3":{"who":"npc","say":"Of course. One tablet in the morning, one at night, after meals. Would you like me to write that on the bag?","sayEs":"Claro. Una tableta por la mañana y otra por la noche, después de las comidas. ¿Quieres que lo escriba en la bolsa?","mood":"pleased","choices":[{"id":"a","say":"Yes. Write, please.","sayEs":"Sí. Escríbalo, por favor.","tag":"accept","q":1,"why":"You accepted politely. A full sentence like 'Yes, please write it down' sounds clearer.","whyEs":"Aceptaste con cortesía. Una oración completa como 'Yes, please write it down' suena más clara.","next":"n4"},{"id":"b","say":"No. I will remember it. Bye.","sayEs":"No. Lo recordaré. Adiós.","tag":"accept","q":0,"why":"Medicine directions are easy to forget. Accepting the written note keeps you safe.","whyEs":"Las indicaciones de una medicina se olvidan fácil. Aceptar la nota escrita te mantiene seguro.","next":"r2"},{"id":"c","say":"Yes, please. That would help me show my parents. Thank you for being patient.","sayEs":"Sí, por favor. Eso me ayudaría a mostrárselo a mis padres. Gracias por tener paciencia.","tag":"accept","q":2,"why":"You accepted the offer, gave a reason with 'help me', and thanked her for being patient.","whyEs":"Aceptaste la oferta, diste una razón con 'help me' y le agradeciste su paciencia.","next":"n4"}]},"r2":{"who":"npc","say":"I want to make sure you can use this safely. Should I go over it one more time?","sayEs":"Quiero asegurarme de que puedas usarla con seguridad. ¿La repaso una vez más?","mood":"concerned","choices":[{"id":"a","say":"Yes. One more time.","sayEs":"Sí. Una vez más.","tag":"clarify","q":1,"why":"You asked for a repeat, which is good. Add 'please' and 'slowly' to be more polite and clear.","whyEs":"Pediste que se repita, y eso está bien. Agrega 'please' y 'slowly' para ser más cortés y claro.","next":"n4"},{"id":"b","say":"Yes, please. Could you go through it slowly, and could you write it down for me?","sayEs":"Sí, por favor. ¿Podría repasarlo despacio y escribirlo para mí?","tag":"clarify","q":2,"why":"You used 'Could you' twice to ask for slow speech and a written note. Both requests are polite.","whyEs":"Usaste 'Could you' dos veces para pedir que hable despacio y una nota escrita. Ambas peticiones son corteses.","next":"n4"},{"id":"c","say":"No. I am in a hurry.","sayEs":"No. Tengo prisa.","tag":"clarify","q":0,"why":"Rushing can lead to mistakes with medicine. You can say 'Please be quick, but go slowly on the dose.'","whyEs":"Apurarte puede causar errores con la medicina. Puedes decir 'Please be quick, but go slowly on the dose'.","next":"e3"}]},"n4":{"who":"npc","say":"Here is the written schedule. Call us if you feel dizzy or sick. Is everything clear now?","sayEs":"Aquí está el horario escrito. Llámanos si te sientes mareado o enfermo. ¿Todo está claro ahora?","mood":"neutral","choices":[{"id":"a","say":"Yes. This took a long time.","sayEs":"Sí. Esto tardó mucho.","tag":"thank","q":0,"why":"Complaining about the time is unkind. She was helping you stay safe.","whyEs":"Quejarte del tiempo no es amable. Ella te ayudaba a estar seguro.","next":"e3"},{"id":"b","say":"Yes. Thanks.","sayEs":"Sí. Gracias.","tag":"thank","q":1,"why":"'Thanks' is polite. Add what you are thanking her for: 'Thanks for repeating it.'","whyEs":"'Thanks' es cortés. Agrega por qué agradeces: 'Thanks for repeating it'.","next":"e2"},{"id":"c","say":"Yes, now I understand. Thank you for repeating it so patiently. Have a good day!","sayEs":"Sí, ahora entiendo. Gracias por repetirlo con tanta paciencia. ¡Que tenga un buen día!","tag":"thank","q":2,"why":"You confirmed understanding, named what you are thankful for, and ended with a kind wish.","whyEs":"Confirmaste que entendiste, dijiste por qué agradeces y terminaste con un buen deseo.","next":"e1"}]},"e1":{"who":"npc","say":"You are very welcome. You asked great questions. Feel better soon!","sayEs":"De nada. Hiciste muy buenas preguntas. ¡Que te mejores pronto!","mood":"happy","end":true,"outcome":"strong","wrap":"You asked clear questions, asked her to slow down politely, and said thank you. Now you know exactly how to take the medicine.","wrapEs":"Hiciste preguntas claras, le pediste con cortesía que fuera más despacio y diste las gracias. Ahora sabes exactamente cómo tomar la medicina."},"e2":{"who":"npc","say":"Okay. Please call if you have any problems.","sayEs":"Muy bien. Por favor, llama si tienes algún problema.","mood":"neutral","end":true,"outcome":"ok","wrap":"You got the information, but full questions and a specific thank you would show more confidence and respect.","wrapEs":"Obtuviste la información, pero preguntas completas y un agradecimiento específico mostrarían más confianza y respeto."},"e3":{"who":"npc","say":"I am concerned. Let us review the schedule once more before you go.","sayEs":"Me preocupa. Repasemos el horario una vez más antes de que te vayas.","mood":"concerned","end":true,"outcome":"retry","wrap":"The pharmacist could not finish explaining safely. Ask questions, request a slower repeat politely, and listen to the directions.","wrapEs":"La farmacéutica no pudo terminar de explicar con seguridad. Haz preguntas, pide con cortesía que repita más despacio y escucha las indicaciones."}}},
  {"id":"c68-store-return","b":"6-8","title":"Returning an item","titleEs":"Devolver un artículo","place":"store","goal":"Return a broken backpack with your receipt and explain the problem politely.","goalEs":"Devolver una mochila rota con tu recibo y explicar el problema con cortesía.","focus":["explain","request","disagree"],"npc":{"name":"Mr. Torres","role":"store clerk","roleEs":"empleado de la tienda","look":{"skin":"#e0ac84","hair":"#3b2a1e","style":"short","shirt":"#2b6f8f","acc":"none"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"Hello. How can I help you today?","sayEs":"Hola. ¿En qué puedo ayudarte hoy?","mood":"neutral","choices":[{"id":"a","say":"I want return this bag. Zipper broken.","sayEs":"Quiero devolver esta mochila. El cierre está roto.","tag":"explain","q":1,"why":"The clerk understands the problem. Use full sentences: 'I would like to return this bag. The zipper is broken.'","whyEs":"El empleado entiende el problema. Usa oraciones completas: 'I would like to return this bag. The zipper is broken'.","next":"r1"},{"id":"b","say":"This bag is garbage. Give me my money back!","sayEs":"Esta mochila es basura. ¡Devuélvame mi dinero!","tag":"explain","q":0,"why":"Shouting and demanding makes the clerk defensive. Explain the problem calmly and ask politely.","whyEs":"Gritar y exigir pone a la defensiva al empleado. Explica el problema con calma y pide con cortesía.","next":"r1"},{"id":"c","say":"Hello. I bought this backpack last week, but the zipper broke. I have my receipt here.","sayEs":"Hola. Compré esta mochila la semana pasada, pero el cierre se rompió. Aquí tengo mi recibo.","tag":"explain","q":2,"why":"You gave the item, the time, the problem, and proof. 'But' links the purchase to the problem clearly.","whyEs":"Diste el artículo, el tiempo, el problema y la prueba. 'But' une la compra con el problema con claridad.","next":"n2"}]},"n2":{"who":"npc","say":"Let me see. I see the receipt, but our policy only allows a refund within seven days. Today is day eight.","sayEs":"Veamos. Veo el recibo, pero nuestra política solo permite reembolso dentro de siete días. Hoy es el día ocho.","mood":"concerned","choices":[{"id":"a","say":"That rule is unfair. I want to talk to your boss!","sayEs":"Esa regla es injusta. ¡Quiero hablar con su jefe!","tag":"disagree","q":0,"why":"Calling the rule unfair and demanding a boss is aggressive. Disagree politely and suggest another option.","whyEs":"Decir que la regla es injusta y exigir al jefe es agresivo. Muestra desacuerdo con cortesía y sugiere otra opción.","next":"r2"},{"id":"b","say":"I see your point, but the zipper broke after two days. Could you make an exception, please?","sayEs":"Entiendo su punto, pero el cierre se rompió a los dos días. ¿Podría hacer una excepción, por favor?","tag":"disagree","q":2,"why":"'I see your point, but' disagrees politely, and 'Could you... please' asks for help with a reason.","whyEs":"'I see your point, but' expresa desacuerdo con cortesía, y 'Could you... please' pide ayuda con una razón.","next":"n3"},{"id":"c","say":"But it broke fast. Please help me.","sayEs":"Pero se rompió rápido. Por favor, ayúdeme.","tag":"disagree","q":1,"why":"'But' shows you disagree and 'please' is polite. Give a clear reason like 'It broke after two days.'","whyEs":"'But' muestra desacuerdo y 'please' es cortés. Da una razón clara como 'It broke after two days'.","next":"n3"}]},"r1":{"who":"npc","say":"I am sorry, I am not sure what the problem is. Can you tell me what happened and when you bought it?","sayEs":"Disculpa, no estoy seguro de cuál es el problema. ¿Puedes decirme qué pasó y cuándo la compraste?","mood":"puzzled","choices":[{"id":"a","say":"Bag broke. I buy last week.","sayEs":"La mochila se rompió. La compré la semana pasada.","tag":"explain","q":1,"why":"The facts are clear. Use past tense: 'The bag broke. I bought it last week.'","whyEs":"Los datos son claros. Usa el pasado: 'The bag broke. I bought it last week'.","next":"n2"},{"id":"b","say":"I am sorry for being upset. I bought this backpack last week, and the zipper broke.","sayEs":"Lamento haberme molestado. Compré esta mochila la semana pasada y el cierre se rompió.","tag":"apologize","q":2,"why":"You apologized for your tone and then explained clearly. That calms the talk and gives the facts.","whyEs":"Te disculpaste por tu tono y luego explicaste con claridad. Eso calma la conversación y da los datos.","next":"n2"},{"id":"c","say":"I do not remember. Just fix it.","sayEs":"No recuerdo. Solo arréglelo.","tag":"explain","q":0,"why":"Without details the clerk cannot help, and 'Just fix it' is a command. Share what you remember.","whyEs":"Sin detalles el empleado no puede ayudar, y 'Just fix it' es una orden. Cuenta lo que recuerdas.","next":"r2"}]},"n3":{"who":"npc","say":"Okay. I cannot give a refund, but I can offer store credit or exchange it for a new backpack. Which do you prefer?","sayEs":"Está bien. No puedo dar un reembolso, pero puedo ofrecer crédito de tienda o cambiarla por una mochila nueva. ¿Cuál prefieres?","mood":"neutral","choices":[{"id":"a","say":"Give me anything. I do not care.","sayEs":"Deme lo que sea. No me importa.","tag":"request","q":0,"why":"This does not answer the clerk, and it sounds careless. Choose one option and ask politely.","whyEs":"No responde al empleado y suena descuidado. Elige una opción y pide con cortesía.","next":"r2"},{"id":"b","say":"Exchange. New one please.","sayEs":"Cambio. Una nueva, por favor.","tag":"request","q":1,"why":"Your choice is clear and polite. A full sentence works better: 'I would like to exchange it.'","whyEs":"Tu elección es clara y cortés. Una oración completa funciona mejor: 'I would like to exchange it'.","next":"n4"},{"id":"c","say":"Could I exchange it for a new backpack, please? That would work well for me.","sayEs":"¿Podría cambiarla por una mochila nueva, por favor? Eso me serviría bien.","tag":"request","q":2,"why":"'Could I... please' is a polite request, and the reason after it shows why your choice fits.","whyEs":"'Could I... please' es una petición cortés, y la razón que sigue muestra por qué tu elección te conviene.","next":"n4"}]},"r2":{"who":"npc","say":"Let us try again. I can offer an exchange or store credit. Which would you like?","sayEs":"Intentémoslo otra vez. Puedo ofrecer un cambio o crédito de tienda. ¿Cuál prefieres?","mood":"concerned","choices":[{"id":"a","say":"I am sorry for the confusion. Could I please exchange it for a new backpack?","sayEs":"Disculpe la confusión. ¿Podría cambiarla por una mochila nueva, por favor?","tag":"request","q":2,"why":"You apologized for the confusion and made a clear, polite request. That restarts the talk well.","whyEs":"Te disculpaste por la confusión e hiciste una petición clara y cortés. Eso reinicia bien la conversación.","next":"n4"},{"id":"b","say":"Exchange. New bag.","sayEs":"Cambio. Mochila nueva.","tag":"request","q":1,"why":"The choice is clear, but it sounds like a command. Add 'please' or 'Could I...?'","whyEs":"La elección es clara, pero suena como una orden. Agrega 'please' o 'Could I...?'","next":"n4"},{"id":"c","say":"Forget it. I will keep the broken one.","sayEs":"Olvídelo. Me quedo con la rota.","tag":"request","q":0,"why":"Giving up ends the chance to solve it. Choose an option and say it politely.","whyEs":"Rendirte termina la posibilidad de resolverlo. Elige una opción y dila con cortesía.","next":"e3"}]},"n4":{"who":"npc","say":"Great. Here is your new backpack. Please check that the zipper works before you leave.","sayEs":"Muy bien. Aquí está tu mochila nueva. Por favor, revisa que el cierre funcione antes de irte.","mood":"pleased","choices":[{"id":"a","say":"OK. Thanks.","sayEs":"Está bien. Gracias.","tag":"thank","q":1,"why":"'Thanks' is polite. Add what you are thanking him for: 'Thanks for the exchange.'","whyEs":"'Thanks' es cortés. Agrega por qué le agradeces: 'Thanks for the exchange'.","next":"e2"},{"id":"b","say":"It better work this time.","sayEs":"Más le vale que funcione esta vez.","tag":"thank","q":0,"why":"This sounds like a threat. Check the zipper and thank him for the help.","whyEs":"Suena como una amenaza. Revisa el cierre y dale las gracias por su ayuda.","next":"e3"},{"id":"c","say":"It works well. Thank you for helping me with the exchange.","sayEs":"Funciona bien. Gracias por ayudarme con el cambio.","tag":"thank","q":2,"why":"You checked the item and thanked him for the specific help. That ends the visit on a positive note.","whyEs":"Revisaste el artículo y le agradeciste su ayuda específica. Eso cierra la visita de forma positiva.","next":"e1"}]},"e1":{"who":"npc","say":"I am glad we could solve it. Have a great day!","sayEs":"Me alegra que pudimos resolverlo. ¡Que tengas un gran día!","mood":"happy","end":true,"outcome":"strong","wrap":"You explained the problem, disagreed politely, and made a clear request. Respectful language helped the clerk find a solution.","wrapEs":"Explicaste el problema, mostraste desacuerdo con cortesía e hiciste una petición clara. El lenguaje respetuoso ayudó al empleado a encontrar una solución."},"e2":{"who":"npc","say":"Okay. Your exchange is complete.","sayEs":"Muy bien. Tu cambio está completo.","mood":"neutral","end":true,"outcome":"ok","wrap":"You solved the problem, but fuller sentences and a specific thank you would sound more polite and confident.","wrapEs":"Resolviste el problema, pero oraciones más completas y un agradecimiento específico sonarían más corteses y seguros."},"e3":{"who":"npc","say":"I am sorry I could not help more. If you want, we can talk again calmly.","sayEs":"Lamento no haber podido ayudar más. Si quieres, podemos hablar de nuevo con calma.","mood":"concerned","end":true,"outcome":"retry","wrap":"The talk ended without a solution. Explain calmly, disagree with 'I see your point, but', and ask with 'Could I...?'","wrapEs":"La conversación terminó sin solución. Explica con calma, muestra desacuerdo con 'I see your point, but' y pide con 'Could I...?'"}}},
  {"id":"c68-phone-favor","b":"6-8","title":"Asking a family friend for a favor","titleEs":"Pedir un favor a un amigo de la familia","place":"phone","goal":"Phone a family friend, ask him to read your essay, offer something in return, and close the call politely.","goalEs":"Llamar a un amigo de la familia, pedirle que lea tu ensayo, ofrecer algo a cambio y cerrar la llamada con cortesía.","focus":["greet","request","thank"],"npc":{"name":"Mr. Asante","role":"family friend","roleEs":"amigo de la familia","look":{"skin":"#5c3a21","hair":"#111111","style":"short","shirt":"#a0522d","acc":"glasses"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"Hello, Asante residence.","sayEs":"Hola, residencia Asante.","mood":"neutral","choices":[{"id":"a","say":"Good afternoon, Mr. Asante. This is Noor Ahmed. I hope I am not calling at a bad time.","sayEs":"Buenas tardes, señor Asante. Habla Noor Ahmed. Espero no llamar en un mal momento.","tag":"greet","q":2,"why":"You greeted him, gave your full name, and checked if the time was good. That is a polite phone opening.","whyEs":"Lo saludaste, diste tu nombre completo y preguntaste si era buen momento. Es una apertura telefónica cortés.","next":"n2"},{"id":"b","say":"Hello. I am Noor. I need help.","sayEs":"Hola. Soy Noor. Necesito ayuda.","tag":"greet","q":1,"why":"He knows who you are, but a polite opening such as 'How are you?' would sound warmer.","whyEs":"Él sabe quién eres, pero una apertura cortés como 'How are you?' sonaría más cálida.","next":"r1"},{"id":"c","say":"Hey. I need something. Are you busy?","sayEs":"Oye. Necesito algo. ¿Está ocupado?","tag":"greet","q":0,"why":"'Hey' and a quick demand sound too casual for an adult. Greet him first and say who you are.","whyEs":"'Hey' y una petición rápida suenan demasiado informales con un adulto. Salúdalo primero y di quién eres.","next":"r1"}]},"n2":{"who":"npc","say":"Hello, Noor! It is a good time. What can I do for you?","sayEs":"¡Hola, Noor! Es buen momento. ¿En qué te puedo ayudar?","mood":"happy","choices":[{"id":"a","say":"I wrote an essay. Can you read it?","sayEs":"Escribí un ensayo. ¿Puede leerlo?","tag":"request","q":1,"why":"The request is clear. 'Would you be willing to...' sounds more polite and explains your purpose.","whyEs":"La petición es clara. 'Would you be willing to...' suena más cortés y explica tu propósito.","next":"n3"},{"id":"b","say":"You are good at writing. Fix my essay for me.","sayEs":"Usted escribe bien. Corrija mi ensayo por mí.","tag":"request","q":0,"why":"This is a command, and it asks him to do your work. Ask politely for feedback instead.","whyEs":"Es una orden y le pide que haga tu trabajo. Pide comentarios con cortesía.","next":"r2"},{"id":"c","say":"I wrote an essay for English class. Would you be willing to read it and give me feedback?","sayEs":"Escribí un ensayo para la clase de inglés. ¿Estaría dispuesto a leerlo y darme sus comentarios?","tag":"request","q":2,"why":"'Would you be willing to' is a polite request, and you named the purpose clearly: feedback.","whyEs":"'Would you be willing to' es una petición cortés, y nombraste claramente el propósito: comentarios.","next":"n3"}]},"r1":{"who":"npc","say":"Hello, Noor. I did not quite follow. What do you need help with?","sayEs":"Hola, Noor. No te entendí bien. ¿Con qué necesitas ayuda?","mood":"puzzled","choices":[{"id":"a","say":"I am sorry for being unclear. I wrote an English essay. Could you please read it and give me feedback?","sayEs":"Disculpe por no ser claro. Escribí un ensayo de inglés. ¿Podría leerlo y darme sus comentarios, por favor?","tag":"apologize","q":2,"why":"You apologized for the confusion, then made a clear, polite request with 'Could you please.'","whyEs":"Te disculpaste por la confusión y luego hiciste una petición clara y cortés con 'Could you please'.","next":"n3"},{"id":"b","say":"Never mind. It is not important.","sayEs":"No importa. No es importante.","tag":"request","q":0,"why":"Giving up leaves him confused. Say what you need, even if you are nervous.","whyEs":"Rendirte lo deja confundido. Di qué necesitas, aunque estés nervioso.","next":"r2"},{"id":"c","say":"Essay English. You read, please?","sayEs":"Ensayo de inglés. ¿Usted lee, por favor?","tag":"request","q":1,"why":"Good use of 'please.' Use a full sentence: 'Could you read my English essay, please?'","whyEs":"Buen uso de 'please'. Usa una oración completa: 'Could you read my English essay, please?'","next":"n3"}]},"n3":{"who":"npc","say":"I would be glad to help. It might take me until Sunday, though. Would that work?","sayEs":"Con gusto te ayudo. Aunque quizás me tome hasta el domingo. ¿Te serviría?","mood":"pleased","choices":[{"id":"a","say":"Sunday is too late. Do it faster.","sayEs":"El domingo es muy tarde. Hágalo más rápido.","tag":"offer","q":0,"why":"He is doing you a favor. Ordering him to hurry is rude. Say Sunday works or ask kindly.","whyEs":"Él te hace un favor. Ordenarle que se apure es grosero. Di que el domingo sirve o pregunta con amabilidad.","next":"r2"},{"id":"b","say":"Sunday works well. To thank you, I could walk your dog or help in your garden.","sayEs":"El domingo me sirve. Para agradecerle, podría pasear a su perro o ayudar en su jardín.","tag":"offer","q":2,"why":"'I could...' offers help in return. It shows gratitude and respect for his time.","whyEs":"'I could...' ofrece ayuda a cambio. Muestra gratitud y respeto por su tiempo.","next":"n4"},{"id":"c","say":"Sunday okay. I help you something.","sayEs":"El domingo está bien. Le ayudo con algo.","tag":"offer","q":1,"why":"Your idea of helping back is kind. Say 'I can help you with something' to be clear.","whyEs":"Tu idea de ayudar a cambio es amable. Di 'I can help you with something' para ser claro.","next":"n4"}]},"r2":{"who":"npc","say":"Hmm. I want to help, but I am not sure what you want. Do you still want me to read your essay?","sayEs":"Mmm. Quiero ayudarte, pero no estoy seguro de lo que quieres. ¿Todavía quieres que lea tu ensayo?","mood":"concerned","choices":[{"id":"a","say":"Yes. Read it. Thanks.","sayEs":"Sí. Léalo. Gracias.","tag":"request","q":1,"why":"The answer is clear and thankful. Adding 'please' and 'I would appreciate it' sounds more polite.","whyEs":"La respuesta es clara y agradecida. Agregar 'please' y 'I would appreciate it' suena más cortés.","next":"n4"},{"id":"b","say":"Yes, please. I am sorry I sounded rushed. I would really appreciate your feedback.","sayEs":"Sí, por favor. Disculpe si sonaba apurado. Le agradecería mucho sus comentarios.","tag":"apologize","q":2,"why":"You apologized for your tone, answered yes, and used 'I would appreciate' to sound respectful.","whyEs":"Te disculpaste por tu tono, respondiste que sí y usaste 'I would appreciate' para sonar respetuoso.","next":"n4"},{"id":"c","say":"I do not know. Maybe. Whatever.","sayEs":"No sé. Quizás. Lo que sea.","tag":"request","q":0,"why":"This does not answer him. If you need help, say yes clearly and ask politely.","whyEs":"No le responde. Si necesitas ayuda, di que sí con claridad y pide con cortesía.","next":"e3"}]},"n4":{"who":"npc","say":"Wonderful. Send it to me tonight, and I will call you on Sunday with my comments.","sayEs":"Perfecto. Envíamelo esta noche y te llamo el domingo con mis comentarios.","mood":"happy","choices":[{"id":"a","say":"Thank you very much, Mr. Asante. I will send it tonight. Have a good evening, and goodbye.","sayEs":"Muchas gracias, señor Asante. Se lo envío esta noche. Que tenga una buena noche y adiós.","tag":"thank","q":2,"why":"You thanked him by name, confirmed the plan, and closed with a kind wish. That is a polite phone closing.","whyEs":"Le agradeciste por su nombre, confirmaste el plan y cerraste con un buen deseo. Es un cierre telefónico cortés.","next":"e1"},{"id":"b","say":"Fine. Do not forget.","sayEs":"Bueno. No se olvide.","tag":"thank","q":0,"why":"This sounds like an order to someone helping you. Thank him and say goodbye kindly.","whyEs":"Suena como una orden a alguien que te ayuda. Dale las gracias y despídete con amabilidad.","next":"e3"},{"id":"c","say":"Okay. Thanks. Bye.","sayEs":"Está bien. Gracias. Adiós.","tag":"thank","q":1,"why":"Polite but very short. 'Thank you for your help. Have a good evening' sounds warmer.","whyEs":"Cortés pero muy corto. 'Thank you for your help. Have a good evening' suena más cálido.","next":"e2"}]},"e1":{"who":"npc","say":"You are very welcome, Noor. I look forward to reading it. Goodbye!","sayEs":"De nada, Noor. Tengo ganas de leerlo. ¡Adiós!","mood":"happy","end":true,"outcome":"strong","wrap":"You opened politely, made a respectful request, offered help in return, and closed with thanks. That is how to ask for a favor.","wrapEs":"Abriste con cortesía, hiciste una petición respetuosa, ofreciste ayuda a cambio y cerraste con gracias. Así se pide un favor."},"e2":{"who":"npc","say":"Okay, Noor. Talk to you on Sunday. Bye.","sayEs":"Muy bien, Noor. Hablamos el domingo. Adiós.","mood":"neutral","end":true,"outcome":"ok","wrap":"He agreed to help, but a polite opening and closing would make your call warmer and more respectful.","wrapEs":"Aceptó ayudarte, pero una apertura y un cierre corteses harían tu llamada más cálida y respetuosa."},"e3":{"who":"npc","say":"Let us talk again when you are ready. I am happy to help.","sayEs":"Hablemos de nuevo cuando estés listo. Con gusto te ayudo.","mood":"concerned","end":true,"outcome":"retry","wrap":"The call ended with confusion. Greet him, explain the favor with 'Would you be willing to...', and thank him at the end.","wrapEs":"La llamada terminó con confusión. Salúdalo, explica el favor con 'Would you be willing to...' y dale las gracias al final."}}},
  {"id":"c68-street-directions","b":"6-8","title":"Asking for directions","titleEs":"Pedir indicaciones","place":"street","goal":"Ask how to get to the library, check that you understood, and thank the helper.","goalEs":"Preguntar cómo llegar a la biblioteca, confirmar que entendiste y agradecer a quien te ayuda.","focus":["question","clarify","thank"],"npc":{"name":"Ms. Moreno","role":"passerby","roleEs":"transeúnte","look":{"skin":"#e0ac84","hair":"#4a2c17","style":"curly","shirt":"#b5473a","acc":"none"}},"start":"n1","nodes":{"n1":{"who":"npc","say":"Hello! You look a little lost. Can I help you?","sayEs":"¡Hola! Pareces un poco perdido. ¿Puedo ayudarte?","mood":"happy","choices":[{"id":"a","say":"Yeah. Where is the library? I am in a hurry.","sayEs":"Sí. ¿Dónde está la biblioteca? Tengo prisa.","tag":"question","q":0,"why":"The question is clear, but 'I am in a hurry' with no 'please' sounds demanding. Begin with 'Excuse me.'","whyEs":"La pregunta es clara, pero 'I am in a hurry' sin 'please' suena exigente. Empieza con 'Excuse me'.","next":"r1"},{"id":"b","say":"Yes, thank you. Excuse me, could you tell me how to get to the public library?","sayEs":"Sí, gracias. Disculpe, ¿podría decirme cómo llegar a la biblioteca pública?","tag":"question","q":2,"why":"'Excuse me' and 'could you tell me' make a polite indirect question, and you named the place.","whyEs":"'Excuse me' y 'could you tell me' forman una pregunta indirecta cortés, y nombraste el lugar.","next":"n2"},{"id":"c","say":"Where is library? I am lost.","sayEs":"¿Dónde está biblioteca? Estoy perdido.","tag":"question","q":1,"why":"The meaning is clear. Add 'the' and use a polite phrase: 'Where is the library, please?'","whyEs":"El significado es claro. Agrega 'the' y usa una frase cortés: 'Where is the library, please?'","next":"r1"}]},"n2":{"who":"npc","say":"Sure. Walk two blocks down Maple Street, turn left at the bakery, and it is across from the park.","sayEs":"Claro. Camina dos cuadras por la calle Maple, gira a la izquierda en la panadería y está frente al parque.","mood":"neutral","choices":[{"id":"a","say":"Sorry, could you repeat the last part? Did you say turn left at the bakery?","sayEs":"Perdón, ¿podría repetir la última parte? ¿Dijo que gire a la izquierda en la panadería?","tag":"clarify","q":2,"why":"You apologized, asked for a repeat with 'could you', and checked one detail with 'Did you say...?'","whyEs":"Pediste perdón, solicitaste que repita con 'could you' y confirmaste un detalle con 'Did you say...?'","next":"n3"},{"id":"b","say":"Left? Where? Again, please.","sayEs":"¿Izquierda? ¿Dónde? Otra vez, por favor.","tag":"clarify","q":1,"why":"You asked for a repeat politely. Name the part you missed: 'Could you repeat the last part?'","whyEs":"Pediste que repita con cortesía. Nombra la parte que no entendiste: 'Could you repeat the last part?'","next":"n3"},{"id":"c","say":"Too many words. Just point there.","sayEs":"Son demasiadas palabras. Solo señale hacia allá.","tag":"clarify","q":0,"why":"This sounds impatient. Ask her to slow down and repeat one step at a time.","whyEs":"Suena impaciente. Pídele que vaya más despacio y repita un paso a la vez.","next":"r2"}]},"r1":{"who":"npc","say":"I am sorry, I did not understand. Are you looking for a place? Which one?","sayEs":"Disculpa, no entendí. ¿Buscas algún lugar? ¿Cuál?","mood":"puzzled","choices":[{"id":"a","say":"Forget it. I will ask someone else.","sayEs":"Olvídelo. Le preguntaré a otra persona.","tag":"question","q":0,"why":"Leaving ends the help. Repeat your question more slowly instead.","whyEs":"Irte termina la ayuda. Mejor repite tu pregunta más despacio.","next":"r2"},{"id":"b","say":"Sorry, let me ask again. How can I get to the public library from here?","sayEs":"Perdón, preguntaré otra vez. ¿Cómo puedo llegar a la biblioteca pública desde aquí?","tag":"question","q":2,"why":"You said sorry, rephrased with a full wh- question, and gave the place and the start point.","whyEs":"Dijiste perdón, reformulaste con una pregunta completa con wh- y diste el lugar y el punto de partida.","next":"n2"},{"id":"c","say":"Library. How go there?","sayEs":"Biblioteca. ¿Cómo ir allá?","tag":"question","q":1,"why":"The place is clear. The full question is 'How do I get there?'","whyEs":"El lugar es claro. La pregunta completa es 'How do I get there?'","next":"n2"}]},"n3":{"who":"npc","say":"Yes, left at the bakery. It is a ten-minute walk, and the library is the tall brick building.","sayEs":"Sí, a la izquierda en la panadería. Son diez minutos caminando y la biblioteca es el edificio alto de ladrillo.","mood":"neutral","choices":[{"id":"a","say":"Two blocks, then left. Right?","sayEs":"¿Dos cuadras y luego a la izquierda? ¿Cierto?","tag":"clarify","q":1,"why":"'Right?' checks your understanding, but include more of the route so she can correct any mistake.","whyEs":"'Right?' confirma tu comprensión, pero incluye más de la ruta para que ella pueda corregir cualquier error.","next":"n4"},{"id":"b","say":"Okay, okay. I will find it myself.","sayEs":"Sí, sí. Lo encontraré yo solo.","tag":"clarify","q":0,"why":"Walking away without checking can lead to a wrong turn. Repeat the steps to confirm them.","whyEs":"Irte sin confirmar puede llevar a una vuelta equivocada. Repite los pasos para confirmarlos.","next":"r2"},{"id":"c","say":"Let me make sure I understand: two blocks down Maple Street, left at the bakery, then the brick building?","sayEs":"Déjeme confirmar que entendí: dos cuadras por la calle Maple, izquierda en la panadería y luego el edificio de ladrillo.","tag":"clarify","q":2,"why":"'Let me make sure I understand' introduces a summary of every step, so she can confirm or fix it.","whyEs":"'Let me make sure I understand' introduce un resumen de cada paso para que ella lo confirme o lo corrija.","next":"n4"}]},"r2":{"who":"npc","say":"I do not want you to get lost. Shall I say the directions one more time, slowly?","sayEs":"No quiero que te pierdas. ¿Digo las indicaciones una vez más, despacio?","mood":"concerned","choices":[{"id":"a","say":"Yes. Slow, please.","sayEs":"Sí. Despacio, por favor.","tag":"clarify","q":1,"why":"You accepted and said please. Add 'Yes, please say them slowly' for a complete reply.","whyEs":"Aceptaste y dijiste please. Agrega 'Yes, please say them slowly' para una respuesta completa.","next":"n4"},{"id":"b","say":"No. You are confusing me.","sayEs":"No. Me está confundiendo.","tag":"clarify","q":0,"why":"Blaming her stops the help. Ask for a slower repeat and repeat each step back.","whyEs":"Culparla detiene la ayuda. Pide que repita más despacio y repite cada paso.","next":"e3"},{"id":"c","say":"Yes, please. Could you say them slowly while I repeat each step?","sayEs":"Sí, por favor. ¿Podría decirlas despacio mientras yo repito cada paso?","tag":"clarify","q":2,"why":"You asked for slow speech with 'Could you' and offered a way to check: repeating each step.","whyEs":"Pediste que hable despacio con 'Could you' y ofreciste una forma de comprobar: repetir cada paso.","next":"n4"}]},"n4":{"who":"npc","say":"Good, you have it now. The park is across the street from the library. Do you have any other questions?","sayEs":"Bien, ya lo tienes. El parque está frente a la biblioteca. ¿Tienes alguna otra pregunta?","mood":"pleased","choices":[{"id":"a","say":"No. This took a long time.","sayEs":"No. Esto tomó mucho tiempo.","tag":"thank","q":0,"why":"Complaining about the time is unkind. She stopped to help you.","whyEs":"Quejarte del tiempo no es amable. Ella se detuvo para ayudarte.","next":"e3"},{"id":"b","say":"No, that is all. Thank you for taking the time to help me. Have a nice day!","sayEs":"No, eso es todo. Gracias por tomarse el tiempo de ayudarme. ¡Que tenga un buen día!","tag":"thank","q":2,"why":"You thanked her for her time, which is specific, and ended with a kind wish.","whyEs":"Le agradeciste por su tiempo, lo cual es específico, y terminaste con un buen deseo.","next":"e1"},{"id":"c","say":"No. Thanks. Bye.","sayEs":"No. Gracias. Adiós.","tag":"thank","q":1,"why":"Polite but short. Adding what you are thankful for sounds warmer.","whyEs":"Cortés pero corto. Agregar por qué agradeces suena más cálido.","next":"e2"}]},"e1":{"who":"npc","say":"You are very welcome! Enjoy the library, and have a wonderful day.","sayEs":"¡De nada! Disfruta la biblioteca y que tengas un día maravilloso.","mood":"happy","end":true,"outcome":"strong","wrap":"You asked politely, checked each step, and thanked her. Clarifying kept you from getting lost.","wrapEs":"Preguntaste con cortesía, confirmaste cada paso y le diste las gracias. Aclarar evitó que te perdieras."},"e2":{"who":"npc","say":"Okay. Good luck finding it!","sayEs":"Muy bien. ¡Buena suerte para encontrarla!","mood":"neutral","end":true,"outcome":"ok","wrap":"You can probably find the library, but a fuller summary of the steps and a specific thank you would be safer and kinder.","wrapEs":"Probablemente encuentres la biblioteca, pero un resumen más completo de los pasos y un agradecimiento específico sería más seguro y amable."},"e3":{"who":"npc","say":"I hope you find it. Please ask someone else if you get lost.","sayEs":"Espero que la encuentres. Por favor, pregunta a otra persona si te pierdes.","mood":"concerned","end":true,"outcome":"retry","wrap":"The talk ended without clear directions. Ask politely, check each step, and thank the person who helps.","wrapEs":"La conversación terminó sin indicaciones claras. Pregunta con cortesía, confirma cada paso y agradece a quien te ayuda."}}},
];
